import type { SpikeStatus, SpikeSummary } from '@magic-ingredients/tiny-brain-core';
import { Zap } from 'lucide-react';
import SpikeCard from './SpikeCard';

// Re-export so consumers in this package don't have to know the
// type lives across the workspace boundary. One source of truth in
// core; the dashboard treats it as part of its own surface.
export type { SpikeSummary } from '@magic-ingredients/tiny-brain-core';

export interface SpikesListProps {
  spikes: SpikeSummary[];
  selectedSpikeId: string | null;
  onSelectSpike: (spikeId: string) => void;
}

/**
 * Sort key ordering — mirrors FixList's status-first sort so the
 * sidebar UX is symmetric across tabs. In-progress floats to the top,
 * not-started next, terminal statuses sink. Within each bucket the
 * pre-sorted server order (created-desc) is preserved.
 */
const STATUS_GROUP_ORDER: Record<SpikeStatus, number> = {
  in_progress: 0,
  not_started: 1,
  validated: 2,
  invalidated: 2,
  abandoned: 2,
};

export function SpikesList({ spikes, selectedSpikeId, onSelectSpike }: SpikesListProps) {
  if (spikes.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-12 px-4">
        <Zap className="h-12 w-12 text-muted-foreground mb-3" aria-hidden="true" />
        <p className="text-text-secondary text-center font-medium">No spikes yet</p>
        <p className="text-text-tertiary text-sm text-center mt-2">
          Use the <code className="font-mono">/spike</code> skill in Claude to
          scaffold a new time-boxed exploration.
        </p>
      </div>
    );
  }

  // V8's Array.prototype.sort is stable, so a same-bucket pair stays
  // in the server's pre-sort order (created-desc) — one-line subtraction
  // is enough.
  const sorted = [...spikes].sort(
    (a, b) => STATUS_GROUP_ORDER[a.status] - STATUS_GROUP_ORDER[b.status],
  );

  return (
    <div className="p-3 space-y-2" role="list" aria-label="Spikes">
      {sorted.map((spike) => (
        <SpikeCard
          key={spike.id}
          spike={spike}
          isSelected={spike.id === selectedSpikeId}
          onClick={() => onSelectSpike(spike.id)}
        />
      ))}
    </div>
  );
}
