import { Settings, Star } from 'lucide-react';
import { cn } from '@/lib/utils';

/** The three parallel work areas surfaced as sibling tabs. */
export type WorkArea = 'plans' | 'fixes' | 'spikes';

export interface WorkAreaCount {
  /** Items currently in progress. */
  inProgress: number;
  /** Total — every item except archived ones (completed/superseded items
   *  still count; only archived, hidden-by-default items are excluded). */
  total: number;
}

export interface StageRailProps {
  /**
   * The currently selected work area, or `null` when a non-work-area view
   * (Quality or Settings) is showing and no tab should appear selected.
   */
  activeTab: WorkArea | null;
  /** Select a work area. */
  onTabSelect: (tab: WorkArea) => void;
  /** Per-area counts rendered inside each tab. */
  counts: Record<WorkArea, WorkAreaCount>;
  /** Open the Quality view (sparkline = quality over time). */
  onQualitySelect?: () => void;
  /** Whether this repo is starred (the star renders filled + pressed). */
  isStarred?: boolean;
  /** Toggle the repo's starred state. */
  onToggleStar?: () => void;
  /** Open the repo-scoped Settings. */
  onSettings?: () => void;
  /** Whether the Settings view is the active one (renders the control raised). */
  settingsActive?: boolean;
  className?: string;
}

// Shared hover treatment for the rail's controls — text lifts to foreground,
// matching the mockups (no resting or hover background on the rail itself).
const HOVER = 'hover:text-foreground';

const TABS: ReadonlyArray<{ area: WorkArea; label: string }> = [
  { area: 'plans', label: 'Plans' },
  { area: 'fixes', label: 'Fixes' },
  { area: 'spikes', label: 'Spikes' },
];

function QualitySparkline() {
  return (
    <svg
      className="h-4 w-12"
      viewBox="0 0 48 16"
      fill="none"
      aria-hidden="true"
      data-testid="quality-sparkline"
    >
      <defs>
        <linearGradient id="stage-rail-qspark" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0" stopColor="var(--color-pink)" />
          <stop offset="1" stopColor="var(--color-blue)" />
        </linearGradient>
      </defs>
      <polyline
        points="2,12 8,13 14,9 21,10 27,6 34,7 40,3 46,2"
        stroke="url(#stage-rail-qspark)"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <circle cx="46" cy="2.5" r="1.6" fill="var(--color-blue)" />
    </svg>
  );
}

function TabCount({ count }: { count: WorkAreaCount }) {
  return (
    <span className="mono flex items-center gap-1 text-[11px] font-normal">
      <span>
        {count.total}&nbsp;<span className="font-sans text-muted-foreground">total</span>
      </span>
      <span className="text-border-strong" aria-hidden="true">
        ·
      </span>
      <span>
        {count.inProgress}&nbsp;<span className="font-sans text-muted-foreground">in progress</span>
      </span>
    </span>
  );
}

/**
 * The repo workspace stage rail from the UI Refresh mockups:
 * a Quality control with a gradient sparkline, the parallel Plans/Fixes/Spikes
 * work-area tablist carrying per-area counts, and right-aligned star toggle
 * and repo Settings controls.
 */
export function StageRail({
  activeTab,
  onTabSelect,
  counts,
  onQualitySelect,
  isStarred = false,
  onToggleStar,
  onSettings,
  settingsActive = false,
  className,
}: StageRailProps) {
  return (
    <section className={cn('px-3 pb-4', className)} aria-label="Plan stages">
      <div className="flex flex-wrap items-center gap-x-2 gap-y-2">
        {/* Quality (left) · sparkline = quality over time */}
        <button
          type="button"
          onClick={onQualitySelect}
          className={cn(
            'flex items-center gap-2 rounded-lg px-2.5 py-2 text-sm text-muted-foreground transition-colors',
            HOVER,
          )}
        >
          Quality
          <QualitySparkline />
        </button>

        {/* Divider between Quality and the work-area group */}
        <span className="h-7 w-px self-center bg-border-strong" aria-hidden="true" />

        {/* Parallel tab group (siblings) · grey segmented-control treatment from
            the mockups: a muted container with a raised white pill for the
            active work area. */}
        <div
          role="tablist"
          aria-label="Work areas"
          className="flex items-stretch gap-0.5 rounded-xl border border-border bg-[color-mix(in_oklab,var(--muted),var(--border)_30%)] p-1 text-sm"
        >
          {TABS.map(({ area, label }, index) => {
            const isActive = activeTab === area;
            return (
              <div key={area} className="flex items-stretch">
                {index > 0 && (
                  <span className="my-1.5 w-px self-stretch bg-border-strong" aria-hidden="true" />
                )}
                <button
                  type="button"
                  role="tab"
                  aria-selected={isActive}
                  onClick={() => onTabSelect(area)}
                  className={cn(
                    'flex items-center gap-2.5 rounded-lg px-3 py-1.5 transition-colors',
                    isActive
                      ? 'bg-background font-semibold text-foreground shadow-sm'
                      : 'text-muted-foreground hover:bg-background/60 hover:text-foreground',
                  )}
                >
                  {label}
                  <TabCount count={counts[area]} />
                </button>
              </div>
            );
          })}
        </div>

        {/* Repo controls (right-aligned) · star toggle + Settings */}
        <div className="ml-auto flex items-center gap-1">
          <button
            type="button"
            title="Star this repo"
            aria-label="Star this repo"
            aria-pressed={isStarred}
            onClick={onToggleStar}
            className={cn(
              'flex items-center rounded-lg px-2 py-2 transition-colors',
              isStarred ? 'text-blue' : 'text-muted-foreground',
              HOVER,
            )}
          >
            <Star className={cn('h-4 w-4', isStarred && 'fill-current')} />
          </button>
          <button
            type="button"
            onClick={onSettings}
            aria-current={settingsActive ? 'page' : undefined}
            className={cn(
              'flex items-center gap-2 rounded-lg px-2.5 py-2 text-sm transition-colors',
              settingsActive
                ? 'bg-background font-semibold text-foreground shadow-sm'
                : cn('text-muted-foreground', HOVER),
            )}
          >
            <Settings className="h-4 w-4" />
            Settings
          </button>
        </div>
      </div>
    </section>
  );
}

export default StageRail;
