// Fix-related APIs
export async function fetchFixContent(repoId: string, fixId: string): Promise<string> {
  const response = await fetch(`${API_BASE}/repos/${repoId}/fixes/${fixId}`);
  if (!response.ok) {
    throw new Error('Failed to fetch fix content');
  }
  const data = await response.json();
  return data.fix?.content ?? '';
}

