// Credentials and authentication APIs
export async function getStoredCredentials(): Promise<{ clientId: string | null; clientSecret: string | null }> {
  const response = await fetch(`${API_BASE}/config/credentials`);
  if (!response.ok) {
    return { clientId: null, clientSecret: null };
  }
  const data = await response.json();

  // Note: clientSecret will be "[STORED]" if it exists, or null if not
  // We need to check if it exists, not use the actual value
  return {
    clientId: data.clientId,
    clientSecret: data.clientSecret === '[STORED]' ? '[STORED]' : null
  };
}

export async function saveCredentials(clientId: string, clientSecret: string) {
  const response = await fetch(`${API_BASE}/config/credentials`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ clientId, clientSecret }),
  });
  if (!response.ok) {
    throw new Error('Failed to save credentials');
  }
  return response.json();
}

export async function testLibraryConnection(clientId: string, clientSecret: string) {
  const response = await fetch(`${API_BASE}/library/test`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ clientId, clientSecret }),
  });
  if (!response.ok) {
    throw new Error('Failed to test library connection');
  }
  return response.json();
}

export async function authenticateLibrary(clientId: string, clientSecret: string): Promise<{ success: boolean; token?: string; error?: string }> {
  const response = await fetch(`${API_BASE}/library/authenticate`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ clientId, clientSecret }),
  });
  if (!response.ok && response.status !== 401) {
    throw new Error('Failed to authenticate with library');
  }
  return response.json();
}