import React from 'react';
import { cn } from '@/lib/utils';
import WorktreePill from './WorktreePill';
import { GradientProgress } from './ui/GradientProgress';
import type { SpikeSummary } from '@magic-ingredients/tiny-brain-core';
import {
  SPIKE_STATUS_ICON,
  SPIKE_STATUS_LABEL,
  SPIKE_STATUS_STYLES,
  SPIKE_TERMINAL_STATUSES,
} from './spike-status';

interface SpikeCardProps {
  spike: SpikeSummary;
  isSelected: boolean;
  onClick: () => void;
}

// Short relative-time readout for the card footer — the spike analogue of
// PlanCard / FixCard's "2h ago". Coarse buckets are all the sidebar needs.
function formatRelativeTime(dateStr: string | null | undefined): string | null {
  if (!dateStr) return null;
  const diffMs = Date.now() - new Date(dateStr).getTime();
  const mins = Math.floor(diffMs / 60000);
  if (mins < 1) return 'just now';
  if (mins < 60) return `${mins}m ago`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  if (days < 7) return `${days}d ago`;
  if (days < 30) return `${Math.floor(days / 7)}w ago`;
  if (days < 365) return `${Math.floor(days / 30)}mo ago`;
  return `${Math.floor(days / 365)}y ago`;
}

const TIMEBOX_PATTERN = /^\s*(\d+(?:\.\d+)?)\s*([smhdw])\s*$/i;
const UNIT_MS: Record<string, number> = {
  s: 1_000,
  m: 60_000,
  h: 3_600_000,
  d: 86_400_000,
  w: 604_800_000,
};

// Fraction of the timebox elapsed (0–100), or null if the timebox string
// isn't one the schema ratified. Drives the open-spike progress bar — spikes
// carry no per-task completion in the summary, so (like the mockup) the bar
// tracks time spent, not work done.
function timeboxElapsedPercent(created: string, timebox: string): number | null {
  const match = TIMEBOX_PATTERN.exec(timebox);
  if (!match) return null;
  const totalMs = Number(match[1]) * UNIT_MS[match[2].toLowerCase()];
  if (!Number.isFinite(totalMs) || totalMs <= 0) return null;
  const elapsedMs = Date.now() - new Date(created).getTime();
  return Math.min(100, Math.max(0, (elapsedMs / totalMs) * 100));
}

const SpikeCard: React.FC<SpikeCardProps> = ({ spike, isSelected, onClick }) => {
  const isTerminal = SPIKE_TERMINAL_STATUSES.has(spike.status);
  const isInProgress = spike.status === 'in_progress';
  const StatusIcon = SPIKE_STATUS_ICON[spike.status];

  const taskCount = spike.tasks?.length ?? 0;
  const relativeCreated = formatRelativeTime(spike.created);
  const elapsedPercent = isInProgress ? timeboxElapsedPercent(spike.created, spike.timebox) : null;

  return (
    <div
      data-testid="spike-card"
      data-selected={isSelected}
      data-status={spike.status}
      role="button"
      tabIndex={0}
      onClick={onClick}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onClick();
        }
      }}
      className={cn(
        'plan-card-surface lift rise relative block cursor-pointer overflow-hidden rounded-2xl p-4 pl-5 hover:bg-accent/30',
        isSelected && 'plan-card-accent panel',
      )}
    >
      <div className="flex items-start justify-between gap-2">
        <h3
          className={cn(
            'display text-[15px] leading-snug line-clamp-2',
            isInProgress || isSelected ? 'font-semibold' : 'font-medium',
          )}
        >
          {spike.title}
        </h3>
      </div>

      <div className="mt-2.5 flex items-center gap-2">
        <span
          data-testid={`spike-status-${spike.id}`}
          data-status={spike.status}
          className={cn(
            'inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-[11px] font-medium whitespace-nowrap',
            SPIKE_STATUS_STYLES[spike.status],
          )}
        >
          {StatusIcon ? (
            <StatusIcon className="h-3 w-3" aria-hidden="true" />
          ) : (
            <span className="h-1.5 w-1.5 rounded-full bg-current" aria-hidden="true" />
          )}
          {SPIKE_STATUS_LABEL[spike.status]}
        </span>
        {isTerminal && <span className="mono ml-auto text-[11px] text-muted-foreground">done</span>}
      </div>

      {elapsedPercent !== null && <GradientProgress value={elapsedPercent} className="mt-3" />}

      <div className="mono mt-3 flex items-center justify-between gap-2 text-[11px] text-muted-foreground">
        <span>
          {taskCount} <span className="font-sans">{taskCount === 1 ? 'task' : 'tasks'}</span>
          {' · '}
          <span>{spike.timebox}</span> <span className="font-sans">timebox</span>
        </span>
        <div className="flex items-center gap-2">
          {spike.worktree && (
            <WorktreePill
              branches={[
                { branch: spike.worktree.branch, hasWorktree: true, worktreeName: spike.worktree.name },
              ]}
            />
          )}
          {relativeCreated && <span className="font-sans">{relativeCreated}</span>}
        </div>
      </div>
    </div>
  );
};

export default SpikeCard;
