/**
 * StarredReposSection — sidebar listing of user-starred repos.
 *
 * Sits in the sidebar layout under the static "Code → Repos" row.
 * Implemented as a sibling section since AppSidebar has no nested
 * children today; visual outcome is equivalent.
 *
 * Clicking an item routes to `/repos/<id>` — same as clicking the
 * card on the Repos page. Hover or focus reveals an unstar control
 * that DELETEs the star and optimistically removes the item.
 *
 * Listens for `repo-starred-changed` SSE events so star/unstar
 * actions performed elsewhere (the Repos page card, another tab)
 * surface here without a manual reload.
 */

import { useCallback, useEffect, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Star } from 'lucide-react';
import { cn } from '@/lib/utils';
import { SELECTED_ITEM_BG } from './sidebarTokens';

/**
 * Custom DOM event used to sync star/unstar between the Repos page
 * card and this sidebar. Lighter than threading SSE through the
 * core-owned event union; both surfaces live in the same window.
 */
export const REPO_STARRED_CHANGED_EVENT = 'repo-starred-changed';

interface StarredRepo {
  id: string;
  name: string;
  starred?: boolean;
}

function isStarredRepo(value: unknown): value is StarredRepo {
  if (typeof value !== 'object' || value === null) return false;
  const v = value as Record<string, unknown>;
  return typeof v.id === 'string' && typeof v.name === 'string';
}

export function StarredReposSection() {
  const navigate = useNavigate();
  const location = useLocation();
  const [repos, setRepos] = useState<StarredRepo[]>([]);
  const [pendingIds, setPendingIds] = useState<ReadonlySet<string>>(() => new Set());

  const refetch = useCallback(async () => {
    try {
      const response = await fetch('/api/repos');
      if (!response.ok) return;
      const data: unknown = await response.json();
      const list = (data as { repos?: unknown }).repos;
      if (!Array.isArray(list)) return;
      setRepos(list.filter(isStarredRepo).filter((r) => r.starred));
    } catch (err) {
      console.error('[StarredReposSection] Failed to load repos:', err);
    }
  }, []);

  useEffect(() => {
    void refetch();
  }, [refetch]);

  // Live sync — when star/unstar fires anywhere in this window
  // (Repos page card, this sidebar, etc.), refetch so the sidebar
  // reflects the latest state without a manual reload.
  useEffect(() => {
    const handler = () => {
      void refetch();
    };
    window.addEventListener(REPO_STARRED_CHANGED_EVENT, handler);
    return () => window.removeEventListener(REPO_STARRED_CHANGED_EVENT, handler);
  }, [refetch]);

  if (repos.length === 0) return null;

  const handleUnstar = async (repo: StarredRepo, index: number) => {
    if (pendingIds.has(repo.id)) return;

    // If the user just unstarred the repo they're currently viewing,
    // navigate back to the repos list — the detail page they're on
    // is fine to leave behind, and the sidebar entry for it is going
    // away.
    if (location.pathname === `/repos/${repo.id}`) {
      navigate('/repos');
    }

    // Optimistic — remove from sidebar immediately. Capture the
    // original index so a rollback restores the same position.
    setRepos((prev) => prev.filter((r) => r.id !== repo.id));
    setPendingIds((prev) => {
      const out = new Set(prev);
      out.add(repo.id);
      return out;
    });
    try {
      const response = await fetch(`/api/repos/${repo.id}/star`, { method: 'DELETE' });
      if (!response.ok) {
        // Roll back to the original position so the visual order is preserved.
        setRepos((prev) => {
          const restored = [...prev];
          restored.splice(index, 0, repo);
          return restored;
        });
      } else {
        // Notify other surfaces (Repos page card) so they refresh.
        window.dispatchEvent(new CustomEvent(REPO_STARRED_CHANGED_EVENT));
      }
    } catch (err) {
      console.error('[StarredReposSection] Failed to unstar:', err);
      setRepos((prev) => {
        const restored = [...prev];
        restored.splice(index, 0, repo);
        return restored;
      });
    } finally {
      setPendingIds((prev) => {
        const out = new Set(prev);
        out.delete(repo.id);
        return out;
      });
    }
  };

  return (
    // No section header — the items render as visually-nested children of the
    // parent "Repos" sidebar item: a left border rail, plain repo names, and an
    // unstar control that only appears on row hover/focus (matching the mockup's
    // clean text list).
    <ul
      data-testid="starred-repos-section"
      className="mt-1.5 ml-2 space-y-0.5 border-l border-border pl-3"
    >
      {repos.map((repo, index) => {
        // Highlight the current selection — clicking a starred-repo
        // item from the sidebar leads to /repos/<id>; mirror the
        // Repos-page selection visually so the active row is obvious.
        const isActive = location.pathname === `/repos/${repo.id}`;
        return (
          <li key={repo.id}>
            <div
              data-testid={`starred-repo-item-${repo.id}`}
              data-active={isActive ? 'true' : 'false'}
              role="button"
              tabIndex={0}
              aria-current={isActive ? 'page' : undefined}
              onClick={() => navigate(`/repos/${repo.id}`)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  e.preventDefault();
                  navigate(`/repos/${repo.id}`);
                }
              }}
              className={cn(
                'group flex cursor-pointer items-center gap-2 rounded-md px-2 py-1.5 text-sm transition-colors',
                isActive
                  ? 'font-medium text-blue'
                  : 'font-normal text-subtle hover:bg-[color-mix(in_oklab,var(--ds-fg)_5%,transparent)] hover:text-foreground focus-within:bg-[color-mix(in_oklab,var(--ds-fg)_5%,transparent)]',
              )}
              style={isActive ? { background: SELECTED_ITEM_BG } : undefined}
            >
              <span className="flex-1 truncate text-left">{repo.name}</span>
              {/* Unstar — revealed on row hover/focus so the default list reads as
                  plain text (per the mockup). Stop propagation so the row's
                  navigate doesn't fire. */}
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  void handleUnstar(repo, index);
                }}
                aria-label={`Unstar ${repo.name} from sidebar`}
                className="flex-shrink-0 rounded p-0 text-subtle opacity-0 transition-opacity hover:text-blue focus-visible:opacity-100 group-hover:opacity-100 group-focus-within:opacity-100"
              >
                <Star className="h-3.5 w-3.5" fill="currentColor" />
              </button>
            </div>
          </li>
        );
      })}
    </ul>
  );
}
