// root barrel (`@magic-ingredients/tiny-brain-core`) transitively pulls Node-only
// modules (storage-path-builder → `path`) that Vite externalises, which crashes
// in the browser. The type imports are erased, so they can stay on the root.
// Import values from the browser-safe subpath, NOT the package root: the root
// barrel transitively pulls Node-only modules (storage-path-builder → `path`)
// that Vite externalises, crashing the browser. taskRefsMatch is the canonical
// join shared with the server projector — re-exported from this subpath so the
// rule isn't duplicated here. Type imports are erased, so they can stay on root.
import { deriveTaskStateFromEvents, taskRefsMatch } from '@magic-ingredients/tiny-brain-core/derive-task-state';
import type { TelemetryEvent, TelemetryTaskRef, DerivedTaskState } from '@magic-ingredients/tiny-brain-core';
import type { Fix, Plan } from '../types';

/**
 * Derive a single task's live overlay from the repo telemetry feed: filter the
 * feed to that task's events (strict ref join, mirroring the server projector)
 * and reduce them with the shared core `deriveTaskStateFromEvents`. Returns
 * undefined when the task has no events, so callers can leave it untouched.
 *
 * This is the shared primitive behind every surface's live overlay — pills
 * (plan/fix/spike) and the timeline. Because the feed rides the
 * `telemetryChange` SSE stream, a pre-commit phase change (e.g.
 * `phase.entered{red}`, which lands no git commit) surfaces here without a
 * refetch. Git stays the source of truth for status/SHAs.
 */
export function deriveTaskOverlay(
  events: readonly TelemetryEvent[],
  ref: TelemetryTaskRef,
): DerivedTaskState | undefined {
  const matched = filterTaskEvents(events, ref);
  return matched.length > 0 ? deriveTaskStateFromEvents(matched) : undefined;
}

/**
 * Filter the repo telemetry feed to a single task's events (strict ref join,
 * mirroring the server projector). The shared primitive behind both the pill
 * overlay (via deriveTaskOverlay) and the task detail timeline, so every
 * surface joins telemetry to a task the same way.
 */
export function filterTaskEvents(
  events: readonly TelemetryEvent[],
  ref: TelemetryTaskRef,
): TelemetryEvent[] {
  return events.filter((e) => taskRefsMatch(e.taskRef, ref));
}

/**
 * Overlay the telemetry feed onto a plan's PRD task rows (shallow-clones the
 * plan/feature/task tree, stamping each stamped task's `derivedState`). Returns
 * the same plan reference untouched when there are no events.
 */
export function overlayPlanTasksWithTelemetry(
  plan: Plan,
  events: readonly TelemetryEvent[],
): Plan {
  if (events.length === 0 || !plan.prdId || !plan.features?.length) return plan;
  const prdId = plan.prdId;

  return {
    ...plan,
    features: plan.features.map((feature) => ({
      ...feature,
      tasks: feature.tasks?.map((task) => {
        if (!task.uuid) return task;
        const derived = deriveTaskOverlay(events, { kind: 'prd', prd: prdId, feature: feature.id, task: task.uuid });
        return derived ? { ...task, derivedState: derived } : task;
      }),
    })),
  };
}

/**
 * Overlay the telemetry feed onto a fix's task rows (fixes have a flat task
 * list, no features). Returns the same fix reference untouched when there are
 * no events.
 */
export function overlayFixTasksWithTelemetry(
  fix: Fix,
  events: readonly TelemetryEvent[],
): Fix {
  if (events.length === 0 || !fix.tasks?.length) return fix;

  return {
    ...fix,
    tasks: fix.tasks.map((task) => {
      if (!task.uuid) return task;
      const derived = deriveTaskOverlay(events, { kind: 'fix', fix: fix.id, task: task.uuid });
      return derived ? { ...task, derivedState: derived } : task;
    }),
  };
}
