import type { QualityIssue, CategoryScore } from '../types';

export const CATEGORY_WEIGHTS: Record<string, number> = {
  Security: 15,
  Reliability: 10,
  Performance: 10,
  Maintainability: 5,
  Testing: 5,
  Architecture: 5,
  Documentation: 3,
  Operations: 3,
};

export const SEVERITY_MULTIPLIERS: Record<string, number> = {
  critical: 1.0,
  major: 0.7,
  minor: 0.3,
  info: 0.0,
};

function getGrade(scorePercentage: number): string {
  if (scorePercentage >= 90) return 'A';
  if (scorePercentage >= 80) return 'B';
  if (scorePercentage >= 70) return 'C';
  if (scorePercentage >= 60) return 'D';
  return 'F';
}

export function calculateCategoryScores(issues: QualityIssue[]): CategoryScore[] {
  if (issues.length === 0) {
    return [];
  }

  const scores: CategoryScore[] = [];

  for (const [category, maxWeight] of Object.entries(CATEGORY_WEIGHTS)) {
    const categoryIssues = issues.filter(issue => issue.category === category);

    if (categoryIssues.length === 0) {
      continue;
    }

    let deduction = 0;
    for (const issue of categoryIssues) {
      const multiplier = SEVERITY_MULTIPLIERS[issue.severity] ?? 0;
      deduction += maxWeight * multiplier;
    }

    const scorePercentage = Math.max(0, Math.min(100, ((maxWeight - deduction) / maxWeight) * 100));
    const grade = getGrade(scorePercentage);

    scores.push({
      category,
      issueCount: categoryIssues.length,
      deduction,
      maxWeight,
      grade,
    });
  }

  return scores;
}
