import type { SpikeStatus } from '@magic-ingredients/tiny-brain-core';
import { Check, CircleHelp, X, type LucideIcon } from 'lucide-react';

/**
 * Per-status pill background/border/text styles on the refreshed
 * design-system tokens (per the spikes-console mockup). The terminal
 * statuses read as outcomes: validated is the positive "Viable" green
 * (`done`), invalidated is the destructive "Not viable" red
 * (`destructive` → phase-red), abandoned is the neutral-warning
 * "Inconclusive" amber (`warn`). in_progress is the live blue "Open";
 * not_started is neutral. Every status resolves to a `--color-*` design
 * token. Single source of truth so the list card, the detail badge and
 * any future spike UI share one palette.
 */
export const SPIKE_STATUS_STYLES: Record<SpikeStatus, string> = {
  not_started: 'bg-muted text-muted-foreground border-border',
  in_progress: 'bg-blue/10 text-blue border-blue/30',
  validated: 'bg-done/10 text-done border-done/30',
  invalidated: 'bg-destructive/10 text-destructive border-destructive/30',
  abandoned: 'bg-warn/10 text-warn border-warn/30',
};

/**
 * The dot colour used by SpikeDetail's Badge for the non-terminal
 * statuses (terminal statuses carry an outcome icon instead — see
 * SPIKE_STATUS_ICON). On the design-system colour tokens.
 */
export const SPIKE_STATUS_DOT_COLORS: Record<SpikeStatus, string> = {
  not_started: 'bg-muted-foreground',
  in_progress: 'bg-blue',
  validated: 'bg-done',
  invalidated: 'bg-destructive',
  abandoned: 'bg-warn',
};

/**
 * Outcome glyph per terminal status (check / x / circle-help, per the
 * mockup). Non-terminal statuses have no icon — they render a status
 * dot instead.
 */
export const SPIKE_STATUS_ICON: Record<SpikeStatus, LucideIcon | null> = {
  not_started: null,
  in_progress: null,
  validated: Check,
  invalidated: X,
  abandoned: CircleHelp,
};

/**
 * Reader-facing status labels. The refreshed spikes console reframes
 * the raw enum statuses as outcomes (validated → "Viable", invalidated
 * → "Not viable", abandoned → "Inconclusive") and shows in_progress as
 * "Open".
 */
export const SPIKE_STATUS_LABEL: Record<SpikeStatus, string> = {
  not_started: 'Not started',
  in_progress: 'Open',
  validated: 'Viable',
  invalidated: 'Not viable',
  abandoned: 'Inconclusive',
};

export const SPIKE_TERMINAL_STATUSES = new Set<SpikeStatus>([
  'validated',
  'invalidated',
  'abandoned',
]);

/**
 * Narrow an arbitrary string to a known SpikeStatus, falling back to
 * `not_started` for anything unrecognised. SpikeDetail's input
 * `SpikeProgress.status` is widened to `SpikeStatus | string` in core
 * (the projector reads a git-sourced status that may predate the enum);
 * narrowing here keeps the status maps total. Without the fallback an
 * unknown status would index a map with `undefined` and render a blank
 * badge with no visual signal. (SpikeSummary.status is already the strict
 * enum, so SpikeCard needs no narrowing.)
 */
export function narrowSpikeStatus(s: string): SpikeStatus {
  return (s in SPIKE_STATUS_LABEL ? s : 'not_started') as SpikeStatus;
}
