import React from 'react';
import type { Instrument } from '../utils/quality-instruments';
import type { TrendColour } from '../utils/instrument-trend';
import type { VitalState } from '../utils/quality-posture';

/** A placeholder instrument has no risk direction, so its dot is `flat` — a
 *  fourth, neutral state alongside the three VitalStates. */
type DotState = VitalState | 'flat';

const DOT_COLOR: Record<DotState, string> = {
  ok: 'var(--color-done)',
  watch: 'var(--color-warn)',
  risk: 'var(--color-phase-red)',
  flat: 'var(--color-border-strong)',
};

const TREND_COLOR: Record<TrendColour, string> = {
  good: 'var(--color-done)',
  bad: 'var(--color-phase-red)',
  neutral: 'var(--color-border-strong)',
};

const SPARK_W = 72;
const SPARK_H = 24;
const SPARK_PAD = 3;

/** Map a series to a polyline `points` string within the sparkline viewbox. */
function sparklinePoints(series: ReadonlyArray<number>): string {
  if (series.length < 2) return '';
  const min = Math.min(...series);
  const max = Math.max(...series);
  const range = max - min || 1;
  const usableW = SPARK_W - SPARK_PAD * 2;
  const usableH = SPARK_H - SPARK_PAD * 2;
  return series
    .map((v, i) => {
      const x = SPARK_PAD + (i / (series.length - 1)) * usableW;
      const y = SPARK_PAD + usableH - ((v - min) / range) * usableH;
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(' ');
}

function InstrumentCard({ instrument }: { instrument: Instrument }) {
  const points = instrument.series ? sparklinePoints(instrument.series) : '';
  // A placeholder slot has no run data yet: a neutral (flat) dot and a muted
  // value, so it reads as "not measured" rather than a real low number.
  const dotState: DotState = instrument.placeholder ? 'flat' : instrument.dotState ?? 'flat';
  return (
    <div
      data-testid={`instrument-${instrument.key}`}
      data-placeholder={instrument.placeholder ? 'true' : undefined}
      className="rounded-2xl border border-border bg-muted/30 p-4"
    >
      <div className="flex items-center justify-between">
        <p className="eyebrow text-[10px] text-subtle">{instrument.label}</p>
        <span
          data-testid={`instrument-dot-${instrument.key}`}
          data-state={dotState}
          className="h-1.5 w-1.5 rounded-full"
          style={{ background: DOT_COLOR[dotState] }}
          aria-hidden
        />
      </div>
      <div className="mt-2 flex items-end justify-between gap-2">
        <span
          className={`display text-2xl font-bold leading-none${instrument.placeholder ? ' text-border-strong' : ''}`}
        >
          {instrument.value}
        </span>
        {/* The sparkline and delta render only when the instrument carries a
            series / deltaLabel. buildInstruments does not emit those yet (quality
            runs persist no per-analyser history), so today's cards show only the
            value + dot; these branches light up when that data lands. */}
        <span className="flex flex-col items-end">
          {points && (
            <svg viewBox={`0 0 ${SPARK_W} ${SPARK_H}`} className="h-6 w-16" fill="none" preserveAspectRatio="none">
              <polyline
                points={points}
                stroke={TREND_COLOR[instrument.trend.colour]}
                strokeWidth={1.5}
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          )}
          {instrument.deltaLabel && (
            <span
              data-testid={`instrument-delta-${instrument.key}`}
              data-trend={instrument.trend.colour}
              className="mono text-[10px]"
              style={{ color: TREND_COLOR[instrument.trend.colour] }}
            >
              {instrument.deltaLabel}
            </span>
          )}
        </span>
      </div>
      {instrument.sublabel && <p className="mt-2.5 text-xs text-muted">{instrument.sublabel}</p>}
    </div>
  );
}

/**
 * The Quality "Measured" section — raw analyser facts as instruments, each a
 * quantity to keep low so the trend colour is invariant (a falling line is an
 * improvement). No grades, no fill-to-100 bars.
 */
export const QualityMeasured: React.FC<{ instruments: ReadonlyArray<Instrument> }> = ({ instruments }) => {
  if (instruments.length === 0) return null;

  return (
    <section data-testid="quality-measured">
      <div className="flex items-end justify-between gap-2">
        <div>
          <h2 className="display text-base font-semibold">Measured</h2>
          <p className="text-xs text-muted">
            Raw analyser facts — each a quantity to keep low, so a falling line is improving and a
            rising line is regressing.
          </p>
        </div>
      </div>
      <div
        data-testid="quality-measured-grid"
        className="mt-3 grid gap-3 sm:grid-cols-2 lg:grid-cols-3"
      >
        {instruments.map((instrument) => (
          <InstrumentCard key={instrument.key} instrument={instrument} />
        ))}
      </div>
    </section>
  );
};
