import { useEffect, useState } from 'react';
import { AlertCircle, Loader2, CheckCircle2, ShieldCheck } from 'lucide-react';
import type { ReviewVerdict } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { useCommitDiff } from '../hooks/useCommitDiff';
import { useHunkAnchor } from '../hooks/useHunkAnchor';
import DiffFileView from './DiffFileView';

/** A single reviewer finding, as written to the on-disk adversarial review. */
interface ReviewFinding {
  description: string;
  priority?: string;
  category?: string;
  file?: string;
  line?: number;
  rationale?: string;
  suggestion?: string;
}

/** The adversarial review body returned by the reviews endpoint. */
interface ReviewBody {
  verdict: ReviewVerdict;
  summary?: string;
  suggestions?: ReviewFinding[];
}

interface ReviewTabProps {
  repoId: string;
  /** The review gate to render (default `'adversarial'`). Drives which
   *  `/reviews/<gate>/<sha>` body is fetched, so the same tab serves any pinned
   *  gate (e.g. `mutation-testing`). */
  gate?: string;
  /** The reviewed (green) SHA the review file is keyed by. */
  reviewedSha?: string;
  /** The refactor commit that addressed the findings, if one landed. */
  refactorCommitSha?: string;
}

const VERDICT_LABEL: Record<ReviewVerdict, string> = {
  clean: 'Clean',
  'needs-refactoring': 'Refactor required',
  failed: 'Review failed',
};

const VERDICT_COLOR: Record<ReviewVerdict, string> = {
  clean: 'var(--color-phase-green)',
  'needs-refactoring': 'var(--color-phase-review)',
  failed: 'var(--color-phase-red)',
};

/**
 * The Review tab — the adversarial review beside the refactor that answered it.
 * A rail of the reviewer's findings (fetched from the review keyed by the
 * reviewed/green SHA) beside the refactor commit's diff. Each finding anchors
 * the diff to its hunk on click. A finding pointing at a file the refactor never
 * touched is surfaced as *unresolved* — the review flagged it but no refactor
 * change addressed it — with a headline count, so the unaddressed ones stand
 * out rather than hiding among the resolved ones.
 */
export default function ReviewTab({ repoId, gate = 'adversarial', reviewedSha, refactorCommitSha }: ReviewTabProps) {
  const hasReview = !!reviewedSha && reviewedSha !== 'skipped';
  // Human label for the empty state, e.g. `mutation-testing` → "mutation testing".
  const gateLabel = gate.replace(/-/g, ' ');

  const [review, setReview] = useState<ReviewBody | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  // A 404 on the review body means "no verdict recorded yet" — the review is in
  // flight, not failed. Tracked separately from `error` so it reads as
  // in-progress rather than a load failure.
  const [pending, setPending] = useState(false);

  useEffect(() => {
    if (!hasReview) {
      setReview(null);
      setLoading(false);
      setError(null);
      setPending(false);
      return;
    }
    let cancelled = false;
    setLoading(true);
    setError(null);
    setPending(false);
    // Encode the gate — it's the newly-parameterised path segment; today's gate
    // slugs need no escaping, but encoding keeps the URL well-formed if the gate
    // source ever widens.
    fetch(`/api/repos/${repoId}/reviews/${encodeURIComponent(gate)}/${reviewedSha}`)
      .then((res) => {
        // 404 = the review body isn't on disk yet → in progress, not an error.
        if (res.status === 404) {
          if (!cancelled) setPending(true);
          return null;
        }
        if (!res.ok) throw new Error(`Failed to load review (${res.status})`);
        return res.json();
      })
      .then((data: ReviewBody | null) => {
        if (data && !cancelled) setReview(data);
      })
      .catch((e: unknown) => {
        if (!cancelled) setError(e instanceof Error ? e.message : 'Failed to load review');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [repoId, gate, reviewedSha, hasReview]);

  // The refactor diff (refactor commit vs its parent). No refactor commit ⇒ no
  // fetch ⇒ an empty diff, so every finding reads as unresolved.
  const diff = useCommitDiff(repoId, hasReview ? refactorCommitSha : undefined);

  // A finding is resolved when the refactor touched its file. File-level (not
  // line-level) so a finding still counts as addressed even though the refactor
  // shifted line numbers. Called before the early return to keep hook order
  // stable across a hasReview flip (Rules of Hooks).
  const { containerRef, selectedKey, isSelected, anchor } = useHunkAnchor(diff.files);

  if (!hasReview) {
    return (
      <div className="grid h-full place-items-center p-6 text-center">
        <p className="text-sm text-muted-foreground">
          No {gateLabel} review for this task yet — nothing has been reviewed.
        </p>
      </div>
    );
  }

  // The review body 404'd: the gate is recorded/expected but its verdict hasn't
  // landed yet — show it as in progress rather than the rail+diff (whose
  // `?? 'clean'` fallback would otherwise mislead).
  if (pending) {
    return (
      <div className="grid h-full place-items-center p-6 text-center">
        <p className="flex items-center gap-2 text-sm text-muted-foreground">
          <Loader2 className="h-4 w-4 animate-spin" />
          {gateLabel} review in progress — no verdict recorded yet.
        </p>
      </div>
    );
  }

  const verdict = review?.verdict ?? 'clean';
  const findings = review?.suggestions ?? [];
  const touchedFiles = new Set(diff.files.map((f) => f.newPath ?? f.oldPath ?? ''));
  const isResolved = (f: ReviewFinding) => !!f.file && touchedFiles.has(f.file);
  const unresolvedCount = findings.filter((f) => !isResolved(f)).length;

  return (
    <div className="grid h-full min-h-0 grid-cols-1 lg:grid-cols-[320px_minmax(0,1fr)]">
      {/* Findings rail */}
      <aside className="flex min-h-0 flex-col border-r border-border">
        <div className="flex items-center justify-between gap-2 px-4 pt-4">
          <p className="eyebrow text-[10px]" style={{ color: 'var(--color-phase-review)' }}>
            Findings
          </p>
          {/* The verdict badge only renders once a review has actually loaded —
              otherwise the `?? 'clean'` fallback would paint a green "Clean"
              badge while loading or even above a load error, a lying screen. */}
          {!loading && !error && review && (
            <span
              data-testid="review-verdict"
              className="inline-flex items-center gap-1.5 rounded-full px-2 py-0.5 text-[11px] font-medium"
              style={{
                background: `color-mix(in oklab, ${VERDICT_COLOR[verdict]} 14%, var(--background))`,
                color: VERDICT_COLOR[verdict],
              }}
            >
              <span
                className="h-1.5 w-1.5 rounded-full"
                style={{ background: VERDICT_COLOR[verdict] }}
                aria-hidden="true"
              />
              {VERDICT_LABEL[verdict]}
            </span>
          )}
        </div>

        {review?.summary && (
          <p className="px-4 pt-2 text-[13px] leading-snug text-muted-foreground">{review.summary}</p>
        )}

        {findings.length > 0 && (
          <p data-testid="review-unresolved-count" className="px-4 pt-2 mono text-[11px] text-muted-foreground">
            {unresolvedCount} unresolved · {findings.length} total
          </p>
        )}

        <div className="mt-3 min-h-0 flex-1 overflow-y-auto pb-3">
          {loading && (
            <div className="flex items-center gap-2 px-4 py-3 text-[13px] text-muted-foreground">
              <Loader2 className="h-4 w-4 animate-spin" /> Loading review…
            </div>
          )}
          {error && !loading && (
            <div className="flex items-start gap-2 px-4 py-3 text-[13px] text-red-500">
              <AlertCircle className="mt-0.5 h-4 w-4 flex-none" /> {error}
            </div>
          )}

          {!loading && !error && findings.length === 0 && (
            <div className="flex items-start gap-2 px-4 py-3 text-[13px] text-muted-foreground">
              <ShieldCheck
                className="mt-0.5 h-4 w-4 flex-none"
                style={{ color: 'var(--color-phase-green)' }}
              />
              No findings — the review came back clean.
            </div>
          )}

          {!loading &&
            !error &&
            findings.map((finding, i) => {
              const resolved = isResolved(finding);
              const canAnchor = !!finding.file && finding.line != null;
              const active =
                canAnchor && isSelected({ path: finding.file!, line: finding.line! });
              return (
                <button
                  key={`${finding.description}-${i}`}
                  type="button"
                  aria-pressed={active}
                  onClick={() =>
                    canAnchor && anchor({ path: finding.file!, line: finding.line! })
                  }
                  className="flex w-full gap-3 border-l-2 px-4 py-3 text-left transition-colors hover:bg-muted/40"
                  style={
                    active
                      ? {
                          borderLeftColor: 'var(--color-phase-review)',
                          background:
                            'color-mix(in oklab, var(--color-phase-review) 12%, transparent)',
                        }
                      : { borderLeftColor: 'transparent' }
                  }
                >
                  <span
                    className="grid h-5 w-5 flex-none place-items-center rounded-full border"
                    style={
                      resolved
                        ? {
                            color: 'var(--color-phase-green)',
                            background: 'color-mix(in oklab, var(--color-phase-green) 16%, transparent)',
                            borderColor: 'color-mix(in oklab, var(--color-phase-green) 45%, transparent)',
                          }
                        : {
                            color: 'var(--color-phase-review)',
                            background: 'color-mix(in oklab, var(--color-phase-review) 16%, transparent)',
                            borderColor: 'color-mix(in oklab, var(--color-phase-review) 45%, transparent)',
                          }
                    }
                  >
                    {resolved ? (
                      <CheckCircle2 className="h-3.5 w-3.5" />
                    ) : (
                      <AlertCircle className="h-3.5 w-3.5" />
                    )}
                  </span>
                  <div className="min-w-0 flex-1">
                    <p className="text-[13px] leading-snug">{finding.description}</p>
                    <p className="mono mt-1 flex flex-wrap items-center gap-1.5 text-[10px] text-muted-foreground">
                      {finding.file && (
                        <span className="truncate">
                          {finding.file}
                          {finding.line != null ? `:${finding.line}` : ''}
                        </span>
                      )}
                      {!resolved && (
                        <span
                          className="rounded-full px-1.5 py-0.5 font-medium"
                          style={{
                            background:
                              'color-mix(in oklab, var(--color-phase-review) 16%, transparent)',
                            color: 'var(--color-phase-review)',
                          }}
                        >
                          unresolved
                        </span>
                      )}
                    </p>
                  </div>
                </button>
              );
            })}
        </div>
      </aside>

      {/* Refactor diff */}
      <section ref={containerRef} data-testid="review-diff" className="tb-diff min-h-0 overflow-y-auto">
        {!refactorCommitSha ? (
          // Only assert "no refactor needed" once a review has actually loaded
          // clean — guarding on `!loading && !error && review` like the verdict
          // badge does, so the `?? 'clean'` fallback can't flash (or stick on,
          // after an error) a falsely-reassuring green message over a review that
          // hasn't loaded or failed to load.
          !loading && !error && review && verdict === 'clean' ? (
            <div className="flex items-start gap-2 p-4 text-sm text-muted-foreground">
              <CheckCircle2
                className="mt-0.5 h-4 w-4 flex-none"
                style={{ color: 'var(--color-phase-green)' }}
              />{' '}
              Clean review — no refactor needed.
            </div>
          ) : (
            <div className="flex items-start gap-2 p-4 text-sm text-muted-foreground">
              <AlertCircle className="mt-0.5 h-4 w-4 flex-none" /> No refactor landed — the findings
              remain unaddressed.
            </div>
          )
        ) : (
          <>
            {diff.loading && (
              <div className="flex items-center gap-2 p-4 text-sm text-muted-foreground">
                <Loader2 className="h-4 w-4 animate-spin" /> Loading diff…
              </div>
            )}
            {diff.error && (
              <div className="flex items-start gap-2 p-4 text-sm text-red-500">
                <AlertCircle className="mt-0.5 h-4 w-4 flex-none" /> {diff.error}
              </div>
            )}
            {!diff.loading &&
              !diff.error &&
              diff.files.map((file, fileIndex) => (
                <DiffFileView
                  key={`${file.newPath ?? file.oldPath ?? ''}-${fileIndex}`}
                  file={file}
                  selectedChanges={selectedKey ? [selectedKey] : []}
                />
              ))}
          </>
        )}
      </section>
    </div>
  );
}
