import React from 'react';
import { LucideIcon, PanelLeft, Settings } from 'lucide-react';
import { cn } from '@/lib/utils';
import { SELECTED_ITEM_BG } from './sidebarTokens';

export interface SidebarItem {
  id: string;
  title: string;
  icon: LucideIcon;
  /**
   * Legacy per-item accent colour. No longer used by the redesigned sidebar
   * (items share a uniform token treatment); kept optional until App.tsx stops
   * supplying it.
   */
  color?: string;
}

export interface SidebarSection {
  id: string;
  title?: string;
  subtitle?: string;
  items: SidebarItem[];
}

interface SidebarProps {
  sections: SidebarSection[];
  selectedItemId: string | null;
  onItemSelect: (itemId: string) => void;
  isCollapsed: boolean;
  onToggleCollapse: () => void;
  /**
   * Optional content rendered immediately after a specific nav item
   * (e.g. starred repos under the Repos item). Hidden when the
   * sidebar is collapsed.
   */
  renderAfterItem?: (itemId: string) => React.ReactNode;
  /** When provided, a Settings control is rendered bottom-aligned above the collapse toggle. */
  onSettingsSelect?: () => void;
  /** Whether the bottom Settings control is the current selection. */
  isSettingsSelected?: boolean;
  /**
   * The nav item whose section is active but not itself selected — e.g. "Repos"
   * while viewing a repo detail page, where the selected (blue) treatment lives
   * on the repo sub-row. Rendered emphasised (medium weight, foreground) but
   * without the blue selected styling.
   */
  activeSectionItemId?: string | null;
}

export const Sidebar: React.FC<SidebarProps> = ({
  sections,
  selectedItemId,
  onItemSelect,
  isCollapsed,
  onToggleCollapse,
  renderAfterItem,
  onSettingsSelect,
  isSettingsSelected = false,
  activeSectionItemId = null,
}) => {
  return (
    <aside
      className={cn(
        'flex h-full shrink-0 flex-col border-r border-border transition-all duration-200',
        isCollapsed ? 'w-16' : 'w-60',
      )}
    >
      {/* Brand wordmark */}
      <div className={cn('flex h-16 items-center gap-2.5', isCollapsed ? 'justify-center px-0' : 'px-5')}>
        <span className="text-xl" aria-hidden="true">
          🧠
        </span>
        {!isCollapsed && (
          <span className="display bg-gradient-to-r from-pink to-blue bg-clip-text text-lg font-bold text-transparent">
            tiny brain
          </span>
        )}
      </div>

      <nav
        className={cn(
          'flex-1 overflow-y-auto py-4 text-sm',
          isCollapsed ? 'space-y-2 px-2' : 'space-y-7 px-3',
        )}
      >
        {sections.map((section) => (
          <div key={section.id}>
            {section.title && !isCollapsed && (
              <p className="eyebrow mb-2 px-2 text-[10px] text-subtle">{section.title}</p>
            )}
            {section.subtitle && !isCollapsed && (
              <p className="-mt-1 mb-2 px-2 text-[11px] text-muted-foreground">{section.subtitle}</p>
            )}
            <ul className="space-y-0.5">
              {section.items.map((item) => {
                const isSelected = selectedItemId === item.id;
                const isActiveSection = !isSelected && activeSectionItemId === item.id;
                return (
                  <li key={item.id}>
                    <button
                      onClick={() => onItemSelect(item.id)}
                      aria-current={isSelected ? 'page' : undefined}
                      title={isCollapsed ? item.title : undefined}
                      className={cn(
                        'flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-left transition-colors',
                        isCollapsed && 'justify-center px-0',
                        isSelected && 'font-medium text-blue',
                        // Active section (a child page is open) — emphasised but not blue.
                        isActiveSection &&
                          'font-medium text-foreground hover:bg-[color-mix(in_oklab,var(--ds-fg)_5%,transparent)]',
                        !isSelected &&
                          !isActiveSection &&
                          'font-normal text-muted-foreground hover:bg-[color-mix(in_oklab,var(--ds-fg)_5%,transparent)] hover:text-foreground',
                      )}
                      style={isSelected ? { background: SELECTED_ITEM_BG } : undefined}
                    >
                      <item.icon className="h-4 w-4 flex-shrink-0" />
                      {!isCollapsed && <span>{item.title}</span>}
                    </button>
                    {!isCollapsed && renderAfterItem?.(item.id)}
                  </li>
                );
              })}
            </ul>
          </div>
        ))}
      </nav>

      {/* Bottom-aligned: Settings (optional) + collapse control. */}
      <div className="mt-auto space-y-0.5 border-t border-border p-3">
        {onSettingsSelect && (
          <button
            onClick={onSettingsSelect}
            aria-current={isSettingsSelected ? 'page' : undefined}
            title={isCollapsed ? 'Settings' : undefined}
            className={cn(
              'flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-sm transition-colors',
              isCollapsed && 'justify-center px-0',
              // Inactive uses the dimmer `text-subtle` (not `text-muted-foreground`)
              // per the mockup, which renders the bottom utilities more recessed
              // than the primary nav items.
              isSettingsSelected
                ? 'font-medium text-blue'
                : 'font-normal text-subtle hover:bg-[color-mix(in_oklab,var(--ds-fg)_5%,transparent)] hover:text-foreground',
            )}
            style={isSettingsSelected ? { background: SELECTED_ITEM_BG } : undefined}
          >
            <Settings className="h-4 w-4 flex-shrink-0" />
            {!isCollapsed && <span>Settings</span>}
          </button>
        )}
        <button
          onClick={onToggleCollapse}
          aria-label="Toggle sidebar"
          className={cn(
            'flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-sm text-subtle transition-colors hover:text-foreground',
            isCollapsed && 'justify-center px-0',
          )}
        >
          <PanelLeft className="h-4 w-4 flex-shrink-0" />
          {!isCollapsed && <span>Collapse</span>}
        </button>
      </div>
    </aside>
  );
};
