import type { ConfigHealth } from '../types';

export type RepoHealthStatus = 'pass' | 'warn' | 'fail';

/**
 * A single repo-health check, shaped like the system doctor's `CheckResult`
 * so the Setup tab can render repo and system health with the same
 * row/Copy-command vocabulary. `fix` is the command a user copies to repair a
 * non-passing check (repo repairs are print-and-paste, matching system policy).
 */
export interface RepoHealthCheck {
  readonly key: string;
  readonly name: string;
  readonly status: RepoHealthStatus;
  readonly message: string;
  readonly details?: readonly string[];
  readonly fix?: string;
}

const HOOKS_FIX = 'tiny-brain hooks install';
const DOCTOR_FIX = 'tiny-brain doctor --fix';

const pluralise = (count: number, singular: string, plural: string): string =>
  `${count} ${count === 1 ? singular : plural}`;

const hooksCheck = (health: ConfigHealth): RepoHealthCheck => {
  const hooks = [health.hooks.preCommit, health.hooks.commitMsg, health.hooks.postCommit];
  const uninstalled = hooks.filter((h) => !h.installed);
  const unsigned = hooks.filter((h) => h.installed && !h.signed);

  if (uninstalled.length === hooks.length) {
    return { key: 'hooks', name: 'Git hooks', status: 'fail', message: 'Git hooks not installed', fix: HOOKS_FIX };
  }
  if (uninstalled.length > 0 || unsigned.length > 0) {
    const details: string[] = [];
    if (uninstalled.length > 0) details.push(`${pluralise(uninstalled.length, 'hook', 'hooks')} not installed`);
    if (unsigned.length > 0) details.push(`${pluralise(unsigned.length, 'hook', 'hooks')} not signed`);
    return { key: 'hooks', name: 'Git hooks', status: 'warn', message: 'Git hooks need attention', details, fix: HOOKS_FIX };
  }
  return { key: 'hooks', name: 'Git hooks', status: 'pass', message: 'Installed and signed' };
};

const contextBlockCheck = (health: ConfigHealth): RepoHealthCheck => {
  const { contextBlock } = health;
  if (!contextBlock.present) {
    return { key: 'contextBlock', name: 'CLAUDE.md', status: 'fail', message: 'CLAUDE.md not found', fix: 'tiny-brain init' };
  }
  const details: string[] = [];
  if (!contextBlock.upToDate) details.push('Context block outdated');
  if (contextBlock.missingSections.length > 0) {
    details.push(`${pluralise(contextBlock.missingSections.length, 'section', 'sections')} missing`);
  }
  if (details.length > 0) {
    return { key: 'contextBlock', name: 'CLAUDE.md', status: 'warn', message: 'CLAUDE.md needs updating', details, fix: DOCTOR_FIX };
  }
  return { key: 'contextBlock', name: 'CLAUDE.md', status: 'pass', message: 'Present and up to date' };
};

const permissionsCheck = (health: ConfigHealth): RepoHealthCheck => {
  const { permissions } = health;
  if (!permissions.present) {
    return { key: 'permissions', name: 'Permissions', status: 'fail', message: 'Permissions file missing', fix: DOCTOR_FIX };
  }
  if (permissions.missing.length > 0) {
    return {
      key: 'permissions',
      name: 'Permissions',
      status: 'warn',
      message: `${pluralise(permissions.missing.length, 'permission', 'permissions')} missing`,
      details: permissions.missing,
      fix: DOCTOR_FIX,
    };
  }
  return { key: 'permissions', name: 'Permissions', status: 'pass', message: 'Configured' };
};

const directoriesCheck = (health: ConfigHealth): RepoHealthCheck => {
  const { directories } = health;
  if (directories.missing.length > 0) {
    return {
      key: 'directories',
      name: 'Directories',
      status: 'warn',
      message: `${pluralise(directories.missing.length, 'directory', 'directories')} missing`,
      details: directories.missing,
      fix: DOCTOR_FIX,
    };
  }
  return { key: 'directories', name: 'Directories', status: 'pass', message: 'Required directories present' };
};

/**
 * Derives repo doctor rows from a ConfigHealth snapshot — git hooks, CLAUDE.md,
 * permissions and directories — each as a pass/warn/fail row with a copyable
 * fix command on non-passing rows. A non-git repo collapses to a single failing
 * row.
 */
export const deriveRepoHealthChecks = (health: ConfigHealth): readonly RepoHealthCheck[] => {
  if (health.isGitRepo === false) {
    return [{ key: 'git', name: 'Git repository', status: 'fail', message: 'Not a git repository', fix: 'git init' }];
  }
  return [hooksCheck(health), contextBlockCheck(health), permissionsCheck(health), directoriesCheck(health)];
};

/** Overall readiness verdict tone, worst-guardrail-wins. */
export type ReadinessTone = 'ready' | 'attention' | 'blocked';

export interface ReadinessSummary {
  /** Guardrails fully passing. */
  readonly ready: number;
  /** Guardrails still needing attention (total − ready). */
  readonly pending: number;
  /** Total guardrails. */
  readonly total: number;
  /** `blocked` if any guardrail fails, else `attention` if any warns, else `ready`. */
  readonly tone: ReadinessTone;
  /** Per-guardrail status, in check order — drives the segmented bar. */
  readonly segments: readonly RepoHealthStatus[];
}

/**
 * Reduce the repo's guardrail checks to a readiness verdict for the Setup hero:
 * a ready/total count and an overall tone. The tone is worst-wins so the hero
 * never reads "ready" while a guardrail is failing.
 */
export const deriveReadiness = (checks: readonly RepoHealthCheck[]): ReadinessSummary => {
  const segments = checks.map((c) => c.status);
  const total = segments.length;
  const ready = segments.filter((s) => s === 'pass').length;
  const tone: ReadinessTone = segments.includes('fail')
    ? 'blocked'
    : segments.includes('warn')
      ? 'attention'
      : 'ready';
  return { ready, pending: total - ready, total, tone, segments };
};
