import React, { useEffect, useState } from 'react';
import { type SetupChipStatus } from './SetupProgressStrip';
import { Button } from './ui/button';

/** A section "needs attention" when its checks fail or it wants a look. The
 *  earlier complete/untouched dots are gone — the sidebar only flags problems. */
const needsAttention = (status: SetupChipStatus): boolean =>
  status === 'fail' || status === 'attention';

export interface RepoSetupSectionDef {
  /** Anchor id, shared by the nav item, the section, and repo-card badges. */
  id: string;
  title: string;
  /** Derived section status; drives the nav-item issues indicator. */
  status: SetupChipStatus;
  /** Aggregate status shown in the section header (e.g. "1 of 5 failing"). */
  statusLabel?: React.ReactNode;
  content: React.ReactNode;
  /** Reference sections (Capabilities) still get a nav item but no Ready-CTA weight. */
  reference?: boolean;
}

interface RepoSetupTabProps {
  sections: RepoSetupSectionDef[];
  onNavigateToPlans: () => void;
  /** Section selected on mount — set by repo-card badges / route anchors.
   *  Defaults to the first section. */
  defaultExpandedSection?: string;
}

/**
 * Repo Setup tab — a left-hand sidebar of sections with a single active section
 * shown in the content pane (the same shape as the global Settings pane). The
 * sidebar makes the section set obvious at a glance; selecting one swaps the
 * content. Replaces the earlier progress-strip + stacked-accordion layout.
 */
export const RepoSetupTab: React.FC<RepoSetupTabProps> = ({
  sections,
  onNavigateToPlans,
  defaultExpandedSection,
}) => {
  const isKnown = (id?: string) => !!id && sections.some(s => s.id === id);
  const [active, setActive] = useState<string | undefined>(
    () => (isKnown(defaultExpandedSection) ? defaultExpandedSection : sections[0]?.id),
  );

  // A deep-link change (badge / route anchor) selects the named section.
  useEffect(() => {
    if (isKnown(defaultExpandedSection)) setActive(defaultExpandedSection);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [defaultExpandedSection]);

  const activeSection = sections.find(s => s.id === active) ?? sections[0];
  const stepSections = sections.filter(s => !s.reference);
  const allComplete = stepSections.length > 0 && stepSections.every(s => s.status === 'complete');

  return (
    <div data-testid="repo-setup-tab" className="h-full flex flex-col overflow-hidden rounded-lg">
      {/* Top tab bar — the main section nav runs horizontally so each section's
          own (vertical) sub-sidebar isn't nested beside a second sidebar. */}
      <nav
        data-testid="setup-tabs"
        className="flex-shrink-0 flex items-center gap-1 px-3 pt-2 border-b border-border overflow-x-auto"
      >
        {sections.map(section => {
          const isActive = section.id === active;
          return (
            <button
              key={section.id}
              type="button"
              data-testid={`setup-nav-${section.id}`}
              data-status={section.status}
              data-active={isActive ? 'true' : 'false'}
              aria-current={isActive ? 'page' : undefined}
              onClick={() => setActive(section.id)}
              className={`flex items-center gap-2 px-3 py-2 -mb-px text-sm whitespace-nowrap border-b-2 transition-colors ${
                isActive
                  ? 'border-blue text-foreground font-semibold'
                  : 'border-transparent text-muted-foreground hover:text-foreground'
              }`}
            >
              <span>{section.title}</span>
              {/* Issues indicator — only when the section needs attention */}
              {needsAttention(section.status) && (
                <span
                  data-testid={`setup-issue-${section.id}`}
                  aria-label={`${section.title} needs attention`}
                  className="h-2 w-2 rounded-full shrink-0"
                  style={{ background: 'var(--color-warn)' }}
                />
              )}
            </button>
          );
        })}

        {allComplete && (
          <Button size="sm" onClick={onNavigateToPlans} className="ml-auto my-1">
            Go to plans
          </Button>
        )}
      </nav>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-6 min-h-0">
        {activeSection && (
          <section id={activeSection.id} aria-labelledby={`setup-heading-${activeSection.id}`} className="h-full flex flex-col">
            <div className="flex items-center justify-between gap-3 mb-4 flex-shrink-0">
              <h2 id={`setup-heading-${activeSection.id}`} className="display text-lg font-semibold">
                {activeSection.title}
              </h2>
              {activeSection.statusLabel != null && (
                <span className="text-xs text-muted-foreground flex items-center gap-1">
                  {activeSection.statusLabel}
                </span>
              )}
            </div>
            <div className="flex-1 min-h-0">{activeSection.content}</div>
          </section>
        )}
      </div>
    </div>
  );
};

export default RepoSetupTab;
