'use client'

import { useEffect, useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { formatDistanceToNow } from 'date-fns'
import { Skeleton } from '@/components/ui/skeleton'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { FolderGit2, AlertCircle, Trash2, GitBranch, Search, Star } from 'lucide-react'
import { REPO_STARRED_CHANGED_EVENT } from '@/components/layout/StarredReposSection'
import { useRepoRegisteredLive } from '@/hooks/useRepoRegisteredLive'
import ConfigHealthBadge from '@/components/ConfigHealthBadge'
import AnalysisBadge from '@/components/AnalysisBadge'

interface WorktreeEntry {
  name: string
  branch: string
  path: string
  lastActive: string
}

interface RepoInfo {
  id: string
  name: string
  path: string
  /** ISO timestamp from RepoConfigService — set on every register/access. */
  lastAccessed?: string
  worktrees?: WorktreeEntry[]
  starred?: boolean
}

type SortKey = 'recent' | 'alphabetical' | 'worktree-count'

const mostRecentLastActive = (repo: RepoInfo): number => {
  // Combine the repo's own lastAccessed timestamp (set by
  // RepoConfigService on every register/access) with any worktree
  // lastActive timestamps and pick the most recent. Without the
  // top-level fallback, repos with no worktrees rendered as "Never
  // accessed" even when their lastAccessed was current.
  const candidates: number[] = []
  if (repo.lastAccessed) {
    const t = new Date(repo.lastAccessed).getTime()
    if (!Number.isNaN(t)) candidates.push(t)
  }
  for (const wt of repo.worktrees ?? []) {
    const t = new Date(wt.lastActive).getTime()
    if (!Number.isNaN(t)) candidates.push(t)
  }
  if (candidates.length === 0) return -Infinity
  return Math.max(...candidates)
}

const formatLastAccessed = (repo: RepoInfo): string => {
  const t = mostRecentLastActive(repo)
  if (!Number.isFinite(t)) return 'Never accessed'
  return `Last accessed ${formatDistanceToNow(new Date(t), { addSuffix: true })}`
}

export default function ReposPage() {
  const navigate = useNavigate()
  const [repos, setRepos] = useState<RepoInfo[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [repoToRemove, setRepoToRemove] = useState<RepoInfo | null>(null)
  const [search, setSearch] = useState('')
  const [sortKey, setSortKey] = useState<SortKey>('recent')

  useEffect(() => {
    fetchRepos()
  }, [])

  // Live sync — when star/unstar fires elsewhere in the window
  // (e.g. the sidebar's StarredReposSection unstars a repo), refetch
  // so the card's star icon mirrors the new state.
  useEffect(() => {
    const handler = () => {
      fetchRepos()
    }
    window.addEventListener(REPO_STARRED_CHANGED_EVENT, handler)
    return () => window.removeEventListener(REPO_STARRED_CHANGED_EVENT, handler)
  }, [])

  const fetchRepos = async () => {
    try {
      const response = await fetch('/api/repos')
      if (!response.ok) {
        setError(`Failed to load repositories (HTTP ${response.status})`)
        setRepos([])
        return
      }
      const data = await response.json()
      setError(null)
      setRepos(data.repos || [])
    } catch (err) {
      console.error('[ReposPage] Failed to load repositories:', err)
      setError(err instanceof Error ? err.message : 'Failed to load repositories')
      setRepos([])
    } finally {
      setLoading(false)
    }
  }

  // Live sync — a newly registered repo (server `repo-registered` SSE) refetches
  // the list so it appears without a manual reload (fix
  // dashboard-drops-filewatcher-sse-events T4).
  useRepoRegisteredLive(() => { fetchRepos() })

  const [starringIds, setStarringIds] = useState<ReadonlySet<string>>(() => new Set())

  const toggleStarred = async (repo: RepoInfo) => {
    // In-flight guard — rapid double-clicks otherwise risk a successful
    // second request being clobbered by the first's rollback.
    if (starringIds.has(repo.id)) return

    const next = !repo.starred
    const setStarred = (id: string, value: boolean | undefined) => {
      setRepos(prev => prev.map(r => (r.id === id ? { ...r, starred: value } : r)))
    }

    // Optimistic update — flip locally so the icon redraws immediately.
    setStarred(repo.id, next)
    setStarringIds(prev => {
      const out = new Set(prev)
      out.add(repo.id)
      return out
    })

    try {
      const response = await fetch(`/api/repos/${repo.id}/star`, {
        method: next ? 'POST' : 'DELETE',
      })
      if (!response.ok) {
        // Roll back on failure so the UI doesn't lie about persisted state.
        setStarred(repo.id, repo.starred)
      } else {
        // Notify the sidebar's StarredReposSection (and any future
        // listeners) so they refresh without a manual reload.
        window.dispatchEvent(new CustomEvent(REPO_STARRED_CHANGED_EVENT))
      }
    } catch (err) {
      console.error('[ReposPage] Failed to toggle starred:', err)
      setStarred(repo.id, repo.starred)
    } finally {
      setStarringIds(prev => {
        const out = new Set(prev)
        out.delete(repo.id)
        return out
      })
    }
  }

  const confirmRemoveRepo = async () => {
    if (!repoToRemove) return
    try {
      const response = await fetch(`/api/repos/${repoToRemove.id}`, { method: 'DELETE' })
      if (response.ok) {
        setRepos(prev => prev.filter(r => r.id !== repoToRemove.id))
      }
    } catch (err) {
      console.error('[ReposPage] Error removing repo:', err)
    } finally {
      setRepoToRemove(null)
    }
  }

  const visibleRepos = useMemo(() => {
    const needle = search.trim().toLowerCase()
    const filtered = needle
      ? repos.filter(r =>
          r.name.toLowerCase().includes(needle) ||
          r.path.toLowerCase().includes(needle)
        )
      : repos

    const sorted = [...filtered]
    switch (sortKey) {
      case 'alphabetical':
        sorted.sort((a, b) => a.name.localeCompare(b.name))
        break
      case 'worktree-count':
        sorted.sort((a, b) => (b.worktrees?.length ?? 0) - (a.worktrees?.length ?? 0))
        break
      case 'recent':
      default:
        sorted.sort((a, b) => mostRecentLastActive(b) - mostRecentLastActive(a))
        break
    }
    return sorted
  }, [repos, search, sortKey])

  if (loading) {
    return (
      <div className="p-6 space-y-4">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-32 w-full" />
      </div>
    )
  }

  if (error) {
    return (
      <div className="p-6">
        <div className="flex items-center gap-2 text-red-500">
          <AlertCircle className="h-5 w-5" />
          <span>{error}</span>
        </div>
      </div>
    )
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <p className="text-muted-foreground">
          View and manage work across your repositories
        </p>

        <div data-testid="repos-toolbar-right" className="flex items-center gap-3 ml-auto">
          <div className="relative">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
            <input
              type="text"
              placeholder="Search repositories..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-8 pr-3 py-1.5 text-sm rounded-md border border-border bg-background focus:outline-none focus:ring-2 focus:ring-blue"
              aria-label="Search repositories"
            />
          </div>

          <label className="flex items-center gap-2 text-sm">
            <span className="text-muted-foreground">Sort</span>
            <select
              aria-label="Sort repositories"
              value={sortKey}
              onChange={(e) => setSortKey(e.target.value as SortKey)}
              className="py-1.5 px-2 text-sm rounded-md border border-border bg-background focus:outline-none focus:ring-2 focus:ring-blue"
            >
              <option value="recent">Most recently used</option>
              <option value="alphabetical">Alphabetical (A–Z)</option>
              <option value="worktree-count">Worktree count</option>
            </select>
          </label>
        </div>
      </div>

      <div className="grid gap-4 grid-cols-1 md:grid-cols-2 xl:grid-cols-3">
        {visibleRepos.map((repo) => (
          <div
            key={repo.id}
            data-testid={`repo-card-${repo.id}`}
            // The shared list-card surface (as FixCard / PlanCard): the panel
            // tint + hover border live in `.plan-card-surface`; `lift` raises it
            // on hover, `rise` plays the entrance.
            className="plan-card-surface lift rise relative block cursor-pointer overflow-hidden rounded-2xl p-4 pl-5"
            onClick={() => navigate(`/repos/${repo.id}`)}
          >
            <div
              data-testid="repo-card-header"
              className="flex items-center justify-between gap-2"
            >
              <div className="flex items-center gap-2 min-w-0">
                <FolderGit2
                  data-testid="repo-card-header-icon"
                  className="h-5 w-5 flex-shrink-0 text-blue"
                />
                <span className="display truncate text-lg font-bold leading-none">
                  {repo.name}
                </span>
              </div>
              <div className="flex items-center gap-1 flex-shrink-0">
                <button
                  onClick={(e) => {
                    e.stopPropagation()
                    toggleStarred(repo)
                  }}
                  className={`rounded p-1 transition-colors hover:bg-accent/40 ${
                    repo.starred ? 'text-blue' : 'text-subtle'
                  }`}
                  aria-label={`${repo.starred ? 'Unstar' : 'Star'} ${repo.name}`}
                  data-starred={repo.starred ? 'true' : 'false'}
                >
                  <Star
                    data-testid={`star-icon-${repo.id}`}
                    className="h-4 w-4"
                    fill={repo.starred ? 'currentColor' : 'none'}
                  />
                </button>
                <button
                  onClick={(e) => {
                    e.stopPropagation()
                    setRepoToRemove(repo)
                  }}
                  className="rounded p-1 text-subtle transition-colors hover:bg-destructive/10 hover:text-destructive"
                  aria-label={`Remove ${repo.name}`}
                >
                  <Trash2 className="h-4 w-4" />
                </button>
              </div>
            </div>

            <p className="mono mt-3 truncate text-[12px] text-subtle" title={repo.path}>
              {repo.path}
            </p>

            {repo.worktrees && repo.worktrees.length > 0 && (
              <div className="mt-2 flex items-center gap-1.5">
                <span className="mono inline-flex items-center gap-1 rounded-full border border-border-strong px-2.5 py-0.5 text-[11px] text-subtle">
                  <GitBranch className="h-3 w-3" />
                  {repo.worktrees.length} {repo.worktrees.length === 1 ? 'worktree' : 'worktrees'}
                </span>
              </div>
            )}

            <p className="mt-2 text-[13px] text-muted-foreground">{formatLastAccessed(repo)}</p>

            {/* Config + analysis badges — deep-link into the repo's Setup tab
                at the matching section. The wrapper stops clicks from bubbling
                to the card's own navigation. */}
            <div className="mt-3 flex items-center gap-3" onClick={(e) => e.stopPropagation()}>
              <ConfigHealthBadge
                repoId={repo.id}
                onClick={() => navigate(`/repos/${repo.id}?section=working-together`)}
              />
              <AnalysisBadge
                repoId={repo.id}
                onClick={() => navigate(`/repos/${repo.id}?section=working-together`)}
              />
            </div>
          </div>
        ))}
      </div>

      {repos.length === 0 && (
        <div className="panel rounded-2xl p-10 text-center text-muted-foreground">
          <FolderGit2 className="mx-auto mb-2 h-12 w-12 opacity-50" />
          <p>No repositories found</p>
        </div>
      )}

      {repos.length > 0 && visibleRepos.length === 0 && (
        <div className="panel rounded-2xl p-10 text-center text-muted-foreground">
          <Search className="mx-auto mb-2 h-12 w-12 opacity-50" />
          <p>No repositories match &quot;{search}&quot;</p>
        </div>
      )}

      <AlertDialog
        open={repoToRemove !== null}
        onOpenChange={(open) => {
          if (!open) setRepoToRemove(null)
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Remove Repository</AlertDialogTitle>
            <AlertDialogDescription>
              Remove &quot;{repoToRemove?.name}&quot; from the repos list? This won&apos;t delete any files on disk.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={confirmRemoveRepo}>Remove</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}
