import React, { useMemo } from 'react';
import { cn } from '@/lib/utils';
import { Archive } from 'lucide-react';
import WorktreePill from './WorktreePill';
import { StatusPill, type StatusVariant } from './StatusPill';
import { GradientProgress } from './ui/GradientProgress';
import type { Fix } from '../types';
import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { taskPhaseProgress } from '../utils/task-progress';
import { toEffectiveTask } from '../utils/effective-task';
import { rollUpEffectiveStatuses } from '../utils/effective-task-status';

interface FixCardProps {
  fix: Fix;
  isSelected: boolean;
  onClick: () => void;
  reviewPipeline?: PipelineStep[];
}

// Short relative-time readout for the card footer (the fix analogue of
// PlanCard's "2h ago"). Coarse buckets are all the sidebar glance needs.
function formatRelativeTime(dateStr: string | null | undefined): string | null {
  if (!dateStr) return null;
  const diffMs = Date.now() - new Date(dateStr).getTime();
  const mins = Math.floor(diffMs / 60000);
  if (mins < 1) return 'just now';
  if (mins < 60) return `${mins}m ago`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  if (days < 7) return `${days}d ago`;
  if (days < 30) return `${Math.floor(days / 7)}w ago`;
  if (days < 365) return `${Math.floor(days / 30)}mo ago`;
  return `${Math.floor(days / 365)}y ago`;
}

const FixCard: React.FC<FixCardProps> = ({ fix, isSelected, onClick, reviewPipeline }) => {
  // Branches this fix's work lives on, each flagged with whether a live worktree
  // exists — the fix analogue of PlanCard's marker. Keyed on the BRANCH (the
  // stable identity) so the same physical worktree, surfacing as both a
  // task/source dir-name and a lattice branch ref, collapses to one entry.
  // Lattice refs are filtered to live worktrees (isWorktree) STRICTLY AHEAD of
  // the launch ref; explicit task/source worktrees surface regardless of ahead-
  // status so a fresh/undiverged worktree still shows.
  const worktreeBranches = useMemo(() => {
    const rank: Record<string, number> = { not_started: 0, in_progress: 1, completed: 2, superseded: 2 };
    const byBranch = new Map<string, { hasWorktree: boolean; worktreeName?: string }>();
    const add = (branch: string, hasWorktree: boolean, worktreeName?: string) => {
      const prev = byBranch.get(branch);
      byBranch.set(branch, {
        hasWorktree: (prev?.hasWorktree ?? false) || hasWorktree,
        worktreeName: prev?.worktreeName ?? worktreeName,
      });
    };

    if (fix.sourceWorktree) add(fix.sourceWorktree.branch, true, fix.sourceWorktree.name);
    for (const task of fix.tasks) {
      if (task.worktree) add(task.worktree.branch, true, task.worktree.name);
      const cells = task.statusByRef || [];
      const launchRank = rank[cells.find(c => c.isLaunchRef)?.status ?? 'not_started'] ?? 0;
      for (const cell of cells) {
        if (cell.isLaunchRef || !cell.isWorktree) continue;
        if ((rank[cell.status] ?? 0) <= launchRank) continue;
        add(cell.ref, true); // lattice refs carry no dir name
      }
    }
    return [...byBranch].map(([branch, v]) => ({ branch, ...v }));
  }, [fix.sourceWorktree, fix.tasks]);

  // Roll the card status/progress up from WORKTREE-EFFECTIVE task statuses, so a
  // fix whose work is all done on a worktree branch reads done in the sidebar
  // like its detail row icons already do (ADR-0007 display rollup; fix:
  // fix-status-head-only-vs-across-refs). Empty-task fixes keep raw fix.status.
  const effectiveTasks = useMemo(() => fix.tasks.map(toEffectiveTask), [fix.tasks]);
  const effectiveFixStatus = fix.tasks.length > 0 ? rollUpEffectiveStatuses(effectiveTasks.map(t => t.status)) : fix.status;

  // Phase-aware completion percentage (single value — the new design system's
  // gradient bar has no completed/superseded split, unlike the old ProgressBar).
  const progress = useMemo(() => {
    if (effectiveFixStatus === 'completed' || effectiveFixStatus === 'superseded') return 100;
    const total = effectiveTasks.length;
    if (total === 0) return 0;
    const weight = effectiveTasks.reduce((sum, task) => sum + taskPhaseProgress(task, reviewPipeline), 0);
    return Math.round((weight / total) * 100);
  }, [effectiveFixStatus, effectiveTasks, reviewPipeline]);

  const isResolved = effectiveFixStatus === 'completed' || effectiveFixStatus === 'superseded';
  const isInProgress = effectiveFixStatus === 'in_progress';
  const isArchived = fix.archived === true;

  const totalTasks = effectiveTasks.length;
  const doneTasks = effectiveTasks.filter(t => t.status === 'completed' || t.status === 'superseded').length;
  // The pink→blue bar appears whenever there's progress to show — active or
  // resolved. A not-started fix shows just its pill (matching PlanCard).
  const showProgress = isResolved || isInProgress;
  const variant: StatusVariant = isResolved ? 'done' : isInProgress ? 'in-progress' : 'not-started';
  const relativeDate = formatRelativeTime(fix.resolved ?? fix.reported);

  return (
    <div
      data-testid={isArchived ? 'archived-card' : 'fix-card'}
      data-selected={isSelected}
      data-status={variant}
      role="button"
      tabIndex={0}
      onClick={onClick}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onClick();
        }
      }}
      className={cn(
        'plan-card-surface lift rise relative block cursor-pointer overflow-hidden rounded-2xl p-4 pl-5 hover:bg-accent/30',
        isSelected && 'plan-card-accent panel',
        isArchived && 'opacity-60',
      )}
    >
      <div className="flex items-start justify-between gap-2">
        <h3 className={cn('display text-[15px] leading-snug line-clamp-2', isInProgress || isSelected ? 'font-semibold' : 'font-medium')}>
          {fix.title}
        </h3>
        {isArchived && <Archive data-testid="archive-icon" className="h-3.5 w-3.5 flex-shrink-0 text-muted-foreground" />}
      </div>

      <div className="mt-2.5 flex items-center gap-2">
        <StatusPill variant={variant} label={isResolved ? 'Fixed' : undefined} />
        {showProgress && (
          <span className="mono ml-auto text-[11px] text-muted-foreground">
            {isResolved ? `${doneTasks}/${totalTasks}` : `${progress}%`} <span className="font-sans">tasks</span>
          </span>
        )}
      </div>

      {showProgress && <GradientProgress value={progress} className="mt-3" />}

      {/* Worktree/branch pill on its own full-width row under the progress bar —
          the pill is wide and reads better unshared, separate from the
          task-count / severity / date meta line below. */}
      {worktreeBranches.length > 0 && (
        <div data-testid="card-worktree-row" className="mt-3">
          <WorktreePill branches={worktreeBranches} />
        </div>
      )}

      <div
        data-testid="card-meta-row"
        className="mono mt-3 flex items-center justify-between gap-2 text-[11px] text-muted-foreground"
      >
        <span>
          {totalTasks} <span className="font-sans">{totalTasks === 1 ? 'task' : 'tasks'}</span>
          {' · '}<span className="font-sans">{fix.severity}</span>
        </span>
        {relativeDate && <span className="font-sans">{relativeDate}</span>}
      </div>

      {/* Active-run footer (Task 10 of run-lifecycle): glance row
          showing which worker is on this fix and where it's
          running. 🤖 for a local-worker driver, ☁️ for cloud-
          remote, both when a worker is driving a remote run. */}
      {fix.activeRun && (
        <div
          data-testid="active-run-footer"
          className="mt-2 flex items-center gap-1.5 text-[11px] text-muted-foreground"
          title={fix.activeRun.worktreePath}
        >
          {/* Robot when a worker is driving (always for local;
              only when `worker` is set for cloud-remote). */}
          {(fix.activeRun.target === 'local-worktree' ||
            fix.activeRun.worker !== undefined) && (
            <span aria-label="local worker">🤖</span>
          )}
          {fix.activeRun.target === 'cloud-remote' && (
            <span aria-label="cloud remote">☁️</span>
          )}
          {fix.activeRun.worktreePath && (
            <span className="truncate">
              {fix.activeRun.worktreePath.split('/').filter(Boolean).slice(-1)[0]}
            </span>
          )}
        </div>
      )}
    </div>
  );
};

export default FixCard;
