import { useCallback, useEffect, useRef, useState } from 'react';
import { findChangeByNewLineNumber, getChangeKey, type FileData } from 'react-diff-view';

/** A point in a diff to anchor to — the file path and its (new-file) line. */
export interface AnchorTarget {
  readonly path: string;
  readonly line: number;
}

interface Selection {
  readonly target: AnchorTarget;
  /** The react-diff-view change key for the highlighted line. */
  readonly key: string;
}

/**
 * Shared rail → diff anchor. `anchor(target)` resolves a {@link AnchorTarget} to
 * the react-diff-view change key (exposed as `selectedKey`, fed to
 * `<Diff selectedChanges>` so the matching line is highlighted) and scrolls that
 * line into view inside `containerRef`. The selection is the single source of
 * truth: `isSelected(target)` and `selectedKey` move together, so a target that
 * doesn't resolve to a change leaves nothing selected (no active row, no
 * highlight) rather than half-selecting.
 *
 * Built for the Red tab's failing-tests rail; consumer-agnostic so the Review
 * tab's findings rail can reuse it (task-detail-page task 5). The caller renders
 * the diff(s) inside `containerRef` and threads `selectedChanges` from
 * `selectedKey`.
 */
export function useHunkAnchor(files: readonly FileData[]) {
  const containerRef = useRef<HTMLElement>(null);
  const [selection, setSelection] = useState<Selection | null>(null);

  const anchor = useCallback(
    (target: AnchorTarget) => {
      const file = files.find((f) => (f.newPath ?? f.oldPath) === target.path);
      const change = file ? findChangeByNewLineNumber(file.hunks, target.line) : undefined;
      setSelection(change ? { target, key: getChangeKey(change) } : null);
    },
    [files],
  );

  const isSelected = useCallback(
    (target: AnchorTarget) =>
      selection?.target.path === target.path && selection?.target.line === target.line,
    [selection],
  );

  // Keyed on the `selection` object (a fresh reference per `anchor` call) so
  // re-selecting the already-active row re-centres it.
  useEffect(() => {
    if (!selection) return;
    // react-diff-view marks the selected line's code cell `.diff-code-selected`.
    const node = containerRef.current?.querySelector<HTMLElement>('.diff-code-selected');
    node?.scrollIntoView({ block: 'center', behavior: 'smooth' });
  }, [selection]);

  return { containerRef, selectedKey: selection?.key ?? null, isSelected, anchor };
}
