import { cn } from '@/lib/utils';

export interface RepoHeaderProps {
  /** Active repo name (the final breadcrumb crumb). */
  repoName: string;
  /** Absolute/〜 path shown after the name in mono. */
  repoPath?: string;
  /** Navigate back to the repos list (the "Repos" crumb). */
  onBack: () => void;
  /** Whether to show the plan badge on the right. */
  showPlanBadge?: boolean;
  /** Plan badge label. */
  planLabel?: string;
  className?: string;
}

/**
 * The repo workspace header from the UI Refresh mockups: a breadcrumb
 * (Repos / <name>) with the repo path in mono, and an optional plan badge.
 */
export function RepoHeader({
  repoName,
  repoPath,
  onBack,
  showPlanBadge = false,
  planLabel = 'PRO',
  className,
}: RepoHeaderProps) {
  return (
    <div className={cn('flex min-w-0 items-center justify-between gap-4', className)}>
      <nav aria-label="Breadcrumb" className="flex min-w-0 items-center gap-2.5 text-sm">
        <button
          onClick={onBack}
          className="text-subtle transition-colors hover:text-foreground"
        >
          Repos
        </button>
        <span className="text-border-strong" aria-hidden="true">
          /
        </span>
        <span className="truncate font-medium">{repoName}</span>
        {repoPath && (
          <span className="mono ml-1 truncate text-xs text-subtle">{repoPath}</span>
        )}
      </nav>

      {showPlanBadge && (
        <span className="shrink-0 rounded-md border border-border-strong px-2.5 py-0.5 text-[11px] font-semibold tracking-widest text-blue">
          {planLabel}
        </span>
      )}
    </div>
  );
}

export default RepoHeader;
