import React from 'react';
import { Archive } from 'lucide-react';
import { cn } from '@/lib/utils';
import CopyIdButton from './CopyIdButton';
import type { Plan } from '../types';

type PlanStatus = Plan['status'];

interface PlanDetailHeaderProps {
  /** Plan title, rendered as the heading. */
  title: string;
  /** PRD id/slug; a copy affordance is shown next to the title when set. */
  prdId?: string;
  /** Lifecycle status, stated by the eyebrow (no separate pill). */
  status?: PlanStatus;
  /** Number of features in the plan. */
  featureCount: number;
  /** ISO timestamp of the last update; formatted as e.g. "29 May 2026". */
  lastUpdated?: string;
  /** Whether the plan is archived — flips the action between Archive/Unarchive. */
  isArchived?: boolean;
  /** Archive/unarchive handlers. The action button only renders when the
   *  relevant handler is wired, so unwired contexts (stories, read-only shells)
   *  show no dead button rather than a silent no-op. */
  onArchive?: () => void;
  onUnarchive?: () => void;
}

/** Derive the header's display props from a Plan, so every render site (the PRD
 *  view and the legacy dashboard fallback) maps the plan the same way. */
export function planHeaderPropsFromPlan(plan: Plan): Omit<PlanDetailHeaderProps, 'onArchive' | 'onUnarchive'> {
  return {
    title: plan.title || plan.name || '',
    prdId: plan.prdId || plan.id,
    status: plan.status,
    featureCount: plan.features?.length ?? plan.metadata?.totalFeatures ?? plan.featureCount ?? 0,
    lastUpdated: plan.lastUpdated || plan.updatedAt,
    isArchived: plan.type === 'archived',
  };
}

const STATUS_LABELS: Record<PlanStatus, string> = {
  not_started: 'Not Started',
  in_progress: 'In Progress',
  completed: 'Complete',
};

// Eyebrow accent per status — the eyebrow alone states the status, matching the
// mockup (no separate status pill in the plan detail header).
const STATUS_TONE: Record<PlanStatus, string> = {
  not_started: 'text-muted-foreground',
  in_progress: 'text-blue',
  completed: 'text-done',
};

function formatUpdated(iso: string | undefined): string {
  if (!iso) return 'Unknown';
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return 'Unknown';
  return date.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
}

/**
 * The plan detail header from the UI Refresh mockup: a status eyebrow, the plan
 * title with a copy-id affordance, and a "{n} features · last updated {date}"
 * line carrying the Archive/Unarchive action. The status is conveyed by the
 * eyebrow alone — there is no separate status pill here.
 */
const PlanDetailHeader: React.FC<PlanDetailHeaderProps> = ({
  title,
  prdId,
  status = 'not_started',
  featureCount,
  lastUpdated,
  isArchived = false,
  onArchive,
  onUnarchive,
}) => {
  const statusLabel = STATUS_LABELS[status];
  const statusTone = STATUS_TONE[status];
  const archiveAction = isArchived ? onUnarchive : onArchive;

  return (
    <div data-testid="plan-detail-header">
      <p className={cn('eyebrow text-[10px]', statusTone)}>Plan · {statusLabel}</p>

      <div className="mt-2 flex items-center gap-2.5">
        <h1 className="display text-2xl font-bold leading-snug">{title}</h1>
        {prdId && <CopyIdButton value={prdId} kind="PRD" className="flex-shrink-0" />}
      </div>

      <div className="mt-2 flex flex-wrap items-center justify-between gap-3">
        <p className="text-sm text-muted-foreground">
          {featureCount} {featureCount === 1 ? 'feature' : 'features'} · last updated {formatUpdated(lastUpdated)}
        </p>
        {archiveAction && (
          <button
            type="button"
            onClick={archiveAction}
            aria-label={isArchived ? 'Unarchive' : 'Archive'}
            className="inline-flex items-center gap-1.5 rounded-lg px-2 py-1.5 text-xs font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
          >
            <Archive className="h-3.5 w-3.5" />
            {isArchived ? 'Unarchive' : 'Archive'}
          </button>
        )}
      </div>
    </div>
  );
};

export default PlanDetailHeader;
