import type { RepoAnalysisFile } from '../types';

/**
 * Agent abilities: the commands the pipeline's Coverage / Mutation / static
 * reviewers run, grouped the way the repo-settings Analysis mockup shows them.
 * A missing command disables the matching pipeline step, so each command is
 * tagged with its availability.
 */
export type AbilityStatus = 'available' | 'needs config' | 'not detected';

export interface AbilityCommand {
  /** Human label, e.g. "Full test run". */
  readonly label: string;
  /** One-line description of what the command covers. */
  readonly detail: string;
  /** The command itself, or null when nothing was detected. */
  readonly command: string | null;
  readonly status: AbilityStatus;
}

export interface AbilityGroup {
  readonly key: 'unit-tests' | 'mutation' | 'static';
  readonly title: string;
  /** Which pipeline agent consumes this group. */
  readonly agent: string;
  readonly commands: readonly AbilityCommand[];
}

const detected = (command: string | undefined | null, label: string, detail: string): AbilityCommand =>
  command
    ? { label, detail, command, status: 'available' }
    : { label, detail, command: null, status: 'not detected' };

const unitTests = (analysis: RepoAnalysisFile): AbilityGroup => {
  const test = analysis.scripts?.test;
  // Prefer the detected `coverage` analyzer's command (the authoritative source)
  // and fall back to the package test script's coverage variant.
  const coverageAnalyzer = (analysis.analyzers ?? []).find((a) => a.id === 'coverage');
  const coverageCommand = coverageAnalyzer?.commands.quality || test?.coverage;
  return {
    key: 'unit-tests',
    title: 'Unit tests',
    agent: 'coverage agent',
    commands: [
      detected(test?.command, 'Full test run', 'Every package'),
      detected(coverageCommand, 'Coverage', 'Line + branch'),
    ],
  };
};

const mutation = (analysis: RepoAnalysisFile): AbilityGroup => {
  // First-wins: a repo realistically has one mutation tool; if more than one
  // mutation-category analyzer is ever detected we surface the first.
  const analyzer = (analysis.analyzers ?? []).find(
    // `mutation-testing` is the canonical analyzer id; keep the legacy
    // `stryker` / `mutation`-category matches for older analysis files.
    (a) => a.id === 'mutation-testing' || a.id === 'stryker' || a.categories.includes('mutation'),
  );
  if (!analyzer) {
    return {
      key: 'mutation',
      title: 'Mutation',
      agent: 'mutation agent',
      commands: [{ label: 'Full mutation', detail: 'No mutation tool detected', command: null, status: 'not detected' }],
    };
  }
  const incremental: AbilityCommand = analyzer.commands.pipeline
    ? { label: 'Changed-file mutation', detail: 'Incremental run', command: analyzer.commands.pipeline, status: 'available' }
    : { label: 'Changed-file mutation', detail: 'Incremental mode not configured', command: null, status: 'needs config' };
  return {
    key: 'mutation',
    title: 'Mutation',
    agent: 'mutation agent',
    commands: [
      // Guard an empty quality command — an empty string is not a usable command.
      analyzer.commands.quality
        ? { label: 'Full mutation', detail: `All mutable source · ${analyzer.name}`, command: analyzer.commands.quality, status: 'available' }
        : { label: 'Full mutation', detail: `${analyzer.name} detected, no run command`, command: null, status: 'not detected' },
      incremental,
    ],
  };
};

const staticAnalysis = (analysis: RepoAnalysisFile): AbilityGroup => {
  const lint = analysis.scripts?.lint?.command;
  const isTs =
    analysis.analysis.primaryLanguage === 'typescript' || analysis.stack.languages.includes('typescript');
  // Dependency audit is now a detectable analyzer (id `dependency-audit`, e.g.
  // `npm audit`); fall back to the suggested-command prompt when absent.
  const auditAnalyzer = (analysis.analyzers ?? []).find((a) => a.id === 'dependency-audit');
  const auditRow: AbilityCommand =
    auditAnalyzer && auditAnalyzer.commands.quality
      ? { label: 'Dependency audit', detail: `Dependencies · ${auditAnalyzer.name}`, command: auditAnalyzer.commands.quality, status: 'available' }
      : { label: 'Dependency audit', detail: 'No audit command detected', command: null, status: 'not detected' };
  return {
    key: 'static',
    title: 'Static analysis',
    agent: 'pipeline & reviewers',
    commands: [
      detected(lint, 'Lint', 'Per-commit'),
      // Type checking is *applicable* to a TS repo but we can't confirm a
      // configured command from analysis.json — surface it as needs-config (a
      // suggested command), not as if it were detected.
      isTs
        ? { label: 'Type check', detail: 'Configure tsc as a pipeline step', command: 'tsc --noEmit', status: 'needs config' }
        : { label: 'Type check', detail: 'No type checker detected', command: null, status: 'not detected' },
      auditRow,
    ],
  };
};

export const deriveAgentAbilities = (analysis: RepoAnalysisFile): readonly AbilityGroup[] => [
  unitTests(analysis),
  mutation(analysis),
  staticAnalysis(analysis),
];
