import type { QualityScoresResponse, StepScoreResponse } from '../types';

/**
 * The "signals" rethink replaces the single-verdict score header with a
 * plain-language posture summary plus a vitals strip. This module is the pure
 * derivation: quality scores → posture sentence + vital chips. No React, no
 * grades, no fill-to-100 bar — every vital is framed as a quantity to keep low
 * so a high value always reads as risk.
 */

export type VitalState = 'ok' | 'watch' | 'risk';

export interface Vital {
  /** Stable key (the source step type) — also drives the chip test id. */
  readonly key: string;
  readonly label: string;
  readonly value: string;
  readonly state: VitalState;
}

export interface PostureSummary {
  readonly eyebrow: string;
  readonly headline: string;
  readonly detail: string;
  readonly vitals: ReadonlyArray<Vital>;
}

/**
 * Lens severity ranking — the sharpest open risk is surfaced in the posture
 * detail. Every lens is listed explicitly (no accidental rank-0 fallthrough):
 * security findings are the sharpest, the measured instruments (coverage,
 * tdd-compliance) rank lowest so a real reviewer finding always wins the
 * "sharpest" slot over a coverage gap. Unknown types fall back to 0.
 */
const SEVERITY: Record<string, number> = {
  security: 5,
  'dependency-audit': 4,
  performance: 3,
  testing: 2,
  'code-quality': 2,
  'tdd-compliance': 1,
  coverage: 1,
};

function severity(step: StepScoreResponse): number {
  return SEVERITY[step.type] ?? 0;
}

/**
 * Shared dot state for a step, framed so a higher value never reads greener.
 * Coverage is a measured instrument: its dot tracks the *uncovered gap* it
 * displays (via `passing`, i.e. score vs threshold) — not `findingsCount`
 * (~always 0 for a percentage step, which would paint a large gap green and
 * break the keep-it-low invariant). Every other lens colours by findings:
 * findings on a failing lens are risk, on a passing lens a watch; a clean lens
 * is ok unless it is failing for another reason.
 */
export function riskStateForStep(step: StepScoreResponse): VitalState {
  if (step.type === 'coverage') {
    return step.passing ? 'ok' : 'risk';
  }
  if (step.findingsCount > 0) {
    return step.passing ? 'watch' : 'risk';
  }
  return step.passing ? 'ok' : 'watch';
}

function openLabel(count: number): string {
  return `${count} open`;
}

/** Map a pipeline step to a vital framed as a quantity to keep low. */
function vitalForStep(step: StepScoreResponse): Vital {
  const state = riskStateForStep(step);
  switch (step.type) {
    case 'coverage':
      // Risk-complement: show the uncovered gap, not the covered percentage.
      return {
        key: 'coverage',
        label: 'Uncovered',
        value: `${Math.max(0, Math.round(100 - step.score))}%`,
        state,
      };
    case 'security':
      return { key: 'security', label: 'Security', value: openLabel(step.findingsCount), state };
    case 'performance':
      return { key: 'performance', label: 'Performance', value: openLabel(step.findingsCount), state };
    case 'testing':
      return { key: 'testing', label: 'Testing', value: openLabel(step.findingsCount), state };
    default:
      return { key: step.type, label: step.label, value: openLabel(step.findingsCount), state };
  }
}

/** Join labels into prose: "a", "a and b", "a, b and c". */
function listToProse(items: ReadonlyArray<string>): string {
  if (items.length <= 1) return items[0] ?? '';
  if (items.length === 2) return `${items[0]} and ${items[1]}`;
  return `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`;
}

export function buildPostureSummary(
  data: QualityScoresResponse,
  opts: { analysedAt?: string } = {},
): PostureSummary {
  const steps = data.steps;
  const vitals = steps.map(vitalForStep);

  const openRisks = steps
    .filter((s) => s.findingsCount > 0)
    .sort((a, b) => severity(b) - severity(a) || b.findingsCount - a.findingsCount);

  const solid = steps.filter((s) => s.passing).map((s) => s.label);
  const headline = solid.length
    ? `${listToProse(solid)} ${solid.length === 1 ? 'is' : 'are'} solid.`
    : 'Signals analysed — read each in context.';

  let detail: string;
  if (openRisks.length === 0) {
    detail = 'No open findings right now — nothing pressing.';
  } else {
    const totalOpen = openRisks.reduce((n, s) => n + s.findingsCount, 0);
    const lenses = listToProse(openRisks.map((s) => s.label.toLowerCase()));
    const sharpest = openRisks[0];
    detail = `${totalOpen} ${totalOpen === 1 ? 'finding' : 'findings'} open across ${lenses}. Sharpest right now: ${sharpest.label}.`;
  }

  const when = opts.analysedAt ? ` · analysed ${opts.analysedAt}` : '';
  const eyebrow = `Repo signals${when} · no single score — read in context`;

  return { eyebrow, headline, detail, vitals };
}
