import type { CSSProperties } from 'react';
import { cn } from '@/lib/utils';

/**
 * Semantic tone for a status pill. Kept abstract (not tied to the four base
 * task statuses) so callers that derive a richer phase — e.g. a completed task
 * sitting in a review/refactor gate, shown purple — can map onto it.
 */
export type StatusTone = 'gray' | 'blue' | 'green' | 'purple' | 'orange';

/**
 * The UI Refresh design-system status variants. These render the filled,
 * token-driven pill from the mockups (tinted background + matching dot) and
 * carry their own default label.
 */
export type StatusVariant = 'in-progress' | 'not-started' | 'done';

const TONE_CLASSES: Record<StatusTone, { dot: string; text: string }> = {
  gray: { dot: 'bg-gray-500', text: 'text-gray-500' },
  blue: { dot: 'bg-blue-500', text: 'text-blue-600 dark:text-blue-400' },
  green: { dot: 'bg-green-500', text: 'text-green-600 dark:text-green-400' },
  purple: { dot: 'bg-purple-500', text: 'text-purple-600 dark:text-purple-400' },
  orange: { dot: 'bg-orange-500', text: 'text-orange-600 dark:text-orange-400' },
};

interface VariantConfig {
  defaultLabel: string;
  /** Text colour class for the label. */
  text: string;
  /** Background tint — a mix of the accent over `--background`, so it flips on `.dark`. */
  tint: string;
  /** Extra classes for the dot (e.g. the hollow outlined dot). */
  dotClass?: string;
  /** Inline style for the dot (solid fill from a design token). */
  dotStyle?: CSSProperties;
}

const VARIANT_CONFIG: Record<StatusVariant, VariantConfig> = {
  'in-progress': {
    defaultLabel: 'In progress',
    text: 'text-blue',
    tint: 'color-mix(in oklab, var(--ds-blue) 14%, var(--background))',
    dotStyle: { background: 'var(--ds-blue)' },
  },
  'not-started': {
    defaultLabel: 'Not started',
    text: 'text-muted-foreground',
    tint: 'color-mix(in oklab, var(--ds-fg) 6%, var(--background))',
    dotClass: 'border border-border-strong bg-transparent',
  },
  done: {
    defaultLabel: 'Done',
    text: 'text-done',
    tint: 'color-mix(in oklab, var(--ds-done) 16%, var(--background))',
    dotStyle: { background: 'var(--ds-done)' },
  },
};

export interface StatusPillProps {
  /** Status text shown in the pill. Optional when `variant` is set (each variant has a default). */
  label?: string;
  /** Colour family for the legacy outlined pill (dot + text). */
  tone?: StatusTone;
  /** Design-system filled variant — takes precedence over `tone` when set. */
  variant?: StatusVariant;
  className?: string;
}

/**
 * A small status pill — a coloured dot plus a label. Two looks share this
 * component: the design-system filled `variant` (in-progress / not-started /
 * done) and the legacy outlined `tone` pill used by existing detail surfaces.
 */
export function StatusPill({ label, tone = 'gray', variant, className }: StatusPillProps) {
  if (variant) {
    const c = VARIANT_CONFIG[variant];
    return (
      <span
        data-testid="status-pill"
        data-variant={variant}
        className={cn(
          'inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[11px] font-medium whitespace-nowrap',
          c.text,
          className,
        )}
        style={{ background: c.tint }}
      >
        <span
          className={cn('w-1.5 h-1.5 rounded-full flex-shrink-0', c.dotClass)}
          style={c.dotStyle}
          aria-hidden="true"
        />
        {label ?? c.defaultLabel}
      </span>
    );
  }

  const c = TONE_CLASSES[tone];
  return (
    <span
      data-testid="status-pill"
      className={cn(
        'inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full border text-xs font-medium whitespace-nowrap',
        'border-gray-300 dark:border-gray-600',
        c.text,
        className,
      )}
    >
      <span className={cn('w-2 h-2 rounded-full flex-shrink-0', c.dot)} aria-hidden="true" />
      {label}
    </span>
  );
}

export default StatusPill;
