import type { TaskRowTask, TddPhase } from '../types';
import type { PipelineStep, PhaseConfig } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { canonicalStepType } from '@magic-ingredients/tiny-brain-core/pipeline-normalizer';
import { isPhaseComplete, isPhaseInProgress } from './tdd-phases';

/**
 * One step in the rendered commit-pipeline row: its display label and the
 * git-sourced phase it maps to. The renderer derives the chip colour from
 * `phase`. (Refactor folds into its review chip in Task 3, so only Red, Green
 * and one review entry per gate are produced here.)
 */
export interface PipelinePhase {
  readonly label: string;
  readonly phase: TddPhase;
}

/** Visual state of a single phase chip (mirrors PipelineChip's ChipState). */
export type PhaseChipState = 'done' | 'current' | 'pending' | 'skipped';

/**
 * Build the ordered phase list for a task: Red + Green lead (Green only for
 * spike tasks, which have no red phase), followed by one review entry per gate.
 * Gate set + order come from the task's immutable `pipelineSnapshot` when
 * present (so a later pipeline change can't rewrite a completed task's
 * history); labels are joined from the live catalog by type.
 */
export function buildPipelinePhases(
  reviewPipeline: PipelineStep[],
  pipelineType?: string,
  pipelineSnapshot?: readonly string[],
): PipelinePhase[] {
  const phases: PipelinePhase[] = pipelineType === 'spike'
    ? [{ label: 'Green', phase: 'green' }]
    : [
        { label: 'Red', phase: 'red' },
        { label: 'Green', phase: 'green' },
      ];
  const catalog = new Map(reviewPipeline.map((s) => [s.type, s]));
  const rawGateTypes = pipelineSnapshot ?? reviewPipeline.filter((s) => !s.hook).map((s) => s.type);
  // Canonicalise each gate id (pipeline-gate-vocab-drift): a gate pinned under
  // its analyzer id (`mutation-testing`) must render under the canonical step
  // type (`mutation`) so the chip/tab joins `task.reviews['mutation']` — the key
  // `_review persist` writes — instead of missing and reading "not reviewed yet".
  // Dedupe so a snapshot carrying both forms collapses to one pill.
  const seen = new Set<string>();
  for (const raw of rawGateTypes) {
    const type = canonicalStepType(raw);
    if (seen.has(type)) continue;
    seen.add(type);
    // The catalog is keyed by the normalised (canonical) step type, so look up
    // by canonical — an aliased gate (`mutation-testing`) still inherits its
    // configured label (e.g. "Mutation Testing") from the canonical entry.
    const step = catalog.get(type);
    const label = step?.label || type.charAt(0).toUpperCase() + type.slice(1);
    phases.push({ label, phase: `review:${type}` });
  }
  return phases;
}

/**
 * The reviewed (green) SHA a review file is named by — distinct from the
 * displayed `reviewSha`, which on a `review:` carrier is the verdict commit's
 * own SHA. Used to FETCH review detail, so the lookup resolves the
 * <greenSha>.json file. Falls back to reviewSha for the event-overlay window.
 */
export function getReviewFetchSha(task: TaskRowTask, type: string): string | undefined {
  const review = task.reviews?.[type];
  return review?.reviewedSha ?? review?.reviewSha ?? undefined;
}

/** The commit SHA that completes a given phase, or undefined if not reached. */
export function getPhaseCommitSha(task: TaskRowTask, phase: TddPhase): string | undefined {
  if (phase.startsWith('review:')) {
    return task.reviews?.[phase.slice(7)]?.reviewSha ?? undefined;
  }
  if (phase === 'red') return task.testCommitSha;
  if (phase === 'green') return task.commitSha;
  return undefined;
}

/**
 * Whether a review gate's refactor is in flight: a needs-refactoring verdict
 * has landed (the review chip folds the refactor) and the refactor has started
 * but not yet committed. The review chip must read this as live rather than
 * jumping to done the instant the verdict lands.
 */
export function isRefactorInProgress(task: TaskRowTask, gate: string): boolean {
  const r = task.reviews?.[gate];
  return !!(r && r.verdict === 'needs-refactoring' && r.refactorStartedAt && !r.refactorCommitSha);
}

/**
 * The chip state for a phase: `done` when complete, `current` when it's the
 * live phase of an in-flight task, `pending` otherwise.
 */
export function derivePhaseChipState(
  task: TaskRowTask,
  phase: TddPhase,
  config?: PhaseConfig,
): PhaseChipState {
  // RED skipped via --green: testCommitSha is the 'skipped' sentinel, which
  // reads as "complete" — surface it as skipped before the completion check.
  if (phase === 'red' && task.testCommitSha === 'skipped') {
    return 'skipped';
  }
  // A review chip folds its refactor: while a needs-refactoring refactor runs,
  // the chip stays 'current' even though the verdict (reviewSha) has landed —
  // otherwise it would jump to done and hide the live refactor window. Excludes
  // superseded (abandoned work isn't live).
  if (
    phase.startsWith('review:') &&
    task.status !== 'superseded' &&
    isRefactorInProgress(task, phase.slice('review:'.length))
  ) {
    return 'current';
  }
  if (isPhaseComplete(task, phase)) {
    return 'done';
  }
  // `isPhaseInProgress` already pinpoints the live phase from the SHAs (e.g. a
  // review gate with a landed green but no verdict yet). We must NOT let a
  // 'completed' status suppress that: a green commit can mark the task
  // completed before the review verdict lands, and during that window the
  // review is genuinely in progress. Only 'superseded' (abandoned work) is
  // excluded — its pending phases shouldn't read as live.
  const live = task.status !== 'superseded'
    && isPhaseInProgress(task, phase, config);
  return live ? 'current' : 'pending';
}
