import React, { useEffect, useMemo, useState } from 'react';
import { Loader2 } from 'lucide-react';
import { QualityPostureHeader } from './QualityPostureHeader';
import { QualityMeasured } from './QualityMeasured';
import { QualityObserved } from './QualityObserved';
import { QualityWorthDoing } from './QualityWorthDoing';
import { buildInstruments } from '../utils/quality-instruments';
import { OBSERVED_LENSES, observedFromIssues, stepForCategory } from '../utils/quality-observed';
import { rankWorthDoing } from '../utils/quality-worth-doing';
import { parseQualityData } from './QualityDetail';
import { SkillInvocationPanel } from './SkillInvocationPanel';
import { useSkillInvocation } from '../hooks/useSkillInvocation';
import { useApiKeyStatus } from '../hooks/useApiKeyStatus';
import type {
  QualityScoresResponse,
  QualityRunSummary,
  QualityRunDetail,
  StepScoreResponse,
  QualityIssue,
  StructuredRecommendation,
} from '../types';

/**
 * Non-overlapping: each category assigned to exactly ONE primary step. The
 * lens→categories rows are derived from OBSERVED_LENSES (the single source of
 * the partition); the analyser-only steps below carry no agent categories.
 */
const STEP_TO_CATEGORIES: Record<string, ReadonlyArray<string>> = {
  ...Object.fromEntries(OBSERVED_LENSES.map((lens) => [lens.step, lens.categories])),
  'tdd-compliance': [],
  'dependency-audit': [],
};

/** Steps where the score is a real percentage (not issue-derived) */
const PERCENTAGE_STEPS = new Set(['coverage']);

function scoreToGrade(score: number): string {
  if (score >= 90) return 'A';
  if (score >= 80) return 'B';
  if (score >= 70) return 'C';
  if (score >= 60) return 'D';
  return 'F';
}

/**
 * Overlay quality run issue counts onto pipeline step scores. Coverage keeps its
 * real % score; other steps get issue counts from the run. This feeds the
 * Measured instruments (via readinessData), not a per-step UI.
 */
function overlayRunData(
  pipelineSteps: ReadonlyArray<StepScoreResponse>,
  issues: ReadonlyArray<QualityIssue>,
): ReadonlyArray<StepScoreResponse> {
  const agentCategoryCounts = new Map<string, number>();
  let npmAuditCount = 0;
  for (const issue of issues) {
    if (issue.source === 'npm-audit') {
      npmAuditCount++;
      continue;
    }
    if (issue.source !== 'llm') continue;
    agentCategoryCounts.set(issue.category, (agentCategoryCounts.get(issue.category) ?? 0) + 1);
  }

  return pipelineSteps.map(step => {
    if (PERCENTAGE_STEPS.has(step.type)) {
      return step;
    }

    if (step.type === 'dependency-audit') {
      const findingsCount = npmAuditCount;
      const score = findingsCount === 0
        ? 100
        : Math.max(0, Math.round(100 - 20 * Math.log(1 + findingsCount)));
      return { ...step, score, findingsCount, passing: score >= step.threshold };
    }

    const categories = STEP_TO_CATEGORIES[step.type];
    if (!categories) return step;

    const findingsCount = categories.reduce(
      (sum, cat) => sum + (agentCategoryCounts.get(cat) ?? 0),
      0,
    );

    const score = findingsCount === 0
      ? 100
      : Math.max(0, Math.round(100 - 20 * Math.log(1 + findingsCount)));

    return {
      ...step,
      score,
      findingsCount,
      passing: score >= step.threshold,
      grade: scoreToGrade(score),
    };
  });
}

interface QualityTabProps {
  repoId: string;
  runs: ReadonlyArray<QualityRunSummary>;
  selectedRun: QualityRunDetail | null;
  selectedRunId: string | null;
  onCriteriaChange?: (criteria: { passing: number; total: number }) => void;
  onRunDeleted?: () => void;
}

/**
 * The Quality "signals" page: a plain-language posture header + vitals strip,
 * the Measured analyser instruments, and the Observed | Worth-doing registers.
 * No single score, grade, readiness bar, runs chart, or per-step console — the
 * repo's quality is read as honest signals, in context.
 */
export const QualityTab: React.FC<QualityTabProps> = ({
  repoId,
  runs,
  selectedRun,
  selectedRunId,
  onCriteriaChange,
  onRunDeleted,
}) => {
  const [pipelineData, setPipelineData] = useState<QualityScoresResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [showPanel, setShowPanel] = useState(false);
  const [coverageBreakdown, setCoverageBreakdown] = useState<Record<string, { pct: number }> | null>(null);
  const [overallCoverage, setOverallCoverage] = useState<number | null>(null);
  const [skippedTests, setSkippedTests] = useState<number | null>(null);
  const [qipGenerating, setQipGenerating] = useState(false);

  const { invoke, cancel, isRunning, output, toolCalls, error } = useSkillInvocation();
  const { hasClaudeCli, isLoading: isApiKeyLoading } = useApiKeyStatus();

  useEffect(() => {
    const fetchScores = async () => {
      setLoading(true);
      try {
        const response = await fetch(`/api/repos/${repoId}/quality-scores`);
        if (response.ok) {
          setPipelineData(await response.json());
        }
      } catch (err) {
        console.error('[QualityTab] Failed to fetch quality scores:', err);
      } finally {
        setLoading(false);
      }
    };
    fetchScores();
  }, [repoId]);

  const handleRunQuality = () => {
    setShowPanel(true);
    const prompt = 'Run a comprehensive quality analysis on this repository';
    invoke('quality', prompt, { repoId });
  };

  const handleClosePanel = () => {
    if (!isRunning) {
      setShowPanel(false);
    }
  };

  const handleDeleteRun = async () => {
    if (!selectedRunId || !repoId) return;
    try {
      const response = await fetch(`/api/repos/${repoId}/quality/${selectedRunId}`, { method: 'DELETE' });
      if (response.ok) {
        onRunDeleted?.();
      }
    } catch (err) {
      console.error('[QualityTab] Failed to delete run:', err);
    }
  };

  const selectedRunSummary = useMemo(
    () => selectedRunId ? runs.find(r => r.runId === selectedRunId) ?? null : null,
    [runs, selectedRunId],
  );

  // The posture eyebrow names when the repo was analysed — the selected run's
  // date, falling back to the most recent run.
  const analysedAt = useMemo(() => {
    const date = selectedRunSummary?.date ?? runs[0]?.date;
    return date
      ? new Date(date).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
      : undefined;
  }, [selectedRunSummary, runs]);

  const parsedRunData = useMemo(() => {
    if (!selectedRun?.rawContent) return null;
    return parseQualityData(selectedRun.rawContent);
  }, [selectedRun?.rawContent]);

  // Fetch coverage aggregate data when a run is selected — feeds the Uncovered %
  // instrument. Try agent data first (backward compat), fall back to static
  // analyser metrics.
  useEffect(() => {
    setCoverageBreakdown(null);
    setOverallCoverage(null);
    setSkippedTests(null);
    if (!selectedRunId) return;

    const applyStaticFallback = () => {
      if (selectedRun?.coverageMetrics?.overallCoverage != null) {
        setOverallCoverage(selectedRun.coverageMetrics.overallCoverage);
      }
    };

    (async () => {
      try {
        const res = await fetch(`/api/repos/${repoId}/quality/${selectedRunId}/agents/coverage`);
        if (res.ok) {
          const data: unknown = await res.json();
          if (data && typeof data === 'object' && 'overallCoverage' in data && typeof (data as Record<string, unknown>).overallCoverage === 'number') {
            setOverallCoverage((data as Record<string, unknown>).overallCoverage as number);
            if ('packageBreakdown' in data) {
              setCoverageBreakdown((data as Record<string, unknown>).packageBreakdown as Record<string, { pct: number }>);
            }
            if ('skippedTests' in data && typeof (data as Record<string, unknown>).skippedTests === 'number') {
              setSkippedTests((data as Record<string, unknown>).skippedTests as number);
            }
            return;
          }
        }
        applyStaticFallback();
      } catch {
        applyStaticFallback();
      }
    })();
  }, [repoId, selectedRunId, selectedRun?.coverageMetrics]);

  // Pipeline steps overlaid with quality run data when available — the source
  // the Measured instruments are derived from. Prefer agentFindings (per-agent
  // counts from assembly); fall back to category-mapping for legacy runs.
  const stepCards = useMemo(() => {
    const pipelineSteps = pipelineData?.steps ?? [];
    if (!parsedRunData) return pipelineSteps;

    const af = parsedRunData.agentFindings as Record<string, { issueCount: number }> | undefined;
    if (af && Object.keys(af).length > 0) {
      return pipelineSteps.map(step => {
        if (PERCENTAGE_STEPS.has(step.type)) {
          const coverageScore = overallCoverage ?? step.score;
          return {
            ...step,
            score: Math.round(coverageScore),
            passing: coverageScore >= step.threshold,
            ...(coverageBreakdown ? { packageBreakdown: coverageBreakdown } : {}),
            ...(skippedTests != null ? { skippedTests } : {}),
          };
        }
        const finding = af[step.type];
        const findingsCount = finding?.issueCount ?? 0;
        return { ...step, findingsCount, passing: findingsCount === 0 };
      });
    }

    if (parsedRunData.issues && parsedRunData.issues.length > 0) {
      return overlayRunData(pipelineSteps, parsedRunData.issues);
    }
    return pipelineSteps;
  }, [parsedRunData, pipelineData, coverageBreakdown, overallCoverage, skippedTests]);

  // Build readiness from step cards (feeds Measured + the parent's tab badge).
  const readinessData = useMemo((): QualityScoresResponse | null => {
    if (stepCards.length > 0) {
      const passing = stepCards.filter(s => s.passing).length;
      const overallScore = selectedRunSummary?.score ?? pipelineData?.overallScore ?? 0;
      return {
        steps: [...stepCards],
        overallScore,
        readiness: { passing, total: stepCards.length },
      };
    }
    return pipelineData;
  }, [stepCards, selectedRunSummary, pipelineData]);

  // Measured instruments — analyser facts framed as quantities to keep low.
  const measuredInstruments = useMemo(() => buildInstruments(readinessData), [readinessData]);

  // Observed — reviewer-agent findings grouped by lens.
  const observedLenses = useMemo(
    () => observedFromIssues(parsedRunData?.issues ?? []),
    [parsedRunData?.issues],
  );

  // Worth doing — structured recommendations ranked by risk reduced.
  const worthDoing = useMemo(
    () => rankWorthDoing(parsedRunData?.structuredRecommendations ?? []),
    [parsedRunData?.structuredRecommendations],
  );

  // Notify parent of criteria changes for tab badge
  useEffect(() => {
    if (readinessData && onCriteriaChange) {
      onCriteriaChange(readinessData.readiness);
    }
  }, [readinessData, onCriteriaChange]);

  const handleGenerateQip = async (stepType: string) => {
    if (!selectedRunId) return;
    setQipGenerating(true);
    try {
      await fetch(`/api/repos/${repoId}/quality/${selectedRunId}/qip/${stepType}`, { method: 'POST' });
    } finally {
      setQipGenerating(false);
    }
  };

  // Worth-doing "Create Fix" reuses the per-step QIP flow, routing a suggestion
  // to the pipeline step that owns its category (stepForCategory is derived
  // from the same OBSERVED_LENSES partition as the Observed grouping).
  const handleCreateFixFromSuggestion = (suggestion: StructuredRecommendation) => {
    void handleGenerateQip(stepForCategory(suggestion.category));
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-8" data-testid="quality-tab-loading">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <>
      <div className="flex flex-col h-full" data-testid="quality-tab">
        <div className="flex-1 overflow-auto px-4 pt-3 pb-7 space-y-7">
          <QualityPostureHeader
            data={readinessData}
            analysedAt={analysedAt}
            selectedRun={selectedRunSummary}
            onRunQuality={handleRunQuality}
            onDeleteRun={selectedRunId ? handleDeleteRun : undefined}
            isRunning={isRunning}
            hasClaudeCli={hasClaudeCli}
            isApiKeyLoading={isApiKeyLoading}
          />

          <QualityMeasured instruments={measuredInstruments} />

          <div className="grid gap-6 lg:grid-cols-2">
            <QualityObserved lenses={observedLenses} />
            <QualityWorthDoing
              suggestions={worthDoing}
              onCreateFix={handleCreateFixFromSuggestion}
            />
          </div>

          {qipGenerating && (
            <p data-testid="qip-generating" className="text-xs text-muted">
              Creating fix…
            </p>
          )}
        </div>
      </div>

      <SkillInvocationPanel
        isOpen={showPanel}
        onClose={handleClosePanel}
        skillName="quality"
        output={output}
        toolCalls={toolCalls}
        isRunning={isRunning}
        error={error}
        onCancel={cancel}
      />
    </>
  );
};
