import type { QualityIssue } from '../types';

/**
 * "Observed" groups reviewer-agent findings by lens — judgement, not a score.
 * A fixed set of four lenses is always shown (so a clean lens reads as a
 * deliberate "nothing here" rather than a missing section); Maintainability
 * folds in the wider code-quality cluster, mirroring the pipeline's
 * code-quality step partition.
 */

export type ObservedSeverity = QualityIssue['severity'];

export interface ObservedFinding {
  readonly severity: ObservedSeverity;
  readonly message: string;
  readonly location?: string;
}

export interface ObservedLens {
  readonly key: string;
  readonly label: string;
  readonly emoji: string;
  readonly count: number;
  readonly findings: ReadonlyArray<ObservedFinding>;
}

interface LensDef {
  readonly key: string;
  readonly label: string;
  readonly emoji: string;
  /** The pipeline step that owns this lens (for routing Create Fix → QIP). */
  readonly step: string;
  readonly categories: ReadonlyArray<QualityIssue['category']>;
}

/**
 * The single source of truth for the lens ↔ category ↔ step partition. The
 * Observed grouping, the category→step routing, and QualityTab's
 * STEP_TO_CATEGORIES all derive from this — so the "must stay in sync" hazard
 * lives in exactly one place. Every QualityIssue category appears exactly once.
 */
export const OBSERVED_LENSES: ReadonlyArray<LensDef> = [
  { key: 'security', label: 'Security', emoji: '🔒', step: 'security', categories: ['Security'] },
  { key: 'performance', label: 'Performance', emoji: '⚡', step: 'performance', categories: ['Performance'] },
  { key: 'testing', label: 'Testing', emoji: '🧪', step: 'testing', categories: ['Testing'] },
  {
    key: 'maintainability',
    label: 'Maintainability',
    emoji: '🧭',
    step: 'code-quality',
    categories: ['Maintainability', 'Architecture', 'Documentation', 'Operations', 'Reliability'],
  },
];

/** The pipeline step that owns a category, derived from OBSERVED_LENSES. */
export function stepForCategory(category: string): string {
  const lens = OBSERVED_LENSES.find((l) => (l.categories as ReadonlyArray<string>).includes(category));
  return lens?.step ?? 'code-quality';
}

const SEVERITY_ORDER: Record<ObservedSeverity, number> = {
  critical: 0,
  major: 1,
  minor: 2,
  info: 3,
};

function locationOf(issue: QualityIssue): string | undefined {
  if (!issue.file) return undefined;
  return issue.line != null ? `${issue.file}:${issue.line}` : issue.file;
}

export function groupObservedByLens(issues: ReadonlyArray<QualityIssue>): ObservedLens[] {
  return OBSERVED_LENSES.map((def) => {
    const categories = new Set<string>(def.categories);
    const findings = issues
      .filter((issue) => categories.has(issue.category))
      .map((issue) => ({ severity: issue.severity, message: issue.message, location: locationOf(issue) }))
      .sort((a, b) => SEVERITY_ORDER[a.severity] - SEVERITY_ORDER[b.severity]);

    return { key: def.key, label: def.label, emoji: def.emoji, count: findings.length, findings };
  });
}

/**
 * Observed feed from a run's issues: reviewer-agent findings only. `source ===
 * 'llm'` is the core merge convention (result-merger tags agent issues), so the
 * coupling lives here behind a tested function rather than inline glue.
 */
export function observedFromIssues(issues: ReadonlyArray<QualityIssue>): ObservedLens[] {
  return groupObservedByLens(issues.filter((issue) => issue.source === 'llm'));
}
