/**
 * Task Phase Progress
 *
 * Computes fractional progress (0-1) for a task based on pipeline phase.
 * Wraps core phaseProgress with status short-circuits for completed/superseded.
 */

import type { TaskRowTask } from '../types';
import type { PipelineStep, PhaseDeriveInput } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { phaseProgress } from '@magic-ingredients/tiny-brain-core/phase-derivation';

/**
 * Returns a 0-1 fraction representing how far through the pipeline a task is.
 *
 * - completed/superseded tasks return 1
 * - not_started tasks return 0
 * - in_progress tasks: delegates to core phaseProgress
 *
 * Pass `undefined` for reviewPipeline to use the default (adversarial-only).
 */
export function taskPhaseProgress(
  task: TaskRowTask,
  reviewPipeline?: PipelineStep[],
): number {
  if (task.status === 'completed' || task.status === 'superseded') return 1;
  if (task.status === 'not_started') return 0;

  return phaseProgress(task as PhaseDeriveInput, {
    combineRedGreenCommits: false,
    reviewPipeline,
  });
}
