export const ADVERSARIAL_STEP = {
    type: 'adversarial',
    agent: 'tiny-brain:adversarial-reviewer',
    label: 'Adversarial Review',
    emoji: '\u{1F608}', // 😈
    color: '#e45858', // red
};
