/** Default quality pipeline step types */
export const DEFAULT_QUALITY_TYPES = ['code-quality', 'coverage', 'dependency-audit', 'performance', 'security', 'testing'];
/** Known defaults for legacy string types — emoji must match capability frontmatter */
const KNOWN_DEFAULTS = {
    adversarial: { ...ADVERSARIAL_STEP },
    'spike-review': { ...SPIKE_REVIEW_STEP },
    'typescript': { ...TYPESCRIPT_HOOK_STEP },
    'eslint': { ...ESLINT_HOOK_STEP },
    'coverage': { ...CODE_COVERAGE_STEP },
    'code-quality': {
        type: 'code-quality',
        agent: 'tiny-brain:code-quality-reviewer',
        label: 'Code Quality',
        emoji: '\u{1F50D}', // 🔍
        color: '#7c4dff', // purple
    },
    'mutation': {
        type: 'mutation',
        agent: 'tiny-brain:analyzer-agent',
        label: 'Mutation Testing',
        emoji: '\u{1F9DF}', // 🧟
        color: '#8bc34a', // lime
        analyzer: 'mutation-testing',
        runsTests: true,
    },
    'performance': {
        type: 'performance',
        agent: 'tiny-brain:performance-reviewer',
        label: 'Performance Review',
        emoji: '\u{26A1}', // ⚡
        color: '#ff9800', // orange
    },
    'security': {
        type: 'security',
        agent: 'tiny-brain:security-reviewer',
        label: 'Security Review',
        emoji: '\u{1F510}', // 🔐
        color: '#2196f3', // blue
    },
    'tdd-compliance': {
        type: 'tdd-compliance',
        agent: 'tiny-brain:tdd-compliance-reviewer',
        label: 'TDD Compliance',
        emoji: '\u{2705}', // ✅
        color: '#009688', // teal
    },
    'testing': {
        type: 'testing',
        agent: 'tiny-brain:testing-reviewer',
        label: 'Testing Review',
        emoji: '\u{1F9EA}', // 🧪
        color: '#e91e63', // pink
    },
    'dependency-audit': {
        type: 'dependency-audit',
        agent: 'tiny-brain:analyzer-agent',
        label: 'Dependency Audit',
        emoji: '\u{1F4E6}', // 📦
        color: '#795548', // brown
        analyzer: 'dependency-audit',
        analyzerThreshold: { maxSeverity: 'high' },
    },
};
/** Hash an emoji to a stable hue (0-360) for generating default colors. */
export function emojiToHue(emoji) {
    let hash = 0;
    for (let i = 0; i < emoji.length; i++) {
        hash = ((hash << 5) - hash + emoji.charCodeAt(i)) | 0;
    }
    return ((hash % 360) + 360) % 360;
}
/** Convert a hue to a hex color at fixed saturation/lightness. */
function hueToHex(hue) {
    // HSL to RGB at S=60%, L=50%
    const s = 0.6, l = 0.5;
    const c = (1 - Math.abs(2 * l - 1)) * s;
    const x = c * (1 - Math.abs(((hue / 60) % 2) - 1));
    const m = l - c / 2;
    let r = 0, g = 0, b = 0;
    if (hue < 60) {
        r = c;
        g = x;
    }
    else if (hue < 120) {
        r = x;
        g = c;
    }
    else if (hue < 180) {
        g = c;
        b = x;
    }
    else if (hue < 240) {
        g = x;
        b = c;
    }
    else if (hue < 300) {
        r = x;
        b = c;
    }
    else {
        r = c;
        b = x;
    }
    const toHex = (v) => Math.round((v + m) * 255).toString(16).padStart(2, '0');
    return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}
/**
 * Aliases mapping analyzer ids → canonical pipeline step types.
 *
 * After the analyzer migration, several callers (review CLI,
 * persisted-review lookups) hand stringToStep an analyzer id like
 * `mutation-testing` rather than the step type `mutation`. Without
 * normalisation those would fall through to the unknown-type
 * placeholder — visible in CLI as a 🔍 instead of the configured
 * step's real emoji.
 *
 * Mirrors `STEP_TYPE_ALIASES` in `services/planning/persist.ts`;
 * keep both lists in lockstep.
 */
export const STEP_TYPE_ALIASES = {
    'mutation-testing': 'mutation',
    'code-coverage': 'coverage',
};
/**
 * Canonicalise an analyzer / capability / step id to the single step-type
 * vocabulary (the registry / KNOWN_DEFAULTS ids). The analyzer registry and
 * `capabilities/installed.json` use longer aliases (`mutation-testing`,
 * `code-coverage`) for what the step/capability registry calls `mutation` /
 * `coverage`; this collapses them so id joins across those surfaces line up.
 * Unknown ids pass through unchanged.
 */
export function canonicalStepType(type) {
    // Own-key check so inherited Object keys (`__proto__`, `constructor`) pass
    // through unchanged rather than resolving to a prototype member.
    return Object.hasOwn(STEP_TYPE_ALIASES, type) ? STEP_TYPE_ALIASES[type] : type;
}
export function stringToStep(type) {
    const canonical = canonicalStepType(type);
    if (KNOWN_DEFAULTS[canonical]) {
        return { ...KNOWN_DEFAULTS[canonical] };
    }
    // Generate sensible defaults for unknown types
    const label = canonical
        .split('-')
        .map(w => w.charAt(0).toUpperCase() + w.slice(1))
        .join(' ');
    const emoji = '\u{1F50D}';
    return {
        type: canonical,
        agent: `tiny-brain:${canonical}-reviewer`,
        label,
        emoji,
        color: hueToHex(emojiToHue(emoji)),
    };
}
export function isPipelineStep(entry) {
    return (typeof entry === 'object' &&
        entry !== null &&
        'type' in entry &&
        'agent' in entry &&
        'label' in entry &&
        'emoji' in entry);
}
/**
 * A step is a *static analyser* iff it carries an `analyzer` id or runs through
 * the analyzer-agent wrapper. This is derived, never stored — the per-commit
 * lane accepts only static analysers; agentic reviewers (e.g. Adversarial) are
 * per-task gates. Keep this the single definition both the UI and API reuse.
 */
export function isStaticAnalyserStep(step) {
    return step.analyzer != null || step.agent === 'tiny-brain:analyzer-agent';
}
/**
 * Return the first per-commit (`hook: 'pre-commit'`) step that is NOT a static
 * analyser, or null when the per-commit lane is clean. Other lanes are ignored.
 */
export function findNonStaticPerCommitStep(steps) {
    return steps.find(s => s.hook === 'pre-commit' && !isStaticAnalyserStep(s)) ?? null;
}
/** Thrown when an agentic step is placed in the static-only per-commit lane. */
export class PerCommitStaticError extends Error {
    constructor(message) {
        super(message);
        this.name = 'PerCommitStaticError';
    }
}
/**
 * Guard the per-commit lane: throw a {@link PerCommitStaticError} if any
 * `hook: 'pre-commit'` step is not a static analyser. The write path (API)
 * catches this to reject the payload; pure and testable on its own.
 */
export function assertPerCommitStatic(steps) {
    const offender = findNonStaticPerCommitStep(steps);
    if (offender) {
        throw new PerCommitStaticError(`Per-commit step "${offender.label}" is not a static analyser. ` +
            'The per-commit lane runs on every commit and accepts static analysers only ' +
            '(TypeScript, ESLint); move agentic reviewers to the per-task lane.');
    }
}
const SOURCE_KEY_HOOK = {
    reviewPipeline: 'pre-commit',
    pushPipeline: 'pre-push',
};
/**
 * Normalize a pipeline config array. Accepts string[], PipelineStep[], or mixed.
 * Returns PipelineStep[] with all entries as full objects.
 *
 * For object entries with a known type, KNOWN_DEFAULTS are merged UNDER the
 * user entry. This means optional intrinsic fields the user omits
 * (`runsTests`, `analyzer`, `analyzerThreshold`) are inherited from defaults,
 * while everything the user explicitly sets wins. `analyzerThreshold` is
 * replaced whole-cloth when the user provides one (no deep merge).
 *
 * Note: `agent`, `label`, and `emoji` are required by `isPipelineStep`, so
 * they will always come from the user — defaults can never surface them.
 *
 * Hook precedence (highest → lowest):
 *   1. User-explicit `hook` field on the step object
 *   2. `options.sourceKey` mapping (`reviewPipeline`→`pre-commit`,
 *      `pushPipeline`→`pre-push`)
 *   3. `KNOWN_DEFAULTS[type].hook`
 *   4. undefined
 *
 * The sourceKey-over-KNOWN_DEFAULTS ordering is deliberate: it ensures a
 * step placed in the "wrong" array gets the array's hook (and so runs at
 * that hook's stage) rather than silently filtering out.
 */
export function normalizePipeline(input, options) {
    if (!input)
        return [];
    const sourceHook = options?.sourceKey ? SOURCE_KEY_HOOK[options.sourceKey] : undefined;
    return input.map(entry => {
        let step;
        // Capture the user's explicit hook *before* KNOWN_DEFAULTS merge so we
        // can let sourceKey override the type-default (but not the user's
        // explicit value). String entries can't carry an explicit hook.
        const userExplicitHook = isPipelineStep(entry) ? entry.hook : undefined;
        if (isPipelineStep(entry)) {
            const defaults = KNOWN_DEFAULTS[entry.type];
            // Merge defaults under user entry — user wins for any field they set,
            // but intrinsic flags (runsTests, etc.) survive when user omits them.
            step = defaults ? { ...defaults, ...entry } : entry;
        }
        else {
            step = stringToStep(String(entry));
        }
        // Apply sourceKey hook when the user didn't explicitly set one. This
        // wins over KNOWN_DEFAULTS.hook so a misplaced step (e.g. typescript
        // in pushPipeline) runs on the array's hook rather than silently
        // mismatching. Re-normalisation is idempotent because the previous
        // pass set step.hook = sourceHook, which equals what we'd write now.
        if (sourceHook && userExplicitHook === undefined) {
            step = { ...step, hook: sourceHook };
        }
        // Default maxAttempts for tollgate steps
        if (step.mode === 'tollgate' && step.maxAttempts === undefined) {
            step = { ...step, maxAttempts: 3 };
        }
        // Clamp weight (min 0) and threshold (0-100)
        if (step.weight !== undefined && step.weight < 0) {
            step = { ...step, weight: 0 };
        }
        if (step.threshold !== undefined) {
            step = { ...step, threshold: Math.max(0, Math.min(100, step.threshold)) };
        }
        // Default color from emoji hash
        if (!step.color) {
            step = { ...step, color: hueToHex(emojiToHue(step.emoji)) };
        }
        return step;
    });
}
export function getHookSteps(pipeline, hookName, options) {
    return pipeline.filter(s => {
        if (s.hook !== hookName)
            return false;
        if (options?.skipTestRunners && s.runsTests)
            return false;
        if (options?.onlyTestRunners && !s.runsTests)
            return false;
        return true;
    });
}
