'use client'

import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { Skeleton } from '@/components/ui/skeleton'
import { Drama, AlertCircle } from 'lucide-react'
import { ResizablePanel, ResizablePanelGroup } from '@/components/ui/resizable'
import { useSSE } from '@/hooks/useSSE'
import { useLibrary } from '@/contexts/LibraryContext'
import { cn } from '@/lib/utils'
import type { LocalPersona, LibraryPersona } from '@/types/personas'

export default function TBSPersonasPage() {
  const navigate = useNavigate()
  const sseState = useSSE()
  const { getAuthHeaders } = useLibrary()
  const currentPersona = sseState.personaId || 'default'
  const [personas, setPersonas] = useState<LocalPersona[]>([])
  const [systemPersonas, setSystemPersonas] = useState<LibraryPersona[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    fetchPersonas()
    fetchSystemPersonas()
  }, [])

  const fetchPersonas = async () => {
    try {
      const response = await fetch('/api/personas')
      if (!response.ok) throw new Error('Failed to fetch personas')
      const data = await response.json()
      setPersonas(data.personas || [])
    } catch (err) {
      setError('Failed to load personas')
      console.error('Error fetching personas:', err)
    } finally {
      setLoading(false)
    }
  }

  const fetchSystemPersonas = async () => {
    try {
      const response = await fetch('/api/library/personas', { headers: getAuthHeaders() || {} })
      if (!response.ok) return
      const data = await response.json()
      const list = Array.isArray(data.personas) ? data.personas : Array.isArray(data) ? data : []
      setSystemPersonas(list)
    } catch (err) {
      console.error('Error fetching system personas:', err)
      setSystemPersonas([])
    }
  }

  const describe = (persona: LocalPersona): string =>
    persona.persona?.system?.metadata?.description ||
    persona.metadata?.description ||
    'Local persona configuration'

  return (
    <div className="h-full">
      <ResizablePanelGroup direction="horizontal">
        <ResizablePanel defaultSize={100} minSize={30}>
          <div className="h-full overflow-auto">
            <div className="mx-auto max-w-7xl space-y-6 p-4 md:p-6 lg:p-8">
              {error && (
                <div className="flex items-center gap-2 rounded-2xl border border-destructive/40 bg-destructive/5 p-4">
                  <AlertCircle className="h-5 w-5 text-destructive" />
                  <p className="text-sm text-destructive">{error}</p>
                </div>
              )}

              {/* Local Personas */}
              <section
                data-testid="local-personas-section"
                className="rounded-2xl panel p-5 md:p-6"
              >
                <h2 className="display text-base font-semibold">Local Personas</h2>
                <p className="text-sm text-muted">Your local personas and customizations</p>

                {loading ? (
                  <div className="mt-4 grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                    {[1, 2, 3].map((i) => (
                      <div key={i} className="rounded-2xl border border-border p-4">
                        <Skeleton className="mb-3 h-11 w-11 rounded-lg" />
                        <Skeleton className="h-4 w-3/4" />
                        <Skeleton className="mt-2 h-3 w-1/2" />
                      </div>
                    ))}
                  </div>
                ) : personas.length === 0 ? (
                  <div className="mt-4 rounded-2xl border border-dashed border-border py-12 text-center">
                    <Drama className="mx-auto mb-4 h-12 w-12 text-subtle" />
                    <p className="mb-1 text-lg font-medium">No personas found</p>
                    <p className="text-sm text-muted">Create your first persona or sync from the library</p>
                  </div>
                ) : (
                  <div className="mt-4 grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                    {personas.map((persona) => {
                      const name = persona.name
                      const isActive = name === currentPersona
                      const tags = persona.metadata?.tags ?? []
                      const version = persona.metadata?.version
                      const sourceLibrary = persona.metadata?.sourceLibrary
                      return (
                        <div
                          key={name}
                          data-testid={`persona-card-${name}`}
                          data-active={isActive ? 'true' : 'false'}
                          onClick={() => navigate(`/personas/${name}`)}
                          className={cn(
                            // `panel` gives the raised surface; for the active card the
                            // bg-primary/5 utility (utilities layer after the component
                            // class) tints over the panel white while keeping its border
                            // + shadow, restoring the active tint alongside the ring.
                            'panel lift relative cursor-pointer rounded-2xl p-4 transition-shadow',
                            isActive ? 'bg-primary/5 ring-2 ring-primary' : 'hover:shadow-md',
                          )}
                        >
                          {isActive && (
                            <span
                              className="absolute right-3 top-3 rounded-md px-2 py-0.5 text-[10px] font-semibold text-white"
                              style={{ background: 'var(--color-primary)' }}
                            >
                              Active
                            </span>
                          )}
                          <div className="flex items-start gap-3">
                            <span
                              className="grid h-11 w-11 shrink-0 place-items-center rounded-lg"
                              style={{
                                background: `color-mix(in oklab, ${isActive ? 'var(--color-primary)' : 'var(--color-blue)'} 16%, transparent)`,
                              }}
                            >
                              <Drama
                                className="h-6 w-6"
                                style={{ color: isActive ? 'var(--color-primary)' : 'var(--color-blue)' }}
                              />
                            </span>
                            <div className="min-w-0">
                              <p className="display truncate text-lg font-semibold leading-tight">{name}</p>
                              <p className="mt-1 line-clamp-2 text-sm text-muted">{describe(persona)}</p>
                            </div>
                          </div>
                          <div className="mt-3 flex flex-wrap items-center gap-1.5">
                            {tags[0] && (
                              <span className="rounded-md border border-border px-1.5 py-0.5 text-[11px] text-muted">
                                {tags[0]}
                              </span>
                            )}
                            {version && (
                              <span className="mono rounded-md border border-border px-1.5 py-0.5 text-[11px] text-muted">
                                v{version}
                              </span>
                            )}
                          </div>
                          {tags.length > 0 && (
                            <p className="mono mt-2 text-[11px] text-subtle">
                              {tags.slice(0, 3).map((t) => `#${t}`).join(' ')}
                            </p>
                          )}
                          {sourceLibrary && (
                            <div className="mt-3 rounded-md panel-flat p-2">
                              <p className="truncate text-xs font-medium">{sourceLibrary.name}</p>
                              {sourceLibrary.version && (
                                <p className="text-[10px] text-subtle">Library v{sourceLibrary.version}</p>
                              )}
                            </div>
                          )}
                        </div>
                      )
                    })}
                  </div>
                )}
              </section>

              {/* Persona Library */}
              <section
                data-testid="library-personas-section"
                className="rounded-2xl panel-flat p-5 md:p-6"
              >
                <h2 className="display text-base font-semibold">Persona Library</h2>
                <p className="text-sm text-muted">Available personas from the Tiny Brain library</p>
                <div className="mt-4 grid gap-3 md:grid-cols-2 lg:grid-cols-3">
                  {!Array.isArray(systemPersonas) || systemPersonas.length === 0 ? (
                    <div className="col-span-full rounded-2xl border border-dashed border-border py-8 text-center">
                      <Drama className="mx-auto mb-3 h-8 w-8 text-subtle" />
                      <p className="mb-1 text-sm font-medium">No Library Personas</p>
                      <p className="text-xs text-muted">Library personas will appear here once available</p>
                    </div>
                  ) : (
                    systemPersonas.map((persona, index) => (
                      <div
                        key={persona.path || `persona-${index}`}
                        data-testid={`library-persona-${persona.metadata?.name ?? index}`}
                        className="rounded-2xl panel p-4"
                      >
                        <div className="flex items-start gap-3">
                          <span
                            className="grid h-10 w-10 shrink-0 place-items-center rounded-lg"
                            style={{ background: 'color-mix(in oklab, var(--color-blue) 16%, transparent)' }}
                          >
                            <Drama className="h-5 w-5" style={{ color: 'var(--color-blue)' }} />
                          </span>
                          <div className="min-w-0 flex-1">
                            <p className="font-medium">{persona.metadata?.name || 'Unnamed'}</p>
                            <p className="mt-1 line-clamp-2 text-xs text-muted">
                              {persona.metadata?.description || 'No description available'}
                            </p>
                            <div className="mt-2 flex flex-wrap items-center gap-1.5">
                              {persona.metadata?.category && (
                                <span className="rounded-md border border-border px-1.5 py-0.5 text-[11px] text-muted">
                                  {persona.metadata.category}
                                </span>
                              )}
                              {persona.metadata?.version && (
                                <span className="mono rounded-md border border-border px-1.5 py-0.5 text-[11px] text-muted">
                                  v{persona.metadata.version}
                                </span>
                              )}
                            </div>
                          </div>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </section>
            </div>
          </div>
        </ResizablePanel>
      </ResizablePanelGroup>
    </div>
  )
}
