import { cn } from '@/lib/utils';

/** The statuses a work-area list can be filtered by. */
export type ListStatus = 'not_started' | 'in_progress' | 'completed' | 'archived';

/** All statuses, in display order. */
export const ALL_LIST_STATUSES: readonly ListStatus[] = [
  'not_started',
  'in_progress',
  'completed',
  'archived',
];

/**
 * The statuses shown by default — active work only. Completed and archived
 * items are hidden until their pills are toggled on.
 */
export const DEFAULT_LIST_STATUSES: readonly ListStatus[] = ['not_started', 'in_progress'];

const LABELS: Record<ListStatus, string> = {
  not_started: 'Not started',
  in_progress: 'In progress',
  completed: 'Completed',
  archived: 'Archived',
};

// Per-status colour coding, mirroring the StatusPill tones (gray / blue / green
// / amber). Text is always tinted by status; the active pill also gets a
// coloured border + faint fill, while inactive pills are dimmed.
const TONE: Record<ListStatus, { text: string; activeBorder: string; activeBg: string }> = {
  not_started: { text: 'text-gray-500', activeBorder: 'border-gray-400', activeBg: 'bg-gray-500/10' },
  in_progress: { text: 'text-blue-600 dark:text-blue-400', activeBorder: 'border-blue-400', activeBg: 'bg-blue-500/10' },
  completed: { text: 'text-green-600 dark:text-green-400', activeBorder: 'border-green-400', activeBg: 'bg-green-500/10' },
  archived: { text: 'text-amber-600 dark:text-amber-400', activeBorder: 'border-amber-400', activeBg: 'bg-amber-500/10' },
};

export interface ListStatusFilterProps {
  /** The currently-active statuses. Items matching any active status are shown. */
  active: ReadonlySet<ListStatus>;
  /** Toggle a status on or off. */
  onToggle: (status: ListStatus) => void;
  /** Optional per-status counts rendered inside each pill. */
  counts?: Partial<Record<ListStatus, number>>;
  className?: string;
}

/**
 * The list-column status filter from the UI Refresh mockups: a row of
 * multi-select pills (Not started, In progress, Completed, Archived) that
 * narrow the plans / fixes / spikes list. Each pill independently toggles its
 * status; the default view ({@link DEFAULT_LIST_STATUSES}) shows active work
 * and hides completed and archived items.
 */
export function ListStatusFilter({ active, onToggle, counts, className }: ListStatusFilterProps) {
  return (
    <div role="group" aria-label="Filter by status" className={cn('flex items-stretch gap-1.5', className)}>
      {ALL_LIST_STATUSES.map((status) => {
        const isActive = active.has(status);
        const count = counts?.[status];
        return (
          <button
            key={status}
            type="button"
            aria-pressed={isActive}
            onClick={() => onToggle(status)}
            // Count stacked above the label keeps all four pills on one line;
            // colour is keyed to the status, dimmed while the pill is inactive.
            className={cn(
              'flex flex-1 flex-col items-center justify-center gap-0.5 rounded-lg border px-2 py-1 transition-all',
              TONE[status].text,
              isActive
                ? cn(TONE[status].activeBorder, TONE[status].activeBg)
                : 'border-border opacity-60 hover:opacity-100',
            )}
          >
            <span className="mono text-sm font-semibold leading-none">{count ?? 0}</span>
            <span className="text-[10px] leading-none">{LABELS[status]}</span>
          </button>
        );
      })}
    </div>
  );
}

export default ListStatusFilter;
