/**
 * Phase Derivation Module
 *
 * Derives TDD phase from task data using SHAs as completion markers.
 * All review/refactor phases are generic — driven by the reviews map
 * and pipeline config. No hardcoded agent names.
 */
import { canonicalStepType } from '../config/pipeline-normalizer.js';
/**
 * Returns the ordered list of pipeline phases.
 */
/** Filter a pipeline to only review steps (exclude hook steps) */
export function getReviewSteps(pipeline) {
    return pipeline.filter(s => !s.hook);
}
/**
 * The ordered review-gate names of a pipeline — its non-hook steps' types.
 * This IS the gate-set: the `pipelineSnapshot` pinned at a task's first commit,
 * the gates derivePhase walks, and the fallback when a task carries no
 * snapshot. Single definition so the pin can never desync from what the phase
 * walk reads (the filter was hand-copied across pipeline.ts, pipeline-service.ts
 * and this file before being lifted here).
 */
export function pipelineGateSet(pipeline) {
    return getReviewSteps(pipeline).map((s) => s.type);
}
/**
 * The canonical, deduped gate-set a task walks: the pinned `pipelineSnapshot`
 * when present, else the configured pipeline's gates. Each id is canonicalised
 * (pipeline-gate-vocab-drift) so a gate pinned under its analyzer id
 * (`mutation-testing`) walks under the canonical step type (`mutation`) — the
 * key the verdict / review record is stored under. Without this a task is stuck
 * on `review:mutation-testing` forever, never matching its `mutation` verdict.
 */
function taskGateSet(snapshot, reviewPipeline) {
    const raw = snapshot ?? (reviewPipeline ? pipelineGateSet(reviewPipeline) : []);
    const seen = new Set();
    const out = [];
    for (const gate of raw) {
        const canonical = canonicalStepType(gate);
        if (seen.has(canonical))
            continue;
        seen.add(canonical);
        out.push(canonical);
    }
    return out;
}
export function getActivePipeline(config) {
    const phases = ['red'];
    if (!config.combineRedGreenCommits) {
        phases.push('green');
    }
    if (config.reviewPipeline) {
        for (const step of getReviewSteps(config.reviewPipeline)) {
            phases.push(`review:${step.type}`, `refactor:${step.type}`);
        }
    }
    phases.push('complete');
    return phases;
}
/**
 * Task-specific pipeline phases — walks `task.pipelineSnapshot` when
 * present (the immutable per-task lock-in) and falls back to
 * `config.reviewPipeline` for legacy tasks. Use this from any function
 * that asks "what phases is THIS task traversing"; reserve
 * `getActivePipeline(config)` for "what's the configured pipeline."
 */
export function getActivePipelineForTask(task, config) {
    const phases = ['red'];
    if (!config.combineRedGreenCommits) {
        phases.push('green');
    }
    const gates = taskGateSet(task.pipelineSnapshot, config.reviewPipeline);
    for (const gate of gates) {
        phases.push(`review:${gate}`, `refactor:${gate}`);
    }
    phases.push('complete');
    return phases;
}
/**
 * Derives the current TDD phase by walking the pipeline.
 * The first phase without its completion SHA is the current phase.
 */
export function derivePhase(task, config = { combineRedGreenCommits: false }) {
    if (!task.redStartedAt)
        return 'not_started';
    if (!task.testCommitSha)
        return 'red';
    if (!task.commitSha) {
        return config.combineRedGreenCommits ? 'red' : 'green';
    }
    // Prefer the task's own snapshot when present — captured at task
    // entry, immutable thereafter. Falls back to the configured pipeline
    // for legacy tasks that pre-date the snapshot field (migration grace).
    const gates = taskGateSet(task.pipelineSnapshot, config.reviewPipeline);
    for (const gate of gates) {
        const record = task.reviews?.[gate] ?? {};
        if (!record.reviewSha)
            return `review:${gate}`;
        // A 'failed' verdict (the step's tool could not run) is a non-blocking
        // terminal state — the gate is recorded but demands no refactor, so we
        // advance past it (pipeline-step-failed-verdict).
        if (record.verdict === 'failed')
            continue;
        if (!record.refactorCommitSha)
            return `refactor:${gate}`;
    }
    return 'complete';
}
/**
 * Checks if a specific phase has its completion SHA set.
 */
export function isPhaseComplete(task, phase) {
    if (phase === 'red')
        return !!task.testCommitSha;
    if (phase === 'green')
        return !!task.commitSha;
    if (phase.startsWith('review:')) {
        const type = canonicalStepType(phase.slice('review:'.length));
        return !!(task.reviews?.[type]?.reviewSha);
    }
    if (phase.startsWith('refactor:')) {
        const type = canonicalStepType(phase.slice('refactor:'.length));
        return !!(task.reviews?.[type]?.refactorCommitSha);
    }
    return false;
}
/**
 * Checks if a phase is currently in progress.
 * When config is provided, uses pipeline ordering to ensure only the
 * current phase returns true (not future phases).
 */
export function isPhaseInProgress(task, phase, config) {
    if (phase === 'red')
        return !!task.redStartedAt && !task.testCommitSha;
    if (phase === 'green')
        return !!task.testCommitSha && !task.commitSha;
    if (phase.startsWith('refactor:')) {
        const type = canonicalStepType(phase.slice('refactor:'.length));
        const record = task.reviews?.[type] ?? {};
        // A failed gate is terminal — it awaits no refactor (pipeline-step-failed-verdict).
        if (record.verdict === 'failed')
            return false;
        return !!record.reviewSha && !record.refactorCommitSha;
    }
    if (phase.startsWith('review:')) {
        const type = canonicalStepType(phase.slice('review:'.length));
        const record = task.reviews?.[type] ?? {};
        if (!task.commitSha || record.reviewSha)
            return false;
        // Check all prior pipeline stages are done. Walk the task's snapshot
        // when present (the immutable per-task lock-in) so a mid-flight
        // config change can't shift what counts as a "prior" gate; fall
        // back to the configured pipeline for legacy tasks.
        const priorGates = taskGateSet(task.pipelineSnapshot, config?.reviewPipeline);
        for (const priorType of priorGates) {
            if (priorType === type)
                break;
            const priorRecord = task.reviews?.[priorType] ?? {};
            if (!priorRecord.reviewSha)
                return false;
            if (!priorRecord.refactorCommitSha)
                return false;
        }
        return true;
    }
    return false;
}
/**
 * Checks if all pipeline stages are complete.
 */
export function isTaskComplete(task, config = { combineRedGreenCommits: false }) {
    return derivePhase(task, config) === 'complete';
}
/**
 * Returns the duration of a phase in milliseconds.
 */
export function getPhaseDuration(task, phase) {
    if (phase === 'red' && task.redStartedAt && task.redCompletedAt) {
        return dateDiff(task.redStartedAt, task.redCompletedAt);
    }
    if (phase === 'green' && task.greenStartedAt && task.greenCompletedAt) {
        return dateDiff(task.greenStartedAt, task.greenCompletedAt);
    }
    if (phase.startsWith('review:')) {
        const record = task.reviews?.[canonicalStepType(phase.slice('review:'.length))];
        if (record?.startedAt && record?.completedAt) {
            return dateDiff(record.startedAt, record.completedAt);
        }
    }
    if (phase.startsWith('refactor:')) {
        const record = task.reviews?.[canonicalStepType(phase.slice('refactor:'.length))];
        if (record?.refactorStartedAt && record?.refactorCompletedAt) {
            return dateDiff(record.refactorStartedAt, record.refactorCompletedAt);
        }
    }
    return undefined;
}
function dateDiff(a, b) {
    const ms = new Date(b).getTime() - new Date(a).getTime();
    return Number.isNaN(ms) ? undefined : ms;
}
/**
 * Returns fractional progress (0–1) for a task.
 */
export function phaseProgress(task, config = { combineRedGreenCommits: false }) {
    const phase = derivePhase(task, config);
    if (phase === 'not_started')
        return 0;
    if (phase === 'complete')
        return 1;
    // Use the task's own pipeline (snapshot when present, config fallback
    // for legacy). Building it from `config` alone would collapse to 0%
    // when a snapshot's gate has been removed from the current config —
    // exactly the migration-grace failure mode the snapshot prevents.
    const pipeline = getActivePipelineForTask(task, config);
    const totalSteps = pipeline.length;
    if (totalSteps <= 0)
        return 0;
    const currentIndex = pipeline.indexOf(phase);
    if (currentIndex === -1)
        return 0;
    return (currentIndex + 1) / totalSteps;
}
/**
 * Average progress across a list of tasks.
 */
export function computeWeightedProgress(tasks, config = { combineRedGreenCommits: false }) {
    if (tasks.length === 0)
        return 0;
    const sum = tasks.reduce((acc, t) => acc + phaseProgress(t, config), 0);
    return sum / tasks.length;
}
