import React from 'react';
import { LucideIcon, ArrowLeft, Settings } from 'lucide-react';
import { useLibrary } from '../../contexts/LibraryContext';
import { useCurrentRepo } from '../../contexts/CurrentRepoContext';
import { useLocation, useNavigate } from 'react-router-dom';
import ThemeToggle from '../ThemeToggle';
import { RepoHeader } from './RepoHeader';
import { cn } from '@/lib/utils';

interface HeaderProps {
  currentItem?: {
    title: string;
    icon: LucideIcon;
  };
}

/** The PRO plan badge; its border/text tint reflects library reachability. */
function ProBadge({ libReachable }: { libReachable: boolean }) {
  return (
    <span
      title={libReachable ? 'Library connected' : 'Library not reachable'}
      className={cn(
        'rounded-md border px-2.5 py-0.5 text-[11px] font-semibold tracking-widest transition-colors',
        libReachable ? 'border-border-strong text-blue' : 'border-border text-muted-foreground',
      )}
    >
      PRO
    </span>
  );
}

/** The header's right cluster: theme toggle first, then the PRO badge (PRO
 *  rightmost). Shared by both header branches so they stay consistent. */
function HeaderRightCluster({ hasCredentials, libReachable }: { hasCredentials: boolean; libReachable: boolean }) {
  return (
    <div className="flex shrink-0 items-center gap-3">
      <ThemeToggle />
      {hasCredentials && <ProBadge libReachable={libReachable} />}
    </div>
  );
}

export const Header: React.FC<HeaderProps> = ({
  currentItem
}) => {
  const { connectionStatus, hasCredentials } = useLibrary();
  const { repo: currentRepo } = useCurrentRepo();
  const libReachable = connectionStatus === 'connected';
  const location = useLocation();
  const navigate = useNavigate();

  // Check if we're on a detail page
  const isPersonaDetailPage = location.pathname.match(/^\/personas\/[^/]+$/);
  const isRepoDetailPage = location.pathname.match(/^\/repos\/[^/]+$/);
  const isSettingsPage = location.pathname === '/settings';
  const repoIdFromPath = isRepoDetailPage ? decodeURIComponent(location.pathname.split('/')[2] ?? '') : null;

  // Repo workspace: a dedicated header (breadcrumb + path + plan badge). The
  // tiny-brain logo lives in the sidebar now, so this header carries no logo.
  if (isRepoDetailPage) {
    return (
      <header className="flex h-16 items-center justify-between gap-4 px-3">
        <RepoHeader
          className="flex-1"
          repoName={currentRepo?.name ?? repoIdFromPath ?? ''}
          repoPath={currentRepo?.path}
          onBack={() => navigate('/repos')}
        />
        <HeaderRightCluster hasCredentials={hasCredentials} libReachable={libReachable} />
      </header>
    );
  }

  return (
    <header
      className={cn(
        'flex h-16 items-center justify-between gap-4 px-3',
        // The settings pane has its own tab-bar underline directly below, so the
        // header's own bottom border would double up right above the tabs.
        !isSettingsPage && 'border-b border-border',
      )}
    >
      <div className="flex min-w-0 items-center">
        {isPersonaDetailPage ? (
          <button
            onClick={() => navigate('/personas')}
            className="-mx-2 flex items-center gap-2 rounded-lg px-2 py-1 text-muted-foreground transition-colors hover:text-foreground"
          >
            <ArrowLeft className="h-4 w-4" />
            <span className="font-medium">Back to Personas</span>
          </button>
        ) : isSettingsPage ? (
          <div className="flex items-center gap-2">
            <Settings className="h-5 w-5" />
            <span className="font-medium">Settings</span>
          </div>
        ) : (
          currentItem && (
            <div className="flex items-center gap-2">
              <currentItem.icon className="h-5 w-5" />
              <span className="font-medium">{currentItem.title}</span>
            </div>
          )
        )}
      </div>

      {/* Right side: theme chooser then PRO badge (shared with the repo-detail
          branch for a consistent right cluster). */}
      <HeaderRightCluster hasCredentials={hasCredentials} libReachable={libReachable} />
    </header>
  );
};