import React, { createContext, useCallback, useContext, useRef, useState } from 'react';

interface DetailsPopoverOptions {
  width?: string;
  onClose?: () => void;
}

interface DetailsPopoverContextValue {
  open: (content: React.ReactNode, options?: DetailsPopoverOptions) => void;
  close: () => void;
}

const DetailsPopoverContext = createContext<DetailsPopoverContextValue | null>(null);

const noop: DetailsPopoverContextValue = {
  open: () => {},
  close: () => {},
};

export const useDetailsPopover = (): DetailsPopoverContextValue => {
  const ctx = useContext(DetailsPopoverContext);
  return ctx ?? noop;
};

export const DetailsPopoverProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [content, setContent] = useState<React.ReactNode>(null);
  const [isOpen, setIsOpen] = useState(false);
  const [width, setWidth] = useState('w-96');
  const onCloseRef = useRef<(() => void) | undefined>();

  const open = useCallback((newContent: React.ReactNode, options?: DetailsPopoverOptions) => {
    setContent(newContent);
    setWidth(options?.width ?? 'w-96');
    onCloseRef.current = options?.onClose;
    setIsOpen(true);
  }, []);

  const close = useCallback(() => {
    setIsOpen(false);
    setContent(null);
    onCloseRef.current?.();
    onCloseRef.current = undefined;
  }, []);

  return (
    <DetailsPopoverContext.Provider value={{ open, close }}>
      {children}
      {isOpen && (
        <>
          <div
            data-testid="details-popover-backdrop"
            className="fixed inset-0 bg-black/50 z-40 transition-opacity"
            onClick={close}
          />
          <div
            data-testid="details-popover-panel"
            className={`fixed inset-y-0 right-0 ${width} bg-white dark:bg-dark-bg-primary border-l border-border dark:border-dark-border shadow-xl z-50 transform transition-transform duration-300 ease-in-out animate-slide-in-right`}
          >
            {content}
          </div>
        </>
      )}
    </DetailsPopoverContext.Provider>
  );
};
