import React, { useMemo } from 'react';
import { cn } from '@/lib/utils';
import { Archive, GitBranch } from 'lucide-react';
import WorktreePill from './WorktreePill';
import { Tooltip, TooltipContent, TooltipTrigger } from './ui/tooltip';
import { StatusPill, type StatusVariant } from './StatusPill';
import { GradientProgress } from './ui/GradientProgress';
import { deriveEffectiveStatus } from '../utils/effective-task-status';
import type { Plan } from '../types';

// Format date to relative time
function formatRelativeTime(dateStr: string | undefined): string {
  if (!dateStr) return 'Never';
  
  const date = new Date(dateStr);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
  const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
  const diffMinutes = Math.floor(diffMs / (1000 * 60));
  
  if (diffMinutes < 1) return 'Just now';
  if (diffMinutes < 60) return `${diffMinutes}m ago`;
  if (diffHours < 24) return `${diffHours}h ago`;
  if (diffDays === 0) return 'Today';
  if (diffDays === 1) return 'Yesterday';
  if (diffDays < 7) return `${diffDays} ${diffDays === 1 ? 'day' : 'days'} ago`;
  if (diffDays < 30) {
    const weeks = Math.floor(diffDays / 7);
    return `${weeks} ${weeks === 1 ? 'week' : 'weeks'} ago`;
  }
  if (diffDays < 365) {
    const months = Math.floor(diffDays / 30);
    if (months === 1 && diffDays > 30) {
      return 'over a month ago';
    }
    return `${months} ${months === 1 ? 'month' : 'months'} ago`;
  }
  const years = Math.floor(diffDays / 365);
  return `${years} ${years === 1 ? 'year' : 'years'} ago`;
}

interface PlanCardProps {
  plan: Plan;
  isSelected: boolean;
  onClick: () => void;
}

const PlanCard: React.FC<PlanCardProps> = ({ plan, isSelected, onClick }) => {
  const planName = plan.title || plan.name || 'Unnamed Plan';
  const updatedDate = formatRelativeTime(plan.updatedAt || plan.lastUpdated);

  // Branches this PRD's work lives on, each flagged with whether a live worktree
  // exists for it. Keyed on the BRANCH (the stable identity) so the same
  // physical worktree — which surfaces both as a task/source worktree dir-name
  // and as a lattice branch ref — collapses to one entry instead of being
  // double-counted under two different name namespaces.
  //
  // Sources:
  //  - `plan.sourceWorktree` / `task.worktree`: worktrees explicitly tied to this
  //    PRD's work (assignment events) — relevant regardless of ahead-status, so a
  //    fresh/undiverged worktree still surfaces.
  //  - per-ref lattice (`statusByRef`, ADR-0007): pure git, reflecting commits on
  //    a worktree branch. Two filters, both learned the hard way: require
  //    `isWorktree` (a stale non-worktree branch like `backup/pre-rebase-*` is
  //    also ahead of main) AND strictly-ahead-of-launch (every worktree descends
  //    from main, so a task done on the launch ref reads "completed" on every
  //    worktree column too).
  const worktreeBranches = useMemo(() => {
    const rank: Record<string, number> = { not_started: 0, in_progress: 1, completed: 2, superseded: 2 };
    const byBranch = new Map<string, { hasWorktree: boolean; worktreeName?: string }>();
    const add = (branch: string, hasWorktree: boolean, worktreeName?: string) => {
      const prev = byBranch.get(branch);
      byBranch.set(branch, {
        hasWorktree: (prev?.hasWorktree ?? false) || hasWorktree,
        worktreeName: prev?.worktreeName ?? worktreeName,
      });
    };

    if (plan.sourceWorktree) add(plan.sourceWorktree.branch, true, plan.sourceWorktree.name);
    for (const feature of plan.features || []) {
      for (const task of feature.tasks || []) {
        if (task.worktree) add(task.worktree.branch, true, task.worktree.name);
        const cells = task.statusByRef || [];
        const launchRank = rank[cells.find(c => c.isLaunchRef)?.status ?? 'not_started'] ?? 0;
        for (const cell of cells) {
          if (cell.isLaunchRef || !cell.isWorktree) continue;
          if ((rank[cell.status] ?? 0) <= launchRank) continue; // not ahead of where we're looking
          add(cell.ref, true); // lattice refs carry no dir name
        }
      }
    }
    return [...byBranch].map(([branch, v]) => ({ branch, ...v }));
  }, [plan.sourceWorktree, plan.features]);

  // The single worktree the WHOLE PRD was done on, or undefined. "Whole" is
  // strict: EVERY task must resolve its effective status to a worktree (none on
  // the launch ref) AND there is exactly ONE worktree branch in play (which
  // folds in sourceWorktree, so a source on one branch + work on another counts
  // as two). One feature on a worktree while the rest landed on main is PARTIAL
  // — that gets the compact top-right indicator, not the full-width row.
  const planWorktree = useMemo(() => {
    const allTasks = (plan.features ?? []).flatMap((f) => f.tasks ?? []);
    if (allTasks.length === 0 || worktreeBranches.length !== 1) return undefined;
    const allOnWorktree = allTasks.every((t) => deriveEffectiveStatus(t).worktreeRef !== undefined);
    return allOnWorktree ? worktreeBranches[0] : undefined;
  }, [plan.features, worktreeBranches]);

  // Calculate progress from tasks (same logic as PlanDetailsPRD)
  // This ensures sidebar and detailed view are always in sync
  const progress = useMemo(() => {
    const features = plan.features || [];
    const totalTasks = features.reduce((acc, feature) => acc + (feature.tasks?.length || 0), 0);
    // Count by WORKTREE-AWARE effective status so work completed on a worktree
    // counts toward progress (not just commits landed on the launch ref).
    const allTasks = features.flatMap((feature) => feature.tasks ?? []);
    const doneTasks = allTasks
      .map((task) => deriveEffectiveStatus(task).status)
      .filter((s) => s === 'completed' || s === 'superseded').length;

    return totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0;
  }, [plan.features]);

  // Calculate feature count from features array or metadata
  const featureCount = plan.features?.length ?? plan.metadata?.totalFeatures ?? plan.featureCount ?? 0;

  const isComplete = progress === 100;
  // Worktree work can advance progress while the launch-ref plan.status is still
  // not_started, so treat any effective progress as in-progress too.
  const isInProgress = !isComplete && (plan.status === 'in_progress' || progress > 0);
  const isArchived = plan.type === 'archived';

  const variant: StatusVariant = isComplete ? 'done' : isInProgress ? 'in-progress' : 'not-started';
  // The pink→blue progress bar appears whenever there's progress to show — i.e.
  // for active and completed work. A not-started plan shows just its pill.
  const showProgress = isComplete || isInProgress;
  // The blue left accent marks the current SELECTION (not in-progress status);
  // the `.plan-card-surface` hover rules also light it (and the border) on hover.

  return (
    <div
      data-testid={isArchived ? 'archived-card' : 'plan-card'}
      data-selected={isSelected}
      data-status={variant}
      role="button"
      tabIndex={0}
      onClick={onClick}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onClick();
        }
      }}
      className={cn(
        'plan-card-surface lift rise relative block cursor-pointer overflow-hidden rounded-2xl p-4 pl-5 hover:bg-accent/30',
        isSelected && 'plan-card-accent panel',
        isArchived && 'opacity-60',
      )}
    >
      <div className="flex items-start justify-between gap-2">
        <h3 className={cn('display text-[15px] leading-snug line-clamp-2', isInProgress || isSelected ? 'font-semibold' : 'font-medium')}>
          {planName}
        </h3>
        <div className="flex items-center gap-1">
          {/* Partial worktree work (some — not all — features/tasks on worktrees,
              or spread across more than one): a compact top-right branch icon,
              not the full-width row (which is reserved for a whole-PRD worktree). */}
          {!planWorktree && worktreeBranches.length > 0 && (
            <Tooltip>
              <TooltipTrigger asChild>
                <span
                  data-testid="card-worktree-indicator"
                  aria-label="Some work done on worktrees"
                  onClick={(e) => e.stopPropagation()}
                  className="inline-flex flex-shrink-0 items-center justify-center rounded border border-[oklch(0.72_0.13_300)] bg-purple-100 px-1 py-0.5 text-purple-700 dark:border-[oklch(0.55_0.15_300)] dark:bg-purple-900/30 dark:text-purple-300"
                >
                  <GitBranch className="h-3 w-3" />
                </span>
              </TooltipTrigger>
              <TooltipContent>
                <span className="flex flex-col gap-0.5">
                  <span className="font-medium">Some work on worktrees</span>
                  {worktreeBranches.map((b) => (
                    <span key={b.branch} className="flex items-center gap-1">
                      <GitBranch className="h-3 w-3 flex-shrink-0" />
                      {b.branch}
                    </span>
                  ))}
                </span>
              </TooltipContent>
            </Tooltip>
          )}
          {isArchived && <Archive data-testid="archive-icon" className="h-3.5 w-3.5 text-muted-foreground" />}
          {plan.isTheCurrentPlan && <span className="text-sm">⭐</span>}
        </div>
      </div>

      <div className="mt-2.5 flex items-center gap-2">
        <StatusPill variant={variant} label={isComplete ? 'Completed' : undefined} />
        {isInProgress && (
          <span className="mono ml-auto text-[11px] text-muted-foreground">
            {progress}% <span className="font-sans">complete</span>
          </span>
        )}
      </div>

      {showProgress && <GradientProgress value={progress} className="mt-3" />}

      {/* Full-width worktree row under the progress bar (matching FixCard) ONLY
          when the WHOLE PRD was done on one worktree — the prominent treatment is
          earned by all-on-one-worktree work. Partial work uses the compact
          header indicator above instead. */}
      {planWorktree && (
        <div data-testid="card-worktree-row" className="mt-3">
          <WorktreePill branches={[planWorktree]} />
        </div>
      )}

      <div className="mono mt-3 flex items-center justify-between text-[11px] text-muted-foreground">
        <span>{featureCount} <span className="font-sans">{featureCount === 1 ? 'feature' : 'features'}</span></span>
        <span className="font-sans">{updatedDate}</span>
      </div>
    </div>
  );
};

export default PlanCard;