import { useEffect, type CSSProperties } from 'react';
import { GitCommitHorizontal, GitBranch } from 'lucide-react';
import { cn } from '@/lib/utils';
import WorktreeIcon from '../components/WorktreeIcon';
import { deriveEffectiveStatus } from '../utils/effective-task-status';
import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { resolveActiveTab, type TaskTab } from '../utils/task-detail-link';
import { buildPipelinePhases, getReviewFetchSha } from '../utils/pipeline-phases';
import type { TaskRowTask } from '../types';
import RedTab from '../components/RedTab';
import GreenTab from '../components/GreenTab';
import ReviewTab from '../components/ReviewTab';
import CommitsTab from '../components/CommitsTab';

/** Accent colour for a tab's dot/underline — review gates share the review hue. */
function tabColor(tab: TaskTab): string | undefined {
  if (tab === 'commits') return undefined;
  if (tab === 'red') return 'var(--color-phase-red)';
  if (tab === 'green') return 'var(--color-phase-green)';
  return 'var(--color-phase-review)'; // review:<gate>
}

export interface TaskDetailPageProps {
  repoId: string;
  taskId: string;
  /** The resolved task, when found in the workspace — supplies the phase
   *  commit SHAs the tab content fetches diffs for, plus the title and status
   *  shown in the header. */
  task?: TaskRowTask;
  /** The task's 1-based ordinal within its container (feature / fix), for the
   *  `task-{n}` part of the header meta line. */
  taskNumber?: number;
  /** The containing feature or fix id, shown in the header meta line. */
  container?: string;
  /** The raw `?tab=` value from the URL; resolved against the task's pinned
   *  gate-set internally (the legacy `review` maps to the first review gate). */
  tab: string | null;
  /** Switch tabs — the caller writes this to the URL (`?tab=`). */
  onTabChange: (tab: TaskTab) => void;
  /** The repo's configured review pipeline — supplies gate labels for the review
   *  tabs. The gate-set itself comes from the task's pinned `pipelineSnapshot`. */
  reviewPipeline?: readonly PipelineStep[];
  /** Leave the task view, returning to the repo workspace. */
  onBack: () => void;
}

/** Human label for a task's git-derived status, as shown in the header meta. */
const STATUS_LABEL: Record<TaskRowTask['status'], string> = {
  not_started: 'not started',
  in_progress: 'in progress',
  completed: 'done',
  superseded: 'superseded',
};

/** Format an ISO timestamp as e.g. "14 Jun 2026"; empty string if absent/invalid. */
function formatMetaDate(iso?: string): string {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  return new Intl.DateTimeFormat('en-GB', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
  }).format(d);
}

/**
 * The full task detail view — promotes per-task pipeline detail out of the
 * anchored popover into an in-place view with a tab-per-phase bar
 * (Red · Green · Review · Commits). Rendered inside the repo workspace
 * (`RepoDetailPage`) so the workspace data stays warm: the caller owns the URL
 * state (`?task=` / `?tab=`) and drives this controlled component via props.
 * Each tab shares one skeleton (a rail beside a single diff); this shell renders
 * the header, the tab bar and the empty panel frame — the rich per-tab content
 * (failing tests, the green implementation, the review findings + refactor, full
 * diffs) lands in the Red/Green/Review/Commits tab tasks.
 */
export default function TaskDetailPage({
  repoId,
  taskId,
  task,
  taskNumber,
  container,
  tab,
  onTabChange,
  onBack,
  reviewPipeline,
}: TaskDetailPageProps) {
  // Tabs are derived from the same builder the per-task pipeline strip uses, so
  // the detail mirrors the strip: Red, Green, one review tab per pinned gate
  // (from the task's pinned `pipelineSnapshot`, falling back to the configured
  // pipeline), then Commits. The active tab is resolved from the raw `?tab=`.
  const phases = buildPipelinePhases(
    [...(reviewPipeline ?? [])],
    task?.pipelineType,
    task?.pipelineSnapshot,
  );
  const tabs: { key: TaskTab; label: string }[] = [
    ...phases.map((p) => ({ key: p.phase as TaskTab, label: p.label })),
    { key: 'commits' as const, label: 'Commits' },
  ];
  const activeTab = resolveActiveTab(
    tab,
    tabs.map((t) => t.key),
  );
  // Header meta line: `task-{n} · {container} · {status} {date}`, omitting any
  // piece that's absent.
  const statusBit = task
    ? `${STATUS_LABEL[task.status]}${task.completedAt ? ` ${formatMetaDate(task.completedAt)}` : ''}`.trim()
    : '';
  const metaLine = [taskNumber ? `task-${taskNumber}` : null, container || null, statusBit || null]
    .filter(Boolean)
    .join(' · ');

  // The branch (and worktree dir, when it diverges) this task's work lives on —
  // shown fully spelled out in the header's top right. The branch is where the
  // effective status came from (a worktree strictly ahead of the launch ref),
  // falling back to an explicit worktree assignment.
  const worktreeBranch = task ? (deriveEffectiveStatus(task).worktreeRef ?? task.worktree?.branch) : undefined;
  const worktreeName =
    task?.worktree && task.worktree.branch === worktreeBranch ? task.worktree.name : undefined;

  // Escape returns to the workspace — the keyboard equivalent of the backdrop
  // click, so dropping the explicit "Back to repo" button doesn't strand
  // keyboard / assistive-tech users (whom the mouse-only backdrop can't serve).
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onBack();
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [onBack]);

  return (
    // The panel sits on a click-dismiss backdrop: a click that lands on the
    // backdrop itself (outside the `<main>` panel) returns to the workspace, so
    // no explicit "Back to repo" control is needed. The `target === currentTarget`
    // guard keeps clicks that bubble up from inside the panel from closing it.
    <div
      data-testid="task-detail-backdrop"
      role="presentation"
      onClick={(e) => {
        if (e.target === e.currentTarget) onBack();
      }}
      className="grid min-h-0 flex-1 place-items-center overflow-hidden p-6"
    >
      <main
        className="panel rise flex w-full max-w-6xl flex-col overflow-hidden rounded-3xl"
        style={{ height: 'min(86vh, 860px)' }}
      >
        {/* Header — task title, then a meta row pairing the task-N/status text
            (left) with the branch + worktree, right-aligned on the SAME row
            (ADR-0007 / fix: fix-status-head-only-vs-across-refs). */}
        <header className="px-6 pt-4">
          {/* Inline colour, not a `text-*` class: the legacy `.dark h1` rule
              (globals.css "tone down headings") tones headings to a grey and
              out-specifics utility classes — only an inline style (or
              !important) wins, so the title reads as the bright foreground the
              mockups show. */}
          <h1
            className="display mt-1 text-xl font-bold leading-snug"
            style={{ color: 'var(--foreground)' }}
          >
            {task?.description ?? 'Task detail'}
          </h1>

          <div className="mt-1 flex items-center justify-between gap-3">
            {task ? (
              <p data-testid="task-meta" className="mono min-w-0 truncate text-[11px] text-muted-foreground">
                {metaLine}
              </p>
            ) : (
              <p className="mono min-w-0 truncate text-[11px] text-muted-foreground">{taskId}</p>
            )}

            {worktreeBranch && (
              <div
                data-testid="task-detail-worktree"
                className="mono flex flex-shrink-0 items-center gap-3 text-[11px] text-purple-700 dark:text-purple-300"
              >
                <span className="inline-flex items-center gap-1">
                  <GitBranch className="h-3.5 w-3.5 flex-shrink-0" />
                  {worktreeBranch}
                </span>
                {worktreeName && worktreeName !== worktreeBranch && (
                  <span className="inline-flex items-center gap-1">
                    <WorktreeIcon />
                    {worktreeName}
                  </span>
                )}
              </div>
            )}
          </div>
        </header>

        {/* Tab bar — Red, Green, a tab per pinned review gate, then Commits;
            underline accent in the phase colour. */}
        <nav
          role="tablist"
          aria-label="Task phases"
          className="mt-3 flex items-center gap-6 border-b border-border px-6"
        >
          {tabs.map(({ key, label }) => {
            const isActive = key === activeTab;
            const color = tabColor(key);
            const isReview = key.startsWith('review:');
            return (
              <button
                key={key}
                role="tab"
                type="button"
                aria-selected={isActive}
                onClick={() => onTabChange(key)}
                style={isActive && color ? ({ borderColor: color } as CSSProperties) : undefined}
                className={cn(
                  'inline-flex items-center gap-2 border-b-2 py-2.5 text-[13px] font-medium transition-colors',
                  isActive
                    ? 'border-current font-semibold text-foreground'
                    : 'border-transparent text-muted-foreground hover:text-foreground',
                )}
              >
                {key === 'commits' ? (
                  <GitCommitHorizontal className="h-3.5 w-3.5" />
                ) : (
                  <span className="h-2 w-2 rounded-full" style={{ background: color }} />
                )}
                {label}
                {isReview && (
                  <span aria-hidden="true" className="mono text-[10px]" style={{ color }}>
                    · refactor
                  </span>
                )}
              </button>
            );
          })}
        </nav>

        {/* Active phase panel — each tab is a rail beside a single diff. A review
            tab renders its own gate's review (the pinned-but-unrun gates show a
            "not reviewed yet" panel). */}
        <section
          role="tabpanel"
          data-phase={activeTab}
          aria-label={`${activeTab} phase`}
          className="min-h-0 flex-1 overflow-hidden"
        >
          {activeTab === 'red' ? (
            <RedTab repoId={repoId} commitSha={task?.testCommitSha} />
          ) : activeTab === 'green' ? (
            <GreenTab
              repoId={repoId}
              commitSha={task?.commitSha}
              testCommitSha={task?.testCommitSha}
            />
          ) : activeTab === 'commits' ? (
            <CommitsTab repoId={repoId} task={task} />
          ) : (
            (() => {
              const gate = activeTab.slice('review:'.length);
              const rec = task?.reviews?.[gate];
              // Only a gate with an actual review record has something to fetch;
              // a pinned-but-unrun gate passes no SHA so ReviewTab shows its
              // "not reviewed yet" empty state rather than 404-ing on the green
              // commit. The review file is keyed by the reviewed (green) SHA.
              const reviewedSha = rec ? (getReviewFetchSha(task!, gate) ?? task?.commitSha) : undefined;
              return (
                <ReviewTab
                  repoId={repoId}
                  gate={gate}
                  reviewedSha={reviewedSha}
                  refactorCommitSha={rec?.refactorCommitSha}
                />
              );
            })()
          )}
        </section>
      </main>
    </div>
  );
}
