import { useEffect, useState } from 'react';
import { X, Check, Loader2, AlertCircle, GitCommitHorizontal } from 'lucide-react';
import type { TaskRowTask } from '../types';
import { useCommitDiff } from '../hooks/useCommitDiff';
import DiffFileView from './DiffFileView';

/** The pipeline phase a task commit belongs to. */
export type CommitPhase = 'red' | 'green' | 'review' | 'refactor';

/** One commit on a task — its SHA and the phase it landed in. */
export interface TaskCommitRef {
  sha: string;
  phase: CommitPhase;
}

const isReal = (sha?: string): sha is string => !!sha && sha !== 'skipped';

/**
 * Derive a task's commits in pipeline-phase order — red (test:), green
 * (feat:/fix:), the review verdict (review:) for each gate, then the
 * refactor(s) — from the git-projected task's phase SHAs. This is fixed
 * phase-bucket order, not commit time order (with two gates a later mutation
 * review still precedes an earlier refactor). Skipped-RED sentinels and
 * duplicate SHAs (a single commit referenced by more than one field) are
 * dropped, so each commit appears once.
 */
export function deriveTaskCommits(task?: Partial<TaskRowTask>): TaskCommitRef[] {
  if (!task) return [];
  const out: TaskCommitRef[] = [];
  const seen = new Set<string>();
  const add = (phase: CommitPhase, sha?: string) => {
    if (!isReal(sha) || seen.has(sha)) return;
    seen.add(sha);
    out.push({ sha, phase });
  };

  add('red', task.testCommitSha);
  add('green', task.commitSha);
  // The verdict (review:) commit for each gate — reviewedSha is the green SHA
  // (already added), so only reviewSha names a distinct commit.
  for (const rec of Object.values(task.reviews ?? {})) add('review', rec?.reviewSha);
  // Refactors: the per-gate fields, the top-level field, then each gate record.
  add('refactor', task.adversarialRefactorCommitSha);
  add('refactor', task.mutationRefactorCommitSha);
  add('refactor', task.refactorCommitSha);
  for (const rec of Object.values(task.reviews ?? {})) add('refactor', rec?.refactorCommitSha);

  return out;
}

interface CommitMeta {
  message: string;
  date?: string;
}

interface CommitsTabProps {
  repoId: string;
  /** The resolved task whose commits are listed. */
  task?: TaskRowTask;
}

const PHASE_COLOR: Record<CommitPhase, string> = {
  red: 'var(--color-phase-red)',
  green: 'var(--color-phase-green)',
  review: 'var(--color-phase-review)',
  refactor: 'var(--color-phase-refactor)',
};

const PHASE_LABEL: Record<CommitPhase, string> = {
  red: 'Red',
  green: 'Green',
  review: 'Review',
  refactor: 'Refactor',
};

const short = (sha: string) => sha.slice(0, 7);
const subjectOf = (message?: string) => (message ? message.split('\n')[0] : '');

const formatWhen = (iso?: string): string | undefined => {
  if (!iso) return undefined;
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return undefined;
  return d.toLocaleString(undefined, { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
};

function PhaseDot({ phase }: { phase: CommitPhase }) {
  const color = PHASE_COLOR[phase];
  return (
    <span
      className="grid h-5 w-5 flex-none place-items-center rounded-full border"
      style={{
        color,
        background: `color-mix(in oklab, ${color} 16%, transparent)`,
        borderColor: `color-mix(in oklab, ${color} 45%, transparent)`,
      }}
    >
      {phase === 'red' ? (
        <X className="h-3.5 w-3.5" />
      ) : phase === 'green' ? (
        <Check className="h-3.5 w-3.5" />
      ) : (
        <GitCommitHorizontal className="h-3.5 w-3.5" />
      )}
    </span>
  );
}

/**
 * The Commits tab — every commit on the task with its per-commit diff. A rail
 * lists the task's commits in pipeline order (red → green → review → refactor),
 * each with its phase dot, subject (fetched per SHA), short SHA and time;
 * selecting one shows that commit's own changes (sha~1..sha) in the diff pane.
 * The first commit is selected by default. Shares the rail + single-diff
 * skeleton with the Red/Green/Review tabs.
 */
export default function CommitsTab({ repoId, task }: CommitsTabProps) {
  const commits = deriveTaskCommits(task);
  const commitKey = commits.map((c) => c.sha).join(',');

  const [metas, setMetas] = useState<Record<string, CommitMeta>>({});
  const [selectedSha, setSelectedSha] = useState<string | null>(null);
  // Which face of the pane is shown — the per-commit changed files or its full
  // message. Persists across rail selections so you can scan messages
  // commit-to-commit without re-toggling.
  const [view, setView] = useState<'files' | 'message'>('files');

  // Keep a valid default selection as the commit set changes (task switch).
  useEffect(() => {
    setSelectedSha((current) =>
      current && commits.some((c) => c.sha === current) ? current : commits[0]?.sha ?? null,
    );
    // commitKey captures the identity of the commit list.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [commitKey]);

  // Fetch each commit's metadata (subject + date) once per commit set.
  useEffect(() => {
    if (commits.length === 0) {
      setMetas({});
      return;
    }
    let cancelled = false;
    Promise.all(
      commits.map((c) =>
        fetch(`/api/repos/${repoId}/git/commits/${c.sha}`)
          .then((res) => (res.ok ? res.json() : null))
          .then((data: { message?: string; date?: string } | null) =>
            data ? ([c.sha, { message: data.message ?? '', date: data.date }] as const) : null,
          )
          .catch(() => null),
      ),
    ).then((entries) => {
      if (cancelled) return;
      setMetas(Object.fromEntries(entries.filter((e): e is NonNullable<typeof e> => e !== null)));
    });
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [repoId, commitKey]);

  // Only fetch the diff when the Files view is showing it — switching commits
  // while reading messages shouldn't pull diffs that are never rendered.
  const diff = useCommitDiff(repoId, view === 'files' ? selectedSha ?? undefined : undefined);
  const selectedMessage = selectedSha ? metas[selectedSha]?.message : undefined;

  if (commits.length === 0) {
    return (
      <div className="grid h-full place-items-center p-6 text-center">
        <p className="text-sm text-muted-foreground">No commits yet for this task.</p>
      </div>
    );
  }

  return (
    <div className="grid h-full min-h-0 grid-cols-1 lg:grid-cols-[320px_minmax(0,1fr)]">
      {/* Commits rail */}
      <aside className="flex min-h-0 flex-col border-r border-border">
        <div className="flex items-center justify-between px-4 pt-4">
          <p className="eyebrow text-[10px] text-muted-foreground">Commits</p>
          <span className="mono text-[11px] text-muted-foreground">{commits.length}</span>
        </div>

        <div className="mt-3 min-h-0 flex-1 overflow-y-auto pb-3">
          {commits.map((commit) => {
            const isActive = commit.sha === selectedSha;
            const meta = metas[commit.sha];
            const subject = subjectOf(meta?.message) || `${PHASE_LABEL[commit.phase]} commit`;
            const when = formatWhen(meta?.date);
            return (
              <button
                key={commit.sha}
                type="button"
                aria-pressed={isActive}
                onClick={() => setSelectedSha(commit.sha)}
                className="flex w-full gap-3 border-l-2 px-4 py-3 text-left transition-colors hover:bg-muted/40"
                style={
                  isActive
                    ? {
                        borderLeftColor: PHASE_COLOR[commit.phase],
                        background: `color-mix(in oklab, ${PHASE_COLOR[commit.phase]} 12%, transparent)`,
                      }
                    : { borderLeftColor: 'transparent' }
                }
              >
                <PhaseDot phase={commit.phase} />
                <div className="min-w-0 flex-1">
                  <p className="text-[13px] leading-snug">{subject}</p>
                  <p className="mono mt-1 text-[10px] text-muted-foreground">
                    {short(commit.sha)}
                    {when ? ` · ${when}` : ''}
                  </p>
                </div>
              </button>
            );
          })}
        </div>
      </aside>

      {/* Selected commit — its changed files or its full message, behind a
          sub-tab bar. Tabs wire to their panels via aria-controls/labelledby. */}
      <div className="flex min-h-0 flex-col">
        <nav
          role="tablist"
          aria-label="Commit view"
          className="flex items-center gap-5 border-b border-border px-4"
        >
          {([['files', 'Files'], ['message', 'Commit message']] as const).map(([v, label]) => (
            <button
              key={v}
              role="tab"
              type="button"
              id={`tab-commit-${v}`}
              aria-selected={view === v}
              aria-controls={`panel-commit-${v}`}
              onClick={() => setView(v)}
              className={
                view === v
                  ? 'border-b-2 border-current py-2.5 text-[13px] font-semibold text-foreground'
                  : 'border-b-2 border-transparent py-2.5 text-[13px] font-medium text-muted-foreground hover:text-foreground'
              }
            >
              {label}
            </button>
          ))}
        </nav>

        {view === 'files' ? (
          <section
            role="tabpanel"
            id="panel-commit-files"
            aria-labelledby="tab-commit-files"
            data-testid="commits-diff"
            className="tb-diff min-h-0 flex-1 overflow-y-auto"
          >
            {diff.loading && (
              <div className="flex items-center gap-2 p-4 text-sm text-muted-foreground">
                <Loader2 className="h-4 w-4 animate-spin" /> Loading diff…
              </div>
            )}
            {diff.error && (
              <div className="flex items-start gap-2 p-4 text-sm text-red-500">
                <AlertCircle className="mt-0.5 h-4 w-4 flex-none" /> {diff.error}
              </div>
            )}
            {!diff.loading &&
              !diff.error &&
              diff.files.map((file, fileIndex) => (
                <DiffFileView key={`${file.newPath ?? file.oldPath ?? ''}-${fileIndex}`} file={file} />
              ))}
          </section>
        ) : (
          <section
            role="tabpanel"
            id="panel-commit-message"
            aria-labelledby="tab-commit-message"
            data-testid="commit-message"
            className="min-h-0 flex-1 overflow-y-auto p-4"
          >
            {selectedMessage ? (
              <pre className="mono whitespace-pre-wrap break-words text-[13px] leading-relaxed text-foreground">
                {selectedMessage}
              </pre>
            ) : (
              <p className="text-sm text-muted-foreground">No commit message available.</p>
            )}
          </section>
        )}
      </div>
    </div>
  );
}
