import { useState, useEffect, useCallback, type ReactNode } from 'react';
import { Skeleton } from '../components/ui/skeleton';
import { Button } from '../components/ui/button';
import { AlertCircle, Package, RefreshCw, Puzzle, Bot, Webhook, Server, ChevronDown, ChevronRight, Store, ExternalLink } from 'lucide-react';

interface PluginManifest {
  name: string;
  version?: string;
  description?: string;
  author?: {
    name?: string;
    email?: string;
    url?: string;
  };
  keywords?: string[];
  skills?: string;
  agents?: string;
  hooks?: string;
  mcpServers?: string;
}

interface PluginComponents {
  skills: string[];
  agents: string[];
  hasHooks: boolean;
  hasMcp: boolean;
}

interface DiscoveredPlugin {
  name: string;
  version: string;
  description: string;
  scope: 'user' | 'project' | 'local';
  path: string;
  repoPath?: string;
  manifest: PluginManifest;
  components: PluginComponents;
}

interface DiscoveredMarketplace {
  name: string;
  source: string;
  url?: string;
  installLocation: string;
  lastUpdated: string;
  autoUpdate?: boolean;
}

interface PluginsByScope {
  user: DiscoveredPlugin[];
  project: Record<string, DiscoveredPlugin[]>;
  local: Record<string, DiscoveredPlugin[]>;
  marketplaces: DiscoveredMarketplace[];
}

/** Scope chips on the design-system palette — a tinted fill + matching ink,
 *  flipping on .dark via the --color-* tokens (no hard-coded *-100 colours). */
const SCOPE_VAR: Record<string, string> = {
  user: 'var(--color-primary)',
  project: 'var(--color-blue)',
  local: 'var(--color-done)',
};

const scopeLabels: Record<string, string> = {
  user: 'User',
  project: 'Project',
  local: 'Local',
};

function ScopePill({ scope }: { scope: string }) {
  const color = SCOPE_VAR[scope] ?? 'var(--color-blue)';
  return (
    <span
      className="rounded-md px-1.5 py-0.5 text-[11px] font-semibold"
      style={{ color, background: `color-mix(in oklab, ${color} 15%, transparent)` }}
    >
      {scopeLabels[scope] ?? scope}
    </span>
  );
}

/** A bordered count/feature chip used for component summaries and detail tags. */
function Chip({ children }: { children: ReactNode }) {
  return (
    <span className="inline-flex items-center gap-1 rounded-md border border-border px-1.5 py-0.5 text-[11px] text-muted-foreground">
      {children}
    </span>
  );
}

function PluginCard({ plugin }: { plugin: DiscoveredPlugin }) {
  const [expanded, setExpanded] = useState(false);
  const { components } = plugin;
  const hasComponents = components.skills.length > 0 || components.agents.length > 0 || components.hasHooks || components.hasMcp;

  return (
    <div
      data-testid={`plugin-card-${plugin.name}`}
      className="lift rounded-2xl panel p-4 transition-shadow hover:shadow-md"
    >
      <div className="flex items-start justify-between gap-2">
        <div className="flex items-center gap-2 min-w-0">
          <span
            className="grid h-9 w-9 shrink-0 place-items-center rounded-lg"
            style={{ background: 'color-mix(in oklab, var(--color-blue) 14%, transparent)' }}
          >
            <Package className="h-5 w-5" style={{ color: 'var(--color-blue)' }} />
          </span>
          <p className="display truncate text-base font-semibold leading-tight">{plugin.name}</p>
        </div>
        <div className="flex shrink-0 items-center gap-1.5">
          <span className="mono rounded-md border border-border px-1.5 py-0.5 text-[11px] text-muted-foreground">{plugin.version}</span>
          <ScopePill scope={plugin.scope} />
        </div>
      </div>
      {plugin.description && (
        <p className="mt-2 line-clamp-2 text-sm text-muted-foreground">{plugin.description}</p>
      )}

      {/* Component summary */}
      <div className="mt-3 flex flex-wrap gap-1.5">
        {components.skills.length > 0 && (
          <Chip>
            <Puzzle className="h-3 w-3" />
            {components.skills.length} skill{components.skills.length > 1 ? 's' : ''}
          </Chip>
        )}
        {components.agents.length > 0 && (
          <Chip>
            <Bot className="h-3 w-3" />
            {components.agents.length} agent{components.agents.length > 1 ? 's' : ''}
          </Chip>
        )}
        {components.hasHooks && (
          <Chip>
            <Webhook className="h-3 w-3" />
            hooks
          </Chip>
        )}
        {components.hasMcp && (
          <Chip>
            <Server className="h-3 w-3" />
            MCP
          </Chip>
        )}
      </div>

      {/* Expandable details */}
      {hasComponents && (
        <div className="mt-3">
          <button
            onClick={() => setExpanded(!expanded)}
            className="flex items-center gap-1 text-sm text-muted-foreground transition-colors hover:text-foreground"
          >
            {expanded ? <ChevronDown className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
            {expanded ? 'Hide details' : 'Show details'}
          </button>

          {expanded && (
            <div className="mt-3 space-y-2 text-sm">
              {components.skills.length > 0 && (
                <div>
                  <span className="font-medium text-foreground">Skills:</span>
                  <div className="mt-1 flex flex-wrap gap-1">
                    {components.skills.map(skill => (
                      <span key={skill} className="mono rounded-md border border-border px-1.5 py-0.5 text-[11px] text-muted-foreground">
                        /{skill}
                      </span>
                    ))}
                  </div>
                </div>
              )}
              {components.agents.length > 0 && (
                <div>
                  <span className="font-medium text-foreground">Agents:</span>
                  <div className="mt-1 flex flex-wrap gap-1">
                    {components.agents.map(agent => (
                      <span key={agent} className="mono rounded-md border border-border px-1.5 py-0.5 text-[11px] text-muted-foreground">
                        {agent}
                      </span>
                    ))}
                  </div>
                </div>
              )}
              <p className="mono mt-2 text-xs text-subtle">Path: {plugin.path}</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function SectionShell({ title, children }: { title: string; children: ReactNode }) {
  return (
    <section className="rounded-2xl panel p-5 md:p-6">
      <h2 className="display text-base font-semibold">{title}</h2>
      <div className="mt-4">{children}</div>
    </section>
  );
}

function EmptyState({ message }: { message: string }) {
  return (
    <div className="rounded-2xl border border-dashed border-border py-8 text-center text-sm text-muted-foreground">
      {message}
    </div>
  );
}

function PluginScopeSection({
  title,
  plugins,
  emptyMessage
}: {
  title: string;
  plugins: DiscoveredPlugin[];
  emptyMessage: string;
}) {
  return (
    <SectionShell title={title}>
      {plugins.length === 0 ? (
        <EmptyState message={emptyMessage} />
      ) : (
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {plugins.map(plugin => (
            <PluginCard key={`${plugin.scope}-${plugin.path}`} plugin={plugin} />
          ))}
        </div>
      )}
    </SectionShell>
  );
}

function MarketplaceCard({ marketplace }: { marketplace: DiscoveredMarketplace }) {
  const lastUpdated = new Date(marketplace.lastUpdated).toLocaleDateString();

  return (
    <div className="lift rounded-2xl panel p-4 transition-shadow hover:shadow-md">
      <div className="flex items-start justify-between gap-2">
        <div className="flex items-center gap-2 min-w-0">
          <span
            className="grid h-9 w-9 shrink-0 place-items-center rounded-lg"
            style={{ background: 'color-mix(in oklab, var(--color-pink) 14%, transparent)' }}
          >
            <Store className="h-5 w-5" style={{ color: 'var(--color-pink)' }} />
          </span>
          <p className="display truncate text-base font-semibold leading-tight">{marketplace.name}</p>
        </div>
        {marketplace.autoUpdate && <Chip>Auto-update</Chip>}
      </div>
      <div className="mt-3 space-y-2 text-sm">
        <div className="flex items-center gap-2">
          <span className="text-muted-foreground">Source:</span>
          <span className="mono rounded-md border border-border px-1.5 py-0.5 text-[11px] text-muted-foreground">{marketplace.source}</span>
        </div>
        {marketplace.url && (
          <div className="flex items-center gap-2">
            <span className="text-muted-foreground">URL:</span>
            <a
              href={marketplace.url}
              target="_blank"
              rel="noopener noreferrer"
              className="flex items-center gap-1 text-blue hover:underline"
            >
              {marketplace.url.replace(/^https?:\/\//, '').slice(0, 40)}
              <ExternalLink className="h-3 w-3" />
            </a>
          </div>
        )}
        <p className="text-xs text-subtle">Last updated: {lastUpdated}</p>
      </div>
    </div>
  );
}

function MarketplacesSection({ marketplaces }: { marketplaces: DiscoveredMarketplace[] }) {
  return (
    <SectionShell title="Marketplaces">
      {marketplaces.length === 0 ? (
        <EmptyState message="No marketplaces registered" />
      ) : (
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {marketplaces.map(marketplace => (
            <MarketplaceCard key={marketplace.name} marketplace={marketplace} />
          ))}
        </div>
      )}
    </SectionShell>
  );
}

export function PluginsPage() {
  const [pluginsByScope, setPluginsByScope] = useState<PluginsByScope | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const loadPlugins = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await fetch('/api/plugins/by-scope');
      if (!response.ok) {
        throw new Error('Failed to fetch plugins');
      }
      const data = await response.json();
      setPluginsByScope(data);
    } catch (err) {
      console.error('Failed to load plugins:', err);
      setError('Failed to load plugins');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadPlugins();
  }, [loadPlugins]);

  // Flatten project plugins for display
  const projectPlugins = pluginsByScope
    ? Object.values(pluginsByScope.project).flat()
    : [];

  const localPlugins = pluginsByScope
    ? Object.values(pluginsByScope.local).flat()
    : [];

  if (loading) {
    return (
      <div className="mx-auto max-w-7xl p-4 md:p-6 lg:p-8">
        <div data-testid="loading-spinner" className="space-y-4">
          <Skeleton className="h-8 w-48" />
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {[1, 2, 3].map(i => (
              <div key={i} className="rounded-2xl panel p-4">
                <Skeleton className="mb-3 h-9 w-9 rounded-lg" />
                <Skeleton className="h-4 w-3/4" />
                <Skeleton className="mt-2 h-3 w-1/2" />
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="mx-auto max-w-7xl p-4 md:p-6 lg:p-8">
        <div className="flex items-center justify-between gap-4 rounded-2xl border border-destructive/40 bg-destructive/5 p-4">
          <div className="flex items-center gap-2">
            <AlertCircle className="h-5 w-5 text-destructive" />
            <span className="text-sm text-destructive">{error}</span>
          </div>
          <Button onClick={loadPlugins} variant="outline">
            Retry
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-7xl space-y-6 p-4 md:p-6 lg:p-8">
      {/* Scope key with refresh */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex flex-wrap gap-x-6 gap-y-2 text-sm">
          <div className="flex items-center gap-2">
            <ScopePill scope="user" />
            <span className="mono text-xs text-subtle">~/.claude/plugins/</span>
          </div>
          <div className="flex items-center gap-2">
            <ScopePill scope="project" />
            <span className="mono text-xs text-subtle">.claude/plugins/</span>
          </div>
          <div className="flex items-center gap-2">
            <ScopePill scope="local" />
            <span className="mono text-xs text-subtle">.claude/local/plugins/</span>
          </div>
        </div>
        <Button onClick={loadPlugins} variant="outline" size="sm" className="flex items-center gap-2">
          <RefreshCw className="h-4 w-4" />
          Refresh
        </Button>
      </div>

      {/* Marketplaces */}
      <MarketplacesSection marketplaces={pluginsByScope?.marketplaces || []} />

      {/* Plugin sections by scope */}
      <PluginScopeSection
        title="User Plugins"
        plugins={pluginsByScope?.user || []}
        emptyMessage="No user-level plugins installed. Install plugins to ~/.claude/plugins/"
      />

      <PluginScopeSection
        title="Project Plugins"
        plugins={projectPlugins}
        emptyMessage="No project-level plugins found. Add plugins to .claude/plugins/ in your repos"
      />

      <PluginScopeSection
        title="Local Plugins"
        plugins={localPlugins}
        emptyMessage="No local plugins found"
      />
    </div>
  );
}
