import clsx from 'clsx';
import { ChevronDown, ChevronRight } from 'lucide-react';
import type { Feature } from '../types';
import { GradientProgress } from './ui';
import CopyIdButton from './CopyIdButton';
import WorktreePill from './WorktreePill';
import FeatureDetail from './FeatureDetail';
import { formatPrdFeatureSlugPath } from '../utils/task-slug-path';
import {
  deriveEffectiveStatus,
  deriveFeatureEffectiveStatus,
  deriveFeatureWorktreeRef,
} from '../utils/effective-task-status';

interface PlanFeatureRowProps {
  feature: Feature;
  repoId: string;
  prdId?: string;
  expanded: boolean;
  onToggle: () => void;
}

/**
 * One feature in the plans-console accordion (UI Refresh). A recessed
 * panel-flat row that lifts to a panel when open, with a number badge, title,
 * copy-id, a worktree pill, and a right-aligned done/total count plus gradient
 * progress (or a "Not started" pill). Expanding reveals the per-task rows and
 * their commit-pipeline timelines via FeatureDetail; the row's status and
 * counts use the worktree-aware effective status so worktree work counts here.
 */
export function PlanFeatureRow({ feature, repoId, prdId, expanded, onToggle }: PlanFeatureRowProps) {
  const tasks = feature.tasks ?? [];
  const status = deriveFeatureEffectiveStatus(tasks);
  const worktreeRef = deriveFeatureWorktreeRef(tasks);
  // The worktree dir name for that branch (when a task names it), so the
  // feature-header pill's tooltip surfaces branch + worktree like the PRD card,
  // not just the branch.
  const worktreeName = tasks.find((t) => t.worktree?.branch === worktreeRef)?.worktree?.name;
  const slug = prdId ? formatPrdFeatureSlugPath(prdId, feature.id) : undefined;

  const total = tasks.length;
  const completed = tasks.filter((t) => deriveEffectiveStatus(t).status === 'completed').length;
  const superseded = tasks.filter((t) => deriveEffectiveStatus(t).status === 'superseded').length;
  const done = completed + superseded;
  const isDone = status === 'completed' || status === 'superseded';
  const percent = isDone ? 100 : total > 0 ? Math.round((done / total) * 100) : 0;
  const started = status !== 'not_started';

  // The number badge is tinted by status — the brand purple (bg-primary) is the
  // "current phase" accent, reserved for the in-progress feature; done features
  // read neutral, not-started faintest.
  const badgeClass =
    status === 'in_progress'
      ? 'bg-primary text-primary-foreground'
      : status === 'not_started'
        ? 'bg-muted text-subtle'
        : 'bg-muted text-muted-foreground';

  return (
    <section
      data-testid="feature-row"
      data-open={expanded}
      className={clsx('overflow-hidden rounded-2xl', expanded ? 'panel' : 'panel-flat')}
    >
      <div className="px-4 py-3.5">
        <div className="flex items-center gap-2">
          <button
            type="button"
            aria-expanded={expanded}
            onClick={onToggle}
            className="flex min-w-0 items-center gap-3 text-left"
          >
            {expanded ? (
              <ChevronDown className="h-4 w-4 shrink-0 text-subtle" />
            ) : (
              <ChevronRight className="h-4 w-4 shrink-0 text-subtle" />
            )}
            <span className={clsx('grid h-7 w-7 shrink-0 place-items-center rounded-lg mono text-xs font-bold', badgeClass)}>
              {feature.number}
            </span>
            <span className="truncate font-medium leading-snug">{feature.title}</span>
          </button>

          {slug && <CopyIdButton value={slug} kind="Feature" className="shrink-0" />}

          <div className="ml-auto flex shrink-0 items-center gap-3 pl-2">
            <span className="mono text-xs text-muted-foreground">
              {total > 0 ? `${done}/${total} tasks` : 'No tasks'}
            </span>
            {started ? (
              <>
                <GradientProgress value={percent} className="hidden w-20 sm:block" />
                <span className="mono text-sm font-semibold text-blue">{percent}%</span>
              </>
            ) : (
              <span className="inline-flex items-center gap-1.5 rounded-full bg-muted px-2 py-0.5 text-[11px] font-medium text-muted-foreground">
                <span className="h-1.5 w-1.5 rounded-full border border-border-strong" />
                Not started
              </span>
            )}
          </div>
        </div>

        {/* Worktree marker on its own second row, indented under the feature
            title (past the chevron + number badge), so it doesn't crowd the
            title/progress row (fix: fix-status-head-only-vs-across-refs). */}
        {worktreeRef && (
          <div data-testid="feature-worktree-row" className="mt-2 pl-[3.5rem]">
            <WorktreePill branches={[{ branch: worktreeRef, hasWorktree: true, worktreeName }]} />
          </div>
        )}
      </div>

      {expanded && (
        <div className="border-t border-border">
          <FeatureDetail feature={feature} repoId={repoId} planId={prdId} />
        </div>
      )}
    </section>
  );
}

export default PlanFeatureRow;
