import React from 'react';

/**
 * The shared "W" worktree glyph — marks that a live worktree exists for a
 * branch. Used both as the WorktreePill decoration and in tooltip rows so the
 * worktree axis reads the same everywhere (distinct from the GitBranch icon
 * that denotes the branch axis).
 */
const WorktreeIcon: React.FC<React.ComponentProps<'span'>> = ({ className = '', ...props }) => (
  <span
    className={`inline-flex items-center justify-center h-3.5 w-3.5 flex-shrink-0 rounded-full bg-purple-600/20 dark:bg-purple-400/20 text-[9px] font-bold leading-none ${className}`}
    {...props}
  >
    W
  </span>
);

export default WorktreeIcon;
