import React from 'react';
import type { ObservedLens, ObservedSeverity } from '../utils/quality-observed';

const SEVERITY_COLOR: Record<ObservedSeverity, string> = {
  critical: 'var(--color-phase-red)',
  major: 'var(--color-phase-red)',
  minor: 'var(--color-warn)',
  info: 'var(--color-border-strong)',
};

/** Count label coloured by the sharpest finding in the lens. */
function countTone(lens: ObservedLens): string {
  if (lens.count === 0) return 'var(--color-done)';
  const sharpest = lens.findings[0]?.severity ?? 'info';
  return SEVERITY_COLOR[sharpest];
}

function LensCard({ lens }: { lens: ObservedLens }) {
  return (
    <div data-testid={`observed-lens-${lens.key}`} className="rounded-2xl border border-border bg-muted/30 p-4">
      <div className="flex items-center justify-between">
        <span className="flex items-center gap-2 text-sm font-semibold">
          <span aria-hidden>{lens.emoji}</span>
          {lens.label}
        </span>
        <span className="mono text-xs" style={{ color: countTone(lens) }}>
          {lens.count === 0 ? 'clean' : `${lens.count} ${lens.count === 1 ? 'finding' : 'findings'}`}
        </span>
      </div>
      {lens.count === 0 ? (
        <p className="mt-3 text-sm text-muted">No concerns this run.</p>
      ) : (
        <ul className="mt-3 space-y-2">
          {lens.findings.map((finding, i) => (
            <li key={`${finding.message}-${i}`} className="flex items-start gap-2.5">
              <span
                className="mt-0.5 rounded px-1.5 py-0.5 text-[10px] font-semibold"
                style={{
                  color: SEVERITY_COLOR[finding.severity],
                  background: `color-mix(in oklab, ${SEVERITY_COLOR[finding.severity]} 13%, transparent)`,
                }}
              >
                {finding.severity}
              </span>
              <span className="min-w-0">
                <span className="block text-sm leading-snug">{finding.message}</span>
                {finding.location && (
                  <span className="mono text-[11px] text-subtle">{finding.location}</span>
                )}
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/**
 * The Quality "Observed" section — reviewer-agent findings grouped by lens,
 * severity-tagged. Judgement, not a score.
 */
export const QualityObserved: React.FC<{ lenses: ReadonlyArray<ObservedLens> }> = ({ lenses }) => (
  <section data-testid="quality-observed">
    <h2 className="display text-base font-semibold">Observed</h2>
    <p className="text-xs text-muted">What the reviewer agents noticed — judgement, not a score.</p>
    <div className="mt-3 space-y-3">
      {lenses.map((lens) => (
        <LensCard key={lens.key} lens={lens} />
      ))}
    </div>
  </section>
);
